// Shared GMSH display companion for axisymmetric validation examples.
// Use with any high-order .msh output from this directory.
Mesh.NumSubEdges = 4;
// Merge "<result>.msh";

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  derive_quad_q1_henrotte.wls

  Derive closed-form 4x4 element matrices for the FEMM/Henrotte axisymmetric
  Q1 element on an axis-aligned rectangle in (r, z).

  Basis (Q1 in s = r^2 reference coords):
      phi(r, z) = a + b*s + c*z + d*s*z      where s = r^2

  Nodes: (s_a, z_a), (s_b, z_a), (s_b, z_b), (s_a, z_b)  with s_a = r_a^2, s_b = r_b^2

  Outputs:
    - Mz: stiffness from B_z component                  (b, d coefficients)
    - Mr: stiffness from B_r component (with log terms) (c, d coefficients)
    - M_sigma: sigma mass matrix in V coords            (full 4x4)

  Energy form:
    W_z = (1/(2 mu_z)) Integrate( B_z^2, 2 pi r dr dz )    with B_z = (b + d z)/pi
    W_r = (1/(2 mu_r)) Integrate( B_r^2, 2 pi r dr dz )    with B_r = -(c + d s)/(2 pi sqrt(s))

  Useful change of variables: 2 pi r dr dz = pi ds dz
*)

Print["=== Deriving FEMM/Henrotte Q1 axis-aligned rectangle element matrices ==="];
Print[""];

(* Symbols *)
ClearAll[a, b, c, d, sa, sb, za, zb, ra, rb, muR, muZ, sigma];

(* Phi interpolation: linear in (s, z), bilinear including s*z term *)
phi[s_, z_, a_, b_, c_, d_] := a + b s + c z + d s z;

(* Nodal values *)
phi0 = phi[sa, za, a, b, c, d];  (* node 0: (sa, za) *)
phi1 = phi[sb, za, a, b, c, d];  (* node 1: (sb, za) *)
phi2 = phi[sb, zb, a, b, c, d];  (* node 2: (sb, zb) *)
phi3 = phi[sa, zb, a, b, c, d];  (* node 3: (sa, zb) *)

(* Solve coefficients (a,b,c,d) in terms of nodal values phi0..phi3 *)
sol = Solve[{
    p0 == phi0, p1 == phi1, p2 == phi2, p3 == phi3
  }, {a, b, c, d}][[1]];

aSol = a /. sol;
bSol = b /. sol;
cSol = c /. sol;
dSol = d /. sol;

Print["a = ", FullSimplify[aSol]];
Print["b = ", FullSimplify[bSol]];
Print["c = ", FullSimplify[cSol]];
Print["d = ", FullSimplify[dSol]];
Print[""];

(* Field components *)
(* B_z = (1/(2 pi r)) d phi/dr = (1/(2 pi r)) * 2 r * d phi/ds = d phi/ds / pi *)
(* For phi = a + b s + c z + d s z, d phi/ds = b + d z, so B_z = (b + d z)/pi *)
(* B_r = -(1/(2 pi r)) d phi/dz = -(c + d s)/(2 pi sqrt(s)) *)

Bz[s_, z_] := (b + d z)/Pi;
Br[s_, z_] := -(c + d s)/(2 Pi Sqrt[s]);

(* Energy: W = (1/2)(B_z^2/mu_z + B_r^2/mu_r) integrated over 2 pi r dr dz = pi ds dz *)
(* Integration limits: s in [sa, sb], z in [za, zb] *)

(* W_z integrand: (B_z^2 / mu_z) * pi ds dz / 2 *)
(*    = (1/(2 mu_z))((b + d z)/pi)^2 * pi ds dz *)
(*    = (b + d z)^2 / (2 pi mu_z) ds dz *)

Wz = Integrate[
  (b + d z)^2 / (2 Pi muZ),
  {s, sa, sb}, {z, za, zb}
];
Wz = FullSimplify[Wz];
Print["W_z (energy from B_z), in (b, d) coefficients:"];
Print[Wz];
Print[""];

(* W_r integrand: (B_r^2 / mu_r) * pi ds dz / 2 *)
(*    = (1/(2 mu_r)) * (c + d s)^2 / (4 pi^2 s) * pi ds dz *)
(*    = (c + d s)^2 / (8 pi mu_r s) ds dz *)

Wr = Integrate[
  (c + d s)^2 / (8 Pi muR s),
  {s, sa, sb}, {z, za, zb}
];
Wr = FullSimplify[Wr];
Print["W_r (energy from B_r), in (c, d) coefficients:"];
Print[Wr];
Print[""];

(* Total energy in coefficients *)
W = Wz + Wr;

(* Substitute coefficients back to (phi0, phi1, phi2, phi3) *)
W_phi = W /. {a -> aSol, b -> bSol, c -> cSol, d -> dSol};
W_phi = FullSimplify[W_phi];

(* Differentiate to get element matrix in phi coords *)
phiVars = {p0, p1, p2, p3};
M_phi = Table[D[D[W_phi, phiVars[[i]]], phiVars[[j]]], {i, 1, 4}, {j, 1, 4}];
M_phi = FullSimplify[M_phi];

Print["Element matrix M_phi (in phi nodal value coords):"];
Print[MatrixForm[M_phi]];
Print[""];

(* Convert to V coords: phi_j = 2 pi r_j V_j  =>  V_j = phi_j / (2 pi r_j)  *)
(* M_V = T . M_phi . T  where  T_jj = 2 pi r_j *)
T = DiagonalMatrix[{2 Pi ra, 2 Pi rb, 2 Pi rb, 2 Pi ra}];
M_V = T . M_phi . T;
M_V = FullSimplify[M_V];

Print["Element matrix M_V (in V = A_phi nodal coords):"];
Print[MatrixForm[M_V]];
Print[""];

(* Substitute sa = ra^2, sb = rb^2 *)
M_V_r = M_V /. {sa -> ra^2, sb -> rb^2};
M_V_r = FullSimplify[M_V_r, Assumptions -> {ra > 0, rb > ra, zb > za}];
Print["Element matrix M_V (with sa=ra^2, sb=rb^2):"];
Print[MatrixForm[M_V_r]];
Print[""];

(* Sigma mass matrix in V coords *)
(* W_sigma = (sigma/2) Integrate( A_phi^2, 2 pi r dr dz ) *)
(*         = (sigma/2) Integrate( phi^2 / (2 pi r)^2, 2 pi r dr dz ) *)
(*         = (sigma/(8 pi^2)) Integrate( phi^2 / r * 2 dr dz ) *)
(*         = (sigma/(4 pi^2)) Integrate( phi^2 / r dr dz ) *)
(*  In s coords: dr = ds/(2 sqrt(s)), so dr/r = ds/(2 s) *)
(*         = (sigma/(8 pi^2)) Integrate( phi^2 / s ds dz ) *)
(*  Wait: phi^2 / r * dr * dz = phi^2 * (1/r) * (ds/(2 r)) * dz = phi^2 * ds*dz/(2 r^2) = phi^2 * ds*dz/(2 s) *)
(*  So W_sigma = (sigma/(4 pi^2)) Integrate[phi^2 / (2 s) ds dz] = (sigma/(8 pi^2)) Integrate[phi^2/s ds dz] *)

Print["Computing sigma mass matrix..."];
phiSym[s_, z_] := a + b s + c z + d s z;
WsigCoef = Integrate[
  sigma * phiSym[s, z]^2 / (8 Pi^2 s),
  {s, sa, sb}, {z, za, zb}
];
WsigCoef = FullSimplify[WsigCoef];
WsigPhi = WsigCoef /. {a -> aSol, b -> bSol, c -> cSol, d -> dSol};
WsigPhi = FullSimplify[WsigPhi];

MsigPhi = Table[D[D[WsigPhi, phiVars[[i]]], phiVars[[j]]], {i, 1, 4}, {j, 1, 4}];
MsigPhi = FullSimplify[MsigPhi];

MsigV = T . MsigPhi . T;
MsigV = FullSimplify[MsigV];
MsigV_r = MsigV /. {sa -> ra^2, sb -> rb^2};
MsigV_r = FullSimplify[MsigV_r, Assumptions -> {ra > 0, rb > ra, zb > za, sigma > 0, muR > 0, muZ > 0}];

Print["Sigma mass matrix M_sigma_V (rb > ra > 0):"];
Print[MatrixForm[MsigV_r]];
Print[""];

(* Numerical sanity check: pick concrete values, evaluate, verify symmetry/PSD *)
testRules = {ra -> 1*^-3, rb -> 2*^-3, za -> 0, zb -> 1*^-3,
             muR -> 4 Pi*^-7, muZ -> 4 Pi*^-7, sigma -> 5.8*^7};

K_test = N[M_V_r /. testRules];
M_test = N[MsigV_r /. testRules];

Print["Numerical test (ra=1mm, rb=2mm, za=0, zb=1mm, mu=mu0, sigma=Cu):"];
Print["K_test = ", MatrixForm[Chop[K_test]]];
Print["M_test = ", MatrixForm[Chop[M_test]]];
Print["K symmetric? ", Norm[K_test - Transpose[K_test]] < 1*^-15];
Print["M symmetric? ", Norm[M_test - Transpose[M_test]] < 1*^-15];
Print["K eigenvalues: ", Eigenvalues[K_test]];
Print["M eigenvalues: ", Eigenvalues[M_test]];

(* Export results: structured association *)
result = <|
  "M_V_general" -> ToString[M_V_r, InputForm],
  "M_sigma_V_general" -> ToString[MsigV_r, InputForm],
  "K_test_numerical" -> Chop[K_test],
  "M_test_numerical" -> Chop[M_test],
  "test_params" -> testRules
|>;
Export["W:/30_CauerLadderNetwork/2026_04_01_\:9577\:65b9\:5f62CLN/axifem/quad_q1_henrotte_matrices.json", result, "JSON"];
Print[""];
Print["Saved: quad_q1_henrotte_matrices.json"];

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  derive_quad_q2_henrotte.wls

  COEFFICIENT-FORM derivation: output only K_phi[i,j] and M_sigma_phi[i,j]
  in the monomial basis (no Vandermonde substitution). C++ runtime computes
  Vandermonde inverse and assembles the nodal/V-DOF matrices.

  Why: substituting the symbolic Vandermonde inverse into the energy creates
  expression explosion. Doing the inversion numerically at runtime is cheap
  (LU on 9x9 ~ microseconds) and keeps the symbolic part compact.

  Convention: Hessian-of-W (matches axifem_quad.py:274 reference).
  W_mag = (1/(2 mu)) Integrate(|grad A_phi|^2, 2 pi r dr dz)
        = Integrate(p_s^2/(2 pi muZ) + p_z^2/(8 pi muR s), ds dz)  for p = phi
  W_kin = (sigma/2) Integrate(A_phi^2, 2 pi r dr dz)
        = sigma/(8 pi) Integrate(phi^2/s, ds dz)
  Hessian K_ij = d^2 W_mag / dc_i dc_j = 2 * (W coefficient) for the matrix
  representation K v = lambda M v (same for M).

  GENERAL case (sa > 0):
    Basis = 9 monomials  m[i] = {1, s, s^2, z, sz, s^2 z, z^2, sz^2, s^2 z^2}
    K_phi[i,j] = Integrate(
        d m[i]/ds * d m[j]/ds / (Pi muZ)
      + d m[i]/dz * d m[j]/dz / (4 Pi muR s),
      {s, sa, sb}, {z, za, zb})            (Hessian = 2 x W coefficient)
    M_sigma_phi[i,j] = Integrate(
        m[i] * m[j] * sigma / (4 Pi s),
      {s, sa, sb}, {z, za, zb})            (Hessian = 2 x W coefficient)

  AXIS case (sa = 0):
    Restricted basis (6 monomials, all proportional to s):
      ma[i] = {s, s^2, sz, s^2 z, sz^2, s^2 z^2}
    Same integral formulas with sa = 0.  No 1/s singularity since basis ~ s.

  Output JSON contains 81 + 81 + 36 + 36 = 234 expressions in InputForm.
  C++ side parses these via a tiny Python codegen.
*)

Print["=== Q2 Henrotte K_phi / M_sigma_phi (coefficient form) ==="];
Print[""];
$startTime = AbsoluteTime[];

ClearAll[s, z, sa, sb, za, zb, muR, muZ, sigma];

(* === GENERAL: 9 monomials === *)
mons = {1, s, s^2, z, s z, s^2 z, z^2, s z^2, s^2 z^2};

Print["[GEN] Computing K_phi (9x9, symbolic integrals)..."];
$t0 = AbsoluteTime[];
KphiG = Table[
  Module[{mi = mons[[i]], mj = mons[[j]], dmis, dmjs, dmiz, dmjz, intK, intM},
    dmis = D[mi, s]; dmjs = D[mj, s];
    dmiz = D[mi, z]; dmjz = D[mj, z];
    intK = Integrate[dmis * dmjs / (Pi muZ),
                     {s, sa, sb}, {z, za, zb},
                     Assumptions -> {sb > sa > 0, zb > za}];
    intM = Integrate[dmiz * dmjz / (4 Pi muR s),
                     {s, sa, sb}, {z, za, zb},
                     Assumptions -> {sb > sa > 0, zb > za}];
    Expand[intK + intM]
  ],
  {i, 1, 9}, {j, 1, 9}];
Print["    done ", Round[AbsoluteTime[] - $t0, 0.1], " s"];

Print["[GEN] Computing M_sigma_phi (9x9)..."];
$t0 = AbsoluteTime[];
MsigPhiG = Table[
  Expand@Integrate[mons[[i]] * mons[[j]] * sigma / (4 Pi s),
                   {s, sa, sb}, {z, za, zb},
                   Assumptions -> {sb > sa > 0, zb > za, sigma > 0}],
  {i, 1, 9}, {j, 1, 9}];
Print["    done ", Round[AbsoluteTime[] - $t0, 0.1], " s"];

(* Numeric sanity for general case *)
testRulesG = {sa -> 1*10^-6, sb -> 4*10^-6, za -> 0, zb -> 1*10^-3,
              muR -> 4*Pi*10^-7, muZ -> 4*Pi*10^-7, sigma -> 5.8*10^7};
KphiGnum = N[KphiG /. testRulesG];
MsigPhiGnum = N[MsigPhiG /. testRulesG];
Print["  GEN K_phi symmetric? ", N[Norm[KphiGnum - Transpose[KphiGnum]] / Norm[KphiGnum]] < 1*10^-12];
Print["  GEN M_sigma_phi symmetric? ", N[Norm[MsigPhiGnum - Transpose[MsigPhiGnum]] / Norm[MsigPhiGnum]] < 1*10^-12];
Print["  GEN K_phi[2,2] = ", KphiG[[2, 2]]];

(* === AXIS: 6 restricted monomials === *)
monsA = {s, s^2, s z, s^2 z, s z^2, s^2 z^2};

Print[""];
Print["[AXIS] Computing K_phi_axis (6x6) at sa=0..."];
$t0 = AbsoluteTime[];
KphiA = Table[
  Module[{mi = monsA[[i]], mj = monsA[[j]], dmis, dmjs, dmiz, dmjz, intK, intM},
    dmis = D[mi, s]; dmjs = D[mj, s];
    dmiz = D[mi, z]; dmjz = D[mj, z];
    intK = Integrate[dmis * dmjs / (Pi muZ),
                     {s, 0, sb}, {z, za, zb},
                     Assumptions -> {sb > 0, zb > za}];
    (* 1/s singularity gone: dmiz, dmjz both have factor s, so dmiz*dmjz/s is polynomial *)
    intM = Integrate[dmiz * dmjz / (4 Pi muR s),
                     {s, 0, sb}, {z, za, zb},
                     Assumptions -> {sb > 0, zb > za}];
    Expand[intK + intM]
  ],
  {i, 1, 6}, {j, 1, 6}];
Print["    done ", Round[AbsoluteTime[] - $t0, 0.1], " s"];

Print["[AXIS] Computing M_sigma_phi_axis (6x6)..."];
$t0 = AbsoluteTime[];
MsigPhiA = Table[
  Expand@Integrate[monsA[[i]] * monsA[[j]] * sigma / (4 Pi s),
                   {s, 0, sb}, {z, za, zb},
                   Assumptions -> {sb > 0, zb > za, sigma > 0}],
  {i, 1, 6}, {j, 1, 6}];
Print["    done ", Round[AbsoluteTime[] - $t0, 0.1], " s"];

testRulesA = {sb -> 4*10^-6, za -> 0, zb -> 1*10^-3,
              muR -> 4*Pi*10^-7, muZ -> 4*Pi*10^-7, sigma -> 5.8*10^7};
KphiAnum = N[KphiA /. testRulesA];
MsigPhiAnum = N[MsigPhiA /. testRulesA];
Print["  AXIS K_phi symmetric? ", N[Norm[KphiAnum - Transpose[KphiAnum]] / Norm[KphiAnum]] < 1*10^-12];
Print["  AXIS M_sigma_phi symmetric? ", N[Norm[MsigPhiAnum - Transpose[MsigPhiAnum]] / Norm[MsigPhiAnum]] < 1*10^-12];

(* === Output expressions for codegen === *)
Print[""];
Print["=== Saving symbolic matrices (InputForm strings) ==="];

(* Convert each entry to InputForm string. Avoid SetDelayed pattern function. *)
KphiGstrings = Flatten[Table[ToString[InputForm[KphiG[[i, j]]]], {i, 1, 9}, {j, 1, 9}]];
MsigPhiGstrings = Flatten[Table[ToString[InputForm[MsigPhiG[[i, j]]]], {i, 1, 9}, {j, 1, 9}]];
KphiAstrings = Flatten[Table[ToString[InputForm[KphiA[[i, j]]]], {i, 1, 6}, {j, 1, 6}]];
MsigPhiAstrings = Flatten[Table[ToString[InputForm[MsigPhiA[[i, j]]]], {i, 1, 6}, {j, 1, 6}]];

Print["  K_phi_general_strings type = ", Head[KphiGstrings], ", length = ", Length[KphiGstrings]];
Print["  K_phi_general_strings[[2]] = ", KphiGstrings[[2]]];

result = <|
  "monomials_general" ->
    "{1, s, s^2, z, s*z, s^2*z, z^2, s*z^2, s^2*z^2}",
  "monomials_axis" ->
    "{s, s^2, s*z, s^2*z, s*z^2, s^2*z^2}",
  "node_order_general" ->
    "0:(sa,za) 1:(sb,za) 2:(sb,zb) 3:(sa,zb) 4:(sm,za) 5:(sb,zm) 6:(sm,zb) 7:(sa,zm) 8:(sm,zm); sm=(sa+sb)/2, zm=(za+zb)/2",
  "node_order_axis" ->
    "0:(sb,za) 1:(sb,zb) 2:(sm,za) 3:(sb,zm) 4:(sm,zb) 5:(sm,zm); sm=sb/2",
  "K_phi_general_strings" -> KphiGstrings,
  "M_sigma_phi_general_strings" -> MsigPhiGstrings,
  "K_phi_axis_strings" -> KphiAstrings,
  "M_sigma_phi_axis_strings" -> MsigPhiAstrings,
  "test_params_general" -> "sa=1e-6, sb=4e-6, za=0, zb=1e-3, mu0, sigma_Cu",
  "test_params_axis" -> "sb=4e-6, za=0, zb=1e-3, mu0, sigma_Cu"
|>;
(* Save numerical test matrices to separate JSON, plain numbers only *)
KphiGtest = N[Flatten[KphiGnum]];
MsigPhiGtest = N[Flatten[MsigPhiGnum]];
KphiAtest = N[Flatten[KphiAnum]];
MsigPhiAtest = N[Flatten[MsigPhiAnum]];
testResults = <|
  "K_phi_general_test_flat" -> KphiGtest,
  "M_sigma_phi_general_test_flat" -> MsigPhiGtest,
  "K_phi_axis_test_flat" -> KphiAtest,
  "M_sigma_phi_axis_test_flat" -> MsigPhiAtest
|>;
Export["W:/30_CauerLadderNetwork/2026_04_01_\:9577\:65b9\:5f62CLN/axifem/quad_q2_henrotte_matrices_test.json", testResults, "JSON"];
Export["W:/30_CauerLadderNetwork/2026_04_01_\:9577\:65b9\:5f62CLN/axifem/quad_q2_henrotte_matrices.json", result, "JSON"];
Print["Saved: quad_q2_henrotte_matrices.json"];
Print[""];
Print["Total elapsed: ", Round[AbsoluteTime[] - $startTime, 0.1], " s"];

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  bem_cln_2cuboid_3D.wls

  Phase 3 Task B foundation: rigorous 3D 2-cuboid BEM-CLN assembly.
  Extends the Phase 2.5 polarizability framework from 2D infinite
  cylinders to 3D finite cuboids, using the cuboid Foster eigenmode
  decomposition (cuboid3D_schur_F.wls building block) and the 3D
  dipole-dipole Green's function.

  Per-cuboid building block (scalar diffusion model, V.B journal):
    Y_cuboid(s) = sigma * Sum_{m,n,p odd} g^2_mnp / (1 + s tau_mnp)
    g^2_mnp     = 512 a b c / ((mnp)^2 pi^6)
    lambda_mnp  = (m pi/a)^2 + (n pi/b)^2 + (p pi/c)^2
    tau_mnp     = mu sigma / lambda_mnp

  Schur-F per-cuboid:
    Y_cuboid_S(s) = Y_cuboid_N(s) + K_SIBC^(cuboid) sqrt(s) / (s + d_param)
    K_SIBC^(cuboid) = 2 (ab + bc + ca) sqrt(sigma/mu)

  Polarizability for 3D cuboid (volume susceptibility):
    alpha_3D(s) = V * (1 - Y_cuboid(s) / (sigma V))
                = V - Y_cuboid(s) / sigma
  Limits:
    alpha(0) = 0           (DC, no eddy currents)
    alpha(inf) = V         (PEC, full volume excluded)

  3D BEM-CLN coupling (3D dipole-dipole Green's function):
    A point dipole m_y at origin produces dB_y at distance D along x:
      dB_y = -(mu_0 / (4 pi D^3)) m_y
    For two cuboids n=1, 2 with c_n = alpha(s) B^local_n:
      B^local_n = B_0 - sum_{m != n} (mu_0 / (4 pi D_nm^3)) c_m
    System:
      (I + alpha(s) G_3D) c = alpha(s) B_0 1_vec
      G_ij = mu_0 / (4 pi D_ij^3)  for i != j, 0 on diagonal
    Note the +sign of alpha G (opposite to 2D's -sign), reflecting
    the destructive 3D dipole-dipole interaction (3 cos^2 theta - 1
    angular factor).

  Total polarizability: alpha_total = sum c_n / B_0.

  Run: wolframscript -file bem_cln_2cuboid_3D.wls
*)

ClearAll[a, b, c, sigma, mu, dParam, basisN];

a       = 5*^-3;
b       = 2*^-3;
c       = 1*^-3;
sigma   = 5.80*^7;
mu      = 4 Pi 1*^-7;
dParam  = 2 Pi 1*^5;
basisN  = 3;

VCub    = a b c;
SCub    = 2 (a b + b c + c a);
KsibcCub = SCub Sqrt[sigma/mu];

Print["=== bem_cln_2cuboid_3D.wls ==="];
Print["3D 2-cuboid BEM-CLN: rigorous polarizability framework"];
Print["Cuboid: ", a 1000, "x", b 1000, "x", c 1000, " mm Cu"];
Print["  V = ", N[VCub, 6], " m^3"];
Print["  S = ", N[SCub, 6], " m^2"];
Print["  K_SIBC^(cuboid) = S sqrt(sigma/mu) = ", N[KsibcCub, 6]];
Print[""];

(* === Per-cuboid Foster eigenmode building block ======================== *)
Mmax = 13;
modeList = Flatten[Table[{m, n, p},
  {m, 1, Mmax, 2}, {n, 1, Mmax, 2}, {p, 1, Mmax, 2}], 2];
Nmodes = Length[modeList];

g2MNP[m_, n_, p_] := 512 a b c / ((m n p)^2 Pi^6);
lambdaMNP[m_, n_, p_] := (m Pi/a)^2 + (n Pi/b)^2 + (p Pi/c)^2;
tauMNP[m_, n_, p_]    := mu sigma / lambdaMNP[m, n, p];

g2Vec  = N[Table[g2MNP[mn[[1]], mn[[2]], mn[[3]]], {mn, modeList}], 30];
tauVec = N[Table[tauMNP[mn[[1]], mn[[2]], mn[[3]]], {mn, modeList}], 30];

(* Foster Y_cuboid(s) *)
YcubFoster[s_] := sigma Total[g2Vec / (1 + s tauVec)];

(* Schur-F Y_cuboid *)
YcubSchur[s_] := YcubFoster[s] + KsibcCub Sqrt[s] / (s + dParam);

(* Polarizability *)
alphaCubFoster[s_] := VCub - YcubFoster[s] / sigma;
alphaCubSchur[s_]  := VCub - YcubSchur[s] / sigma;

(* Sanity: DC and PEC limits *)
Print["Per-cuboid alpha(s) sanity:"];
Print["  Y_cuboid(0) Foster   = ", N[YcubFoster[0], 8],
      "  (target sigma V = ", N[sigma VCub, 8], ")"];
Print["  alpha(0)             = ", N[Re[alphaCubFoster[I 2 Pi 0.01]], 8]];
Print["  alpha(inf) Foster    = ", N[Re[alphaCubFoster[I 2 Pi 1*^14]], 8],
      "  (target V = ", N[VCub, 8], ")"];
Print["  alpha(inf) Schur     = ", N[Re[alphaCubSchur[I 2 Pi 1*^14]], 8]];
Print[""];

(* === 3D BEM-CLN coupling =============================================== *)
(* G_ij = mu_0 / (4 pi D_ij^3) for i != j *)
gCoupling3D[D_] := mu / (4 Pi D^3);

coupling3DMatrix[Nc_, D_] := Table[
  If[i == j, 0, gCoupling3D[Abs[i - j] D]],
  {i, 1, Nc}, {j, 1, Nc}];

solveBemCLN3D[s_, Nc_, D_, alphaFun_] := Module[
  {alf, G, sys, rhs, cvec, ones},
  alf  = alphaFun[s];
  G    = coupling3DMatrix[Nc, D];
  ones = ConstantArray[1, Nc];
  sys  = IdentityMatrix[Nc] + alf G;     (* I + alpha G (3D sign) *)
  rhs  = alf ones;
  cvec = LinearSolve[sys, rhs];
  Total[cvec]
];

alphaTotal3DFoster[s_, Nc_, D_] := solveBemCLN3D[s, Nc, D, alphaCubFoster];
alphaTotal3DSchur[s_, Nc_, D_]  := solveBemCLN3D[s, Nc, D, alphaCubSchur];

(* === Verification: 2-cuboid pair at various D ========================== *)
Print["3D 2-cuboid BEM-CLN: alpha_total(s, D) at f = 10^6 Hz"];
Print[""];
Print[StringPadRight["D [mm]", 10] <>
      StringPadRight["alpha (per cuboid)", 22] <>
      StringPadRight["alpha_total (Foster)", 22] <>
      "alpha_total/(2 alpha)"];
Print[StringRepeat["-", 78]];

With[{omegaProbe = 2 Pi 1*^6},
  With[{sProbe = I omegaProbe},
    With[{alfSingle = Re[alphaCubFoster[sProbe]]},
      Do[
        With[{Dval = Dmm 1*^-3},
          With[{aTot = Re[alphaTotal3DFoster[sProbe, 2, Dval]]},
            Print[StringPadRight[ToString[N[Dmm, 4]], 10],
                  StringPadRight[ToString[N[alfSingle, 6]], 22],
                  StringPadRight[ToString[N[aTot, 6]], 22],
                  N[aTot/(2 alfSingle), 8]]
          ]],
        {Dmm, {5, 10, 15, 30, 100, 1000}}]
    ]]];

Print[""];

(* === DC and PEC sanity check =========================================== *)
Print["Sanity checks at D = 15 mm:"];
With[{Dprobe = 15*^-3, Nc = 2},
  With[{s0 = I 2 Pi 0.01, sInf = I 2 Pi 1*^14},
    With[{alphaDC   = Re[alphaTotal3DFoster[s0, Nc, Dprobe]],
          alphaPEC  = Re[alphaTotal3DFoster[sInf, Nc, Dprobe]],
          alphaSingleInf = Re[alphaCubFoster[sInf]]},
      Print["  DC limit alpha_total(s=0)            = ",
            N[alphaDC, 8], "  (target 0)"];
      Print["  PEC limit alpha_total(s=infinity)    = ",
            N[alphaPEC, 8]];
      Print["  N alpha_single (PEC, uncoupled)      = ",
            N[Nc alphaSingleInf, 8], "  (target ~V)"];
      Print["  alpha_total / N alpha_single (PEC)   = ",
            N[alphaPEC/(Nc alphaSingleInf), 8],
            "  (= 1 / (1 + V mu_0/(4 pi D^3) coupling))"]
    ]]];

(* === Compare Foster vs Schur-F per-cuboid in 3D BEM-CLN ================ *)
Print[""];
Print["Foster vs Schur-F per-cuboid building blocks in 2-cuboid BEM-CLN:"];
Print[""];
Print[StringPadRight["f [Hz]", 10] <>
      StringPadRight["alpha_tot Foster", 22] <>
      StringPadRight["alpha_tot Schur", 22] <>
      "ratio"];
Print[StringRepeat["-", 70]];

With[{Dprobe = 15*^-3},
  Do[
    With[{omega = 2 Pi 10.0^logf},
      With[{s = I omega},
        With[{aFos = Re[alphaTotal3DFoster[s, 2, Dprobe]],
              aSch = Re[alphaTotal3DSchur[s, 2, Dprobe]]},
          Print[StringPadRight[ToString["1e" <> ToString[logf]], 10],
                StringPadRight[ToString[N[aFos, 6]], 22],
                StringPadRight[ToString[N[aSch, 6]], 22],
                N[aSch/aFos, 6]]
        ]]],
    {logf, {3, 4, 5, 6, 7, 8, 10, 12}}]
];

(* === Far-field test ===================================================== *)
Print[""];
With[{Dfar = 100, sProbe = I 2 Pi 1*^6, Nc = 2},
  With[{alfSingle = Re[alphaCubFoster[sProbe]],
        aTotFar = Re[alphaTotal3DFoster[sProbe, Nc, Dfar]]},
    Print["Far-field D = 100 m: alpha_total/(N alpha_single) = ",
          N[aTotFar/(Nc alfSingle), 12], "  (target 1.0)"]
  ]];

(* === CSV output ========================================================= *)
Print[""];
Print["Writing CSV..."];
csvData = {{"f_Hz", "D_mm", "alpha_per_cuboid", "alpha_total_Foster", "alpha_total_Schur"}};
Dout = 15*^-3;
Do[
  With[{omega = 2 Pi (10.0^logf), s = I 2 Pi (10.0^logf)},
    With[{alf = Re[alphaCubFoster[s]],
