#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  bem_cln_Ncylinder.wls

  Phase 2: N-cylinder sparse-block BEM-CLN assembly.  Generalises the
  Phase 1 two-cylinder demo (bem_cln_2cylinder.wls) to an arbitrary
  number N of identical infinite Cu cylinders arranged in a linear
  chain at equal spacing D.  The applied field is uniform transverse
  B_0 in y.

  System (N x N) at each frequency s:
    (I + diag(Y_cyl(s)) . G(s)) . m = Y_cyl(s) . B_0 . 1
  where
    Y_cyl(s)     scalar per-cylinder admittance (Bessel or Schur-F);
    G_ij(s) = (mu_0 / (2 pi |r_i - r_j|^2)) * s / (s + s_sat) for i != j;
    G_ii = 0;
    m_n          induced dipole moment of cylinder n.

  Total system admittance:
    Y_total(s, N, D) = (1 / B_0) sum_n m_n(s).

  DOF count (Schur-F per cylinder, basis N_C):
    total = N * (N_C + 1).      Memory scales O(N^2) for coupling matrix.

  Verifies:
   (a) DC limit: Y_total(0, N, D) -> N * Y_cyl(0)
   (b) Far-field limit (D -> infinity): Y_total -> N * Y_cyl
   (c) SIBC tail: |Y_total(j omega)| sqrt(omega) -> N * K_SIBC^(cyl)
       as omega -> infinity (via per-cylinder Schur-F)
   (d) Bessel-exact vs Schur-F-basis-4 building blocks: agreement in wall band

  Run: wolframscript -file bem_cln_Ncylinder.wls
*)

ClearAll[a, sigma, mu, dParam, basisN, omegaSat, sSat];

a        = 5*^-3;
sigma    = 5.96*^7;
mu       = 4 Pi 1*^-7;
dParam   = 2 Pi 1*^5;
basisN   = 4;
omegaSat = 2 Pi 1*^5;
sSat     = I omegaSat;

Print["=== bem_cln_Ncylinder.wls ==="];
Print["N-cylinder linear-chain BEM-CLN assembly"];
Print["a = ", a 1000, " mm, sigma = ", sigma, " S/m, Schur-F basis ", basisN];
Print[""];

KsibcCyl = 2 Pi a Sqrt[sigma/mu];
Print["K_SIBC^(cyl) = ", N[KsibcCyl, 6]];

(* === Per-cylinder building blocks ====================================== *)
YcylBessel[s_] := Module[{gamma},
  gamma = Sqrt[s mu sigma];
  Pi a^2 sigma * 2 BesselI[1, gamma a] / (gamma a BesselI[0, gamma a])];

alphaBessel = N[BesselJZero[0, Range[1, 60]], 30];
gVec2       = 4 / alphaBessel^2;
tauVec      = mu sigma a^2 / alphaBessel^2;

YcylFosterN[s_, n_] := Pi a^2 sigma Total[gVec2[[1 ;; n]] / (1 + s tauVec[[1 ;; n]])];

YcylSchur[s_, n_] := YcylFosterN[s, n] + KsibcCyl Sqrt[s] / (s + dParam);

(* === Coupling matrix G(s) for linear chain of N cylinders ============== *)
(* Cylinder n at position (n - 1) * D along x.  Distance D_ij = |i - j| D. *)
gPair[s_, dist_] := (mu / (2 Pi dist^2)) (s / (s + sSat));

couplingMatrix[s_, Nc_, D_] := Table[
  If[i == j, 0, gPair[s, Abs[i - j] D]],
  {i, 1, Nc}, {j, 1, Nc}];

(* === Solve N x N BEM-CLN system at frequency s ========================= *)
solveBemCLN[s_, Nc_, D_, ycylFun_] := Module[
  {yc, G, sys, rhs, mvec, ones},
  yc = ycylFun[s];
  G = couplingMatrix[s, Nc, D];
  ones = ConstantArray[1, Nc];
  sys = IdentityMatrix[Nc] + yc G;
  rhs = yc ones;
  mvec = LinearSolve[sys, rhs];
  Total[mvec]
];

YtotalBemBessel[s_, Nc_, D_] := solveBemCLN[s, Nc, D, YcylBessel];
YtotalBemSchur[s_, Nc_, D_]  := solveBemCLN[s, Nc, D, YcylSchur[#, basisN] &];

(* === Verification table: N = 2, 3, 5, 10 at D = 15 mm ================== *)
Print[""];
Print["Verification: linear chain, D = 15 mm, at f = 10^6 Hz wall band"];
Print[""];
Print[StringPadRight["N", 4] <>
      StringPadRight["DOF (Schur)", 14] <>
      StringPadRight["|Y_tot Bessel|", 18] <>
      StringPadRight["|Y_tot Schur|", 18] <>
      StringPadRight["Schur/Bessel", 14] <>
      "N*Y_cyl_uncoupled"];
Print[StringRepeat["-", 90]];

With[{Dprobe = 15*^-3, fProbe = 1*^6, omegaProbe = 2 Pi 1*^6},
  With[{sProbe = I omegaProbe},
    With[{ycylUncoupled = Abs[YcylBessel[sProbe]]},
      Do[
        With[{ytBes  = Abs[YtotalBemBessel[sProbe, Nc, Dprobe]],
              ytSch  = Abs[YtotalBemSchur[sProbe, Nc, Dprobe]]},
          Print[StringPadRight[ToString[Nc], 4],
                StringPadRight[ToString[Nc (basisN + 1)], 14],
                StringPadRight[ToString[N[ytBes, 5]], 18],
                StringPadRight[ToString[N[ytSch, 5]], 18],
                StringPadRight[ToString[N[ytSch / ytBes, 6]], 14],
                N[Nc ycylUncoupled, 5]]
        ],
        {Nc, {2, 3, 5, 10}}]
    ]]];

(* === SIBC tail check for N = 5 chain =================================== *)
Print[""];
Print["SIBC tail (N = 5, D = 15 mm): r(omega) = |Y_total| sqrt(omega) / (N K_SIBC^cyl)"];
Print["  Expected r -> 1 at high omega via per-cylinder Schur-F"];
Print[""];
Print[StringPadRight["f [Hz]", 10] <>
      StringPadRight["r (Bessel)", 14] <>
      "r (Schur-F)"];
Print[StringRepeat["-", 50]];

With[{Nc5 = 5, Dprobe = 15*^-3, Ktot5 = 5 KsibcCyl},
  Do[
    With[{omega = 2 Pi (10.0^logf)},
      With[{s = I omega},
        With[{yBes  = Abs[YtotalBemBessel[s, Nc5, Dprobe]],
              ySchur = Abs[YtotalBemSchur[s, Nc5, Dprobe]]},
          Print["f = 1e", logf, " Hz   ",
                "r_Bessel = ", N[yBes Sqrt[omega] / Ktot5, 5], "   ",
                "r_Schur = ",  N[ySchur Sqrt[omega] / Ktot5, 5]]
        ]]],
    {logf, {4, 5, 6, 7, 8, 10, 12}}]
];

(* === DC and parallel limits for sanity check =========================== *)
Print[""];
Print["Sanity: DC and parallel limits"];
With[{omega0 = 2 Pi 0.01, omegaInfD = 2 Pi 1*^6, Nc = 5, Dprobe = 15*^-3, Dfar = 2*^5},
  With[{s0 = I omega0, sInfD = I omegaInfD},
    With[{ycyl0 = Abs[Re[YcylBessel[s0]]],
          ytotDC = Abs[Re[YtotalBemBessel[s0, Nc, Dprobe]]],
          ytotFar = Abs[YtotalBemBessel[sInfD, Nc, Dfar]],
          ycylWall = Abs[YcylBessel[sInfD]]},
      Print["  DC: Y_total(0) / (N Y_cyl(0))  = ", N[ytotDC / (Nc ycyl0), 8],
            "  (target 1.000000)"];
      Print["  Far-field D=200m: Y_tot / (N Y_cyl) at f=1e6 = ",
            N[ytotFar / (Nc ycylWall), 8],
            "  (target 1.000000)"]
    ]]];

(* === Sweep CSV output =================================================== *)
Print[""];
Print["Writing N-scaling sweep CSV..."];
Dout = 15*^-3;
freqList = Table[10^k, {k, 4, 12, 1}];
NList = {2, 3, 5, 10};

csvData = {{"N", "f_Hz", "Y_tot_Bessel_mag", "Y_tot_Schur_mag",
            "DOF_total_Schur", "N_KsibcCyl_div_sqrt_omega"}};
Do[
  Do[
    With[{omega = 2 Pi freq, s = I 2 Pi freq},
      With[{yBes = Abs[YtotalBemBessel[s, Nc, Dout]],
            ySchur = Abs[YtotalBemSchur[s, Nc, Dout]],
            asympt = Nc KsibcCyl / Sqrt[omega]},
        AppendTo[csvData,
          {Nc, N[freq, 6], N[yBes, 8], N[ySchur, 8],
           Nc (basisN + 1), N[asympt, 8]}]
      ]]
    , {freq, freqList}]
  , {Nc, NList}];

Export["bem_cln_Ncylinder.csv", csvData, "CSV"];
Print["Wrote bem_cln_Ncylinder.csv (", (Length[csvData] - 1), " rows)"];

Print[""];
Print["=== bem_cln_Ncylinder.wls DONE ==="];

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  bem_cln_quadrupole_correction.wls

  Phase 4 final-2: quadrupole-order coupling correction to the
  Phase 2.5 rigorous BEM-CLN framework for 2D long cylinder pairs.

  Phase 2.5 includes only dipole-dipole coupling (1/D^2).  For
  finite ratio a/D the field from one cylinder is NOT uniform
  across the other cylinder's cross-section: there is a gradient
  ~1/D^3 that induces a *quadrupole* moment in the receiving
  cylinder.  The correction is O((a/D)^2) of the dipole result.

  For 5 mm cylinder pair at D = 15 mm: (a/D)^2 = (1/3)^2 = 0.111,
  so ~11 % correction expected.

  The 4 x 4 coupled system for 2 cylinders:
    (c_dip_1, c_quad_1, c_dip_2, c_quad_2) coupled by 2x2 sub-blocks
    [G_dd, G_dq; G_qd, G_qq]

  Coupling tensor entries (2D dipole/quadrupole pair, applied B in y,
  cylinders separated by D along x):
    G_dd(D)  = 1/D^2        (dipole field at distance D)
    G_dq(D)  = grad of dipole field / D^3 ~ 2/D^3 in magnitude
    G_qd(D)  = quadrupole field at distance D ~ 2/D^3
    G_qq(D)  = grad of quadrupole field ~ 6/D^4

  Per-cylinder polarizabilities:
    alpha_dipole(s) = a^2 [1 - 2 I_1(gamma a)/(gamma a I_0(gamma a))]
                                                       (Phase 2.5)
    alpha_quad(s)   ~ a^4 [1 - I_2(gamma a)/(... I_1(gamma a))]
                                                       (next Bessel order)

  For a simplified derivation we use scaling estimates:
    alpha_quad(s) / alpha_dip(s) = a^2 * scaling_factor
  where scaling_factor approaches 1 at PEC (perfect shielding of all
  multipoles) and 0 at DC.  A useful approximation is
    alpha_quad(s) ~= a^2 * alpha_dip(s)
  which captures the correct DC and PEC limits and the leading
  s-dependence.

  Run: wolframscript -file bem_cln_quadrupole_correction.wls
*)

ClearAll[a, sigma, mu];

a     = 5*^-3;
sigma = N[5.96*^7, 30];
mu    = N[4 Pi 1*^-7, 30];

Print["=== bem_cln_quadrupole_correction.wls ==="];
Print["Quadrupole correction to Phase 2.5 dipole-only coupling"];
Print["Cylinder a = ", a 1000, " mm, Cu"];
Print[""];

(* === Bessel exact polarizability (per Phase 2.5) ======================== *)
YcylBessel[s_?NumericQ] := Module[{gamma},
  gamma = Sqrt[s mu sigma];
  N[Pi a^2 sigma * 2 BesselI[1, gamma a] / (gamma a BesselI[0, gamma a]), 20]];

alphaDip[s_?NumericQ] := N[a^2 - YcylBessel[s] / (Pi sigma), 20];

(* === Quadrupole polarizability (limits-correct approximation) =========== *)
(* The exact Bessel-derived n=2 polarizability is complicated.  For an
   estimate that captures the correct DC and PEC limits and the leading
   s-dependence, we use the simplified scaling
        alpha_quad(s) = (a^2 / 2) * alpha_dip(s)
   which has:
     alpha_quad(0)        = 0                 (no eddy current at DC)
     alpha_quad(infinity) = a^4 / 2           (n=2 PEC shielding)
   The exact n=2 Bessel form has the same limits but different shape at
   intermediate frequencies; for the (a/D)^2 magnitude estimate this
   approximation is sufficient.  Refinement to exact n=2 Bessel via
   I_2(gamma a) matching is left as a small future improvement.        *)
alphaQuad[s_?NumericQ] := N[(a^2 / 2) alphaDip[s], 20];

(* Sanity: limits *)
Print["alpha_dip limits:"];
Print["  alpha_dip(0+)        = ", N[Re[alphaDip[I 2 Pi 0.01]], 6]];
Print["  alpha_dip(infinity)  = ", N[Re[alphaDip[I 2 Pi 1*^14]], 6],
      "  (target a^2 = ", N[a^2, 6], ")"];
Print[""];
Print["alpha_quad limits:"];
Print["  alpha_quad(0+)       = ", N[Re[alphaQuad[I 2 Pi 0.01]], 6]];
Print["  alpha_quad(infinity) = ", N[Re[alphaQuad[I 2 Pi 1*^14]], 6],
      "  (target a^4 = ", N[a^4, 6], ")"];
Print[""];

(* === 2D coupling tensor (dipole + quadrupole) =========================== *)
(* For cylinders separated by D along x, applied B in y *)
gDD[D_] := 1/D^2;           (* dipole-dipole *)
gDQ[D_] := 2/D^3;           (* dipole field gradient -> drives quadrupole *)
gQD[D_] := 2/D^3;           (* by reciprocity *)
gQQ[D_] := 6/D^4;           (* quadrupole-quadrupole *)

(* === 2-cylinder 4 x 4 system =========================================== *)
solve2cylQuad[s_?NumericQ, D_?NumericQ, B0_?NumericQ] := Module[
  {ad, aq, gdd, gdq, gqd, gqq, sysMat, rhs, sol},
  ad = alphaDip[s];
  aq = alphaQuad[s];
  gdd = gDD[D]; gdq = gDQ[D]; gqd = gQD[D]; gqq = gQQ[D];
  (* System: (c_d1, c_q1, c_d2, c_q2) coupled
     c_d1 - ad gdd c_d2 - ad gdq c_q2 = ad B0
     c_q1 - aq gqd c_d2 - aq gqq c_q2 = 0       (no quadrupole drive from uniform B)
     -ad gdd c_d1 - ad gdq c_q1 + c_d2 = ad B0
     -aq gqd c_d1 - aq gqq c_q1 + c_q2 = 0     *)
  sysMat = {
    {1,         0,         -ad gdd,   -ad gdq},
    {0,         1,         -aq gqd,   -aq gqq},
    {-ad gdd,  -ad gdq,    1,          0     },
    {-aq gqd,  -aq gqq,    0,          1     }
  };
  rhs = {ad B0, 0, ad B0, 0};
  sol = LinearSolve[sysMat, rhs];
  Association["c_d1" -> sol[[1]], "c_q1" -> sol[[2]],
              "c_d2" -> sol[[3]], "c_q2" -> sol[[4]]]];

(* === Phase 2.5 reference (dipole only) ================================ *)
solve2cylDipOnly[s_?NumericQ, D_?NumericQ, B0_?NumericQ] := Module[
  {ad, gdd},
  ad = alphaDip[s];
  gdd = gDD[D];
  ad B0 / (1 - ad gdd)];

(* === Test: 2 cylinders, a = 5 mm, D = 15 mm =========================== *)
Dpair = 15*^-3;
aOverD = a / Dpair;
Print["a/D = ", N[aOverD, 4]];
Print["(a/D)^2 = ", N[aOverD^2, 4], " (expected quadrupole correction magnitude)"];
Print[""];

Print["Comparison: dipole-only (Phase 2.5) vs dipole+quadrupole at f = 10^6 Hz"];
Print[""];
With[{sProbe = I 2 Pi 1*^6, B0 = 1.0},
  Module[{cDipOnly, sol4x4, cTotal4x4, correctionPct},
    cDipOnly = solve2cylDipOnly[sProbe, Dpair, B0];
    sol4x4 = solve2cylQuad[sProbe, Dpair, B0];
    cTotal4x4 = sol4x4["c_d1"];     (* dipole moment of cyl 1 *)
    correctionPct = 100 (Abs[cTotal4x4] - Abs[cDipOnly]) / Abs[cDipOnly];
    Print["  c_dip Phase 2.5 only           = ", N[cDipOnly, 5]];
    Print["  c_dip with quadrupole coupling = ", N[cTotal4x4, 5]];
    Print["  |c_quad| (induced quadrupole)  = ", N[Abs[sol4x4["c_q1"]], 5]];
    Print["  Correction (%)                 = ", N[correctionPct, 4]];
    Print["  Expected ~ (a/D)^2 = ", N[100 aOverD^2, 4], " %"]
  ]];

(* === Frequency sweep ==================================================== *)
Print[""];
Print["Quadrupole correction across wall band:"];
Print[""];
Print[StringPadRight["f [Hz]", 12] <>
      StringPadRight["|c_dip Phase2.5|", 22] <>
      StringPadRight["|c_dip with quad|", 22] <>
      "correction %"];
Print[StringRepeat["-", 70]];
Do[
  With[{omega = 2 Pi (10.0^logf), s = I 2 Pi (10.0^logf), B0 = 1.0},
    With[{cDip = solve2cylDipOnly[s, Dpair, B0],
          sol = solve2cylQuad[s, Dpair, B0]},
      Print["f=1e", logf, "       ",
            StringPadRight[ToString[N[Abs[cDip], 5]], 22],
            StringPadRight[ToString[N[Abs[sol["c_d1"]], 5]], 22],
            N[100 (Abs[sol["c_d1"]] - Abs[cDip])/Abs[cDip], 4]]
    ]],
  {logf, {3, 4, 5, 6, 7, 8}}];

Print[""];
Print["=== bem_cln_quadrupole_correction.wls DONE ==="];

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  cuboid3D_AAA_CFschur.wls

  AAA-flavoured rational approximation of the Schur block
    z_block(s) = K_SIBC * sqrt(s) / (s + d)
  using a DC-preserving pole-residue ansatz:
    g_N(s) = K_SIBC * sum_{k=1}^N r_k * (1/p_k - 1/(s + p_k))
           = K_SIBC * sum_{k=1}^N r_k * s / (p_k * (s + p_k))

  At s = 0: g_N(0) = 0  (DC PRESERVED by construction)
  At s -> oo: g_N -> K_SIBC * (sum r_k/p_k) -> finite (BANDLIMITED, not 1/sqrt(s))

  This solves the B-axis contamination of the naive Stieltjes CF
  (which had non-zero DC) while accepting that no finite-N rational
  function can reach 1/sqrt(s) asymptotically -- the BANDLIMIT.

  The poles p_k are chosen log-spaced over [p_min, p_max] and the
  residues r_k solve a complex least-squares problem matching
  z_target(jw) at K log-spaced frequency samples on [w_min, w_max].

  Comparison against:
    - Naive Stieltjes CF (B-axis contaminated, A/C axes failed)
    - Non-rational sqrt(s) Schur-F (gold standard, exact at all s)

  Run: wolframscript -file cuboid3D_AAA_CFschur.wls
*)

ClearAll[sigma, mu, nu];
sigma = 5.8*^7;
mu    = 4 Pi 1*^-7;
nu    = 1/mu;

geometries = {
  <|"name" -> "A1 (17.72x17.72x2 mm Cu)",
    "a" -> 17.72*^-3, "b" -> 17.72*^-3, "c" -> 2*^-3,
    "wall_lo" -> 1*^3, "wall_hi" -> 1*^5,
    "d_schur" -> 2 Pi 1*^6,
    "p_min" -> 2 Pi 1*^4, "p_max" -> 2 Pi 1*^12|>,
  <|"name" -> "5x2x1 mm Cu",
    "a" -> 5*^-3, "b" -> 2*^-3, "c" -> 1*^-3,
    "wall_lo" -> 1*^5, "wall_hi" -> 1*^7,
    "d_schur" -> 2 Pi 1*^9,
    "p_min" -> 2 Pi 1*^6, "p_max" -> 2 Pi 1*^14|>
};

(* === DC-preserving rational ansatz with LS residues =================== *)
(* g(s) = K_SIBC * sum_{k=1..N} r_k * s / (p_k * (s + p_k))                *)
(* Target: z_target(s) = K_SIBC * sqrt(s) / (s + d)                       *)
(* LS over N_sample log-spaced frequencies in [w_lo, w_hi]                *)

fitDCPreservingPoles[Nrank_, pMin_, pMax_, dSchur_, KSIBC_, wLo_, wHi_, nSample_:60] :=
  Module[{poles, samples, omegas, sValues, Amat, bvecLS, rVec, basisFn},
    poles  = N[pMin Exp[Log[pMax/pMin] Subdivide[0, 1, Nrank - 1]]];
    omegas = N[Exp[Log[wLo] + (Log[wHi] - Log[wLo]) Subdivide[0, 1, nSample - 1]]];
    sValues = I omegas;
    basisFn[s_, p_] := s / (p (s + p));
    Amat = Table[
      Table[basisFn[sValues[[i]], poles[[k]]], {k, 1, Nrank}],
      {i, 1, nSample}];
    bvecLS = Table[KSIBC Sqrt[sValues[[i]]] / (sValues[[i]] + dSchur), {i, 1, nSample}];
    (* LS: solve A . r = b in least-squares sense *)
    rVec = LeastSquares[Amat, bvecLS];
    rVec = Re[rVec];  (* enforce real residues (passive) *)
    {poles, rVec}];  (* K_SIBC is already absorbed into bvecLS target *)

(* AAA-fit evaluator: g_AAA(s) = sum_k r_k * s / (p_k * (s + p_k))      *)
gAAA[s_, poles_, rEff_] :=
  Total[rEff (s / (poles (s + poles)))];

(* === Per-geometry analysis ============================================= *)
analyzeGeom[geom_] := Module[
  {a, b, c, name, wallLo, wallHi, dSchur, pMin, pMax, Sarea, KSIBC,
   Mmax = 13, oddRange, modeList, Nmodes, lamVec, tauVec, g2Vec,
   LambdaM, sigmaM, Imat, Kmodal, K0matrix, bvec, YExactFoster,
   K0Inner, K0MGS, K0Normalise, buildCLNbasis,
   YReducedFromBasis, YSchurNR, YAAA, QCLN3, freqWall, freqProbe,
   results, evalAAA, evalNR, NCFs},
  a = geom["a"]; b = geom["b"]; c = geom["c"];
  name = geom["name"]; wallLo = geom["wall_lo"]; wallHi = geom["wall_hi"];
  dSchur = geom["d_schur"]; pMin = geom["p_min"]; pMax = geom["p_max"];
  Sarea = 2 (a b + b c + c a);
  KSIBC = Sarea Sqrt[sigma/mu];

  Print["==============================================="];
  Print[" Geometry: ", name];
  Print["==============================================="];
  Print["  K_SIBC = ", N[KSIBC, 6]];
  Print["  Schur-F d/(2pi) = ", N[dSchur/(2 Pi), 4], " Hz"];
  Print["  AAA pole grid [p_min, p_max]/(2pi) = [",
        N[pMin/(2 Pi), 3], ", ", N[pMax/(2 Pi), 3], "] Hz"];

  (* --- Foster spectrum (343 modes) --- *)
  oddRange = Range[1, Mmax, 2];
  modeList = Flatten[Table[{m, n, p}, {m, oddRange}, {n, oddRange}, {p, oddRange}], 2];
  Nmodes   = Length[modeList];
  lamVec   = N[Table[(mnp[[1]] Pi/a)^2 + (mnp[[2]] Pi/b)^2 + (mnp[[3]] Pi/c)^2,
                     {mnp, modeList}]];
  tauVec   = mu sigma / lamVec;
  g2Vec    = N[Table[512 sigma a b c / ((mnp[[1]] mnp[[2]] mnp[[3]])^2 Pi^6),
                     {mnp, modeList}]];
  LambdaM    = N[DiagonalMatrix[lamVec]];
  sigmaM     = N[sigma IdentityMatrix[Nmodes]];
  Imat       = N[IdentityMatrix[Nmodes]];
  Kmodal[s_] := nu LambdaM + sigma s Imat;
  K0matrix   = Kmodal[0];
  bvec       = N[Sqrt[g2Vec / tauVec]];
  YExactFoster[omega_] := Module[{s = I omega}, Total[g2Vec / (1 + s tauVec)]];

  K0Inner[u_, v_] := u . K0matrix . v;
  K0MGS[vIn_, basis_] := Module[{v = vIn},
    Do[v = v - K0Inner[basis[[i]], v] basis[[i]], {i, 1, Length[basis]}]; v];
  K0Normalise[v_] := Module[{nrm = Sqrt[Re[K0Inner[v, v]]]},
    If[nrm < 1*^-300, v, v/nrm]];
  buildCLNbasis[s0_, M_] := Module[{Q = {}, vk, KsInv},
    KsInv = Inverse[Kmodal[s0]];
    vk    = K0Normalise[KsInv . (sigmaM . bvec)];
    AppendTo[Q, vk];
    Do[vk = KsInv . (sigmaM . Last[Q]);
       vk = K0Normalise[K0MGS[vk, Q]];
       AppendTo[Q, vk], {M - 1}];
    Q];

  YReducedFromBasis[Qlist_, omega_] := Module[{Kr, Qb},
    Kr = Qlist . Kmodal[I omega] . Transpose[Qlist];
    Qb = Qlist . bvec;
    sigma (Qb . LinearSolve[Kr, Qb])];

  YSchurNR[Qlist_, omega_] :=
    YReducedFromBasis[Qlist, omega] + KSIBC Sqrt[I omega]/(I omega + dSchur);

  QCLN3 = buildCLNbasis[0, 3];

  freqWall = Select[N[10^Range[Log10[wallLo], Log10[wallHi], 0.25]],
                    wallLo <= # <= wallHi &];
  freqProbe = N[{1*^6, 1*^8, 1*^10, 1*^12}];

  NCFs = {4, 8, 16};

  Print[""];
  Print["  --- AAA CF-Schur (DC-preserving rational) ---"];
  Print["  ", StringPadLeft["N", 4], " ",
        StringPadRight["wall %", 11], StringPadRight["DC offset", 14],
        StringPadRight["r(1e6)", 11], StringPadRight["r(1e8)", 11],
        StringPadRight["r(1e10)", 11], StringPadRight["r(1e12)", 11]];
  results = Table[
    Module[{poles, rEff, YAAAfn, wallErr, dcOffset, rVec, yEx, yR},
      {poles, rEff} = fitDCPreservingPoles[NC, pMin, pMax, dSchur, KSIBC,
                        2 Pi wallLo, 2 Pi 1*^11, 60];
      YAAAfn[om_] := YReducedFromBasis[QCLN3, om] + gAAA[I om, poles, rEff];
      wallErr = Max[Table[
        Module[{om = 2 Pi f},
          yEx = YExactFoster[om];
          yR  = YAAAfn[om];
          Abs[(yR - yEx)/yEx]], {f, freqWall}]];
      dcOffset = gAAA[0., poles, rEff];   (* should be 0 by construction *)
      rVec = Table[
        Module[{om = 2 Pi f},
          yR = YAAAfn[om];
          Abs[yR] Sqrt[om] / KSIBC], {f, freqProbe}];
      Print["  ", StringPadLeft[ToString[NC], 4], " ",
            StringPadRight[ToString[NumberForm[100 wallErr, {6, 2}]] <> "%", 11],
            StringPadRight[ToString[ScientificForm[N[dcOffset], 3]], 14],
            StringPadRight[ToString[NumberForm[rVec[[1]], {6, 4}]], 11],
            StringPadRight[ToString[NumberForm[rVec[[2]], {6, 4}]], 11],
            StringPadRight[ToString[NumberForm[rVec[[3]], {6, 4}]], 11],
            StringPadRight[ToString[NumberForm[rVec[[4]], {6, 4}]], 11]];
      <|"N" -> NC, "poles" -> N[poles], "rEff" -> N[rEff],
        "wall_peak" -> N[wallErr],
        "dc_offset" -> N[dcOffset],
        "r_1e6"  -> N[rVec[[1]]], "r_1e8"  -> N[rVec[[2]]],
        "r_1e10" -> N[rVec[[3]]], "r_1e12" -> N[rVec[[4]]]|>],
    {NC, NCFs}];

  (* Non-rational reference *)
  Module[{wallErr, rVec, yR},
    wallErr = Max[Table[
      Module[{om = 2 Pi f, yEx},
        yEx = YExactFoster[om];
        yR  = YSchurNR[QCLN3, om];
        Abs[(yR - yEx)/yEx]], {f, freqWall}]];
    rVec = Table[
      Module[{om = 2 Pi f, yR2},
        yR2 = YSchurNR[QCLN3, om];
        Abs[yR2] Sqrt[om] / KSIBC], {f, freqProbe}];
    Print["  ", StringPadLeft["NR", 4], " ",
          StringPadRight[ToString[NumberForm[100 wallErr, {6, 2}]] <> "%", 11],
          StringPadRight["(0 exact)", 14],
          StringPadRight[ToString[NumberForm[rVec[[1]], {6, 4}]], 11],
          StringPadRight[ToString[NumberForm[rVec[[2]], {6, 4}]], 11],
          StringPadRight[ToString[NumberForm[rVec[[3]], {6, 4}]], 11],
          StringPadRight[ToString[NumberForm[rVec[[4]], {6, 4}]], 11]];
    Print["  (NR = non-rational sqrt(s)/(s+d) Schur-F at d/(2pi)=",
          N[dSchur/(2 Pi), 4], " Hz)"]];

  Print[""];
  <|"geom" -> geom, "K_SIBC" -> N[KSIBC],
    "AAA_results" -> results|>];

(* === Run both geometries =============================================== *)
allResults = Map[analyzeGeom, geometries];

(* === Save JSON (strip symbolic Pi etc.) ================================ *)
toReal[x_] := If[NumericQ[x], N[x],
                 If[ListQ[x], Map[toReal, x],
                    If[AssociationQ[x], Association[Map[# -> toReal[x[#]] &, Keys[x]]],
                       x]]];
out = <|
  "geometries" -> toReal[Table[allResults[[k]]["geom"], {k, Length[allResults]}]],
  "AAA_results" -> Table[
    <|"name"     -> allResults[[k]]["geom"]["name"],
      "K_SIBC"   -> N[allResults[[k]]["K_SIBC"]],
      "results"  -> toReal[allResults[[k]]["AAA_results"]]|>,
    {k, Length[allResults]}]|>;
Export["cuboid3D_AAA_CFschur.json", out, "JSON"];
Print[""];
Print["Saved cuboid3D_AAA_CFschur.json"];

(* === Headline summary ================================================= *)
Print[""];
Print["============================================================"];
Print[" Headline: AAA-CF-Schur vs naive Stieltjes vs non-rational"];
Print[" (compare with naive CF-Schur results in cuboid3D_CFschur_both.wls)"];
Print[" Key improvements over naive CF:"];
Print["   - DC offset = 0 by ansatz (B-axis preserved)"];
Print["   - Wall-band accuracy controlled by LS fit"];
Print["   - C-axis: still rational, still bandlimited (cannot reach 1/sqrt)"];
Print["   - For SPICE realisation: passive RLC ladder with real poles"];
Print["============================================================"];

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  cuboid3D_CFschur_both.wls

  Continued-fraction (CF) Schur: expand the non-rational K_SIBC sqrt(s)/(s+d)
  block as an N-rung rational ladder via Stieltjes integral representation
  of 1/sqrt(s), then couple each rung as a Schur block to the CLN.

  Mathematical content
  --------------------
    1/sqrt(s) = (1/pi) integral_0^inf 1/(sqrt(xi)*(s+xi)) dxi
              ~ Sum_{k=1..N} w_k / (s + xi_k)
    where (xi_k, w_k) are Stieltjes-Gauss quadrature nodes/weights.

  Implementation: log-grid Stieltjes with closed-form residue weights.
    xi_k = xi_min * (xi_max/xi_min)^((k-0.5)/N)    (log-spaced)
    w_k  = (1/pi) * sqrt(xi_k) * log(xi_max/xi_min) / N
      (rectangular rule on log(xi) with weight sqrt(xi); converges in N)

  This is the simplest convergent quadrature.  For production work, use
  Gauss-Jacobi or AAA rational approximation; results below already show
  geometric convergence in N for the C-axis.

  Y_CF-Schur(s) = Y_CLN(s) + K_SIBC * Sum_{k=1..N} w_k / (s + xi_k)

  All-rational: each rung = parallel R-L pair, SPICE-realisable.

  Four sub-tests on each cuboid (A1 17.72x17.72x2 mm, 5x2x1 mm):
    (1) N=1 CF-Schur vs original non-rational sqrt(s) Schur-F
    (2) C-axis convergence for N=1,3,5,7,9,11
    (3) B-axis contamination (s=0 Taylor coefficient errors)
    (4) A-axis hybrid: CLN_N=3 + CF-Schur(N=4) (basis 7) vs Multi-K basis 7
*)

ClearAll[sigma, mu, nu];

sigma = 5.8*^7;
mu    = 4 Pi 1*^-7;
nu    = 1/mu;

geometries = {
  <|"name" -> "A1 (17.72x17.72x2 mm Cu)",
    "a" -> 17.72*^-3, "b" -> 17.72*^-3, "c" -> 2*^-3,
    "wall_lo" -> 1*^3, "wall_hi" -> 1*^5|>,
  <|"name" -> "5x2x1 mm Cu",
    "a" -> 5*^-3, "b" -> 2*^-3, "c" -> 1*^-3,
    "wall_lo" -> 1*^5, "wall_hi" -> 1*^7|>
};

(* === CF nodes/weights for 1/sqrt(s) on log-xi grid ====================== *)
(* xi range covers the body's wall band and 4 decades above for high-f      *)
cfNodes[N_Integer, xiMin_, xiMax_] := Module[{logRatio, ksRange, xi, w},
  logRatio = Log[xiMax/xiMin];
  ksRange  = Range[N];
  xi = Table[xiMin Exp[(k - 0.5) logRatio / N], {k, ksRange}];
  (* Stieltjes weight on log-grid: w_k = (1/pi) sqrt(xi_k) * (log_ratio/N) *)
  w  = (1/Pi) Sqrt[xi] (logRatio / N);
  {xi, w}];

(* === Per-geometry analysis ============================================== *)
analyzeCuboid[geom_, cfParams_] := Module[
  {a, b, c, name, wallLo, wallHi, Sarea, KSIBC3D, Mmax = 13, oddRange,
   modeList, Nmodes, lamVec, tauVec, g2Vec, LambdaM, sigmaM, Imat,
   Kmodal, K0matrix, bvec, YExactFoster, K0Inner, K0MGS, K0Normalise,
   buildCLNbasis, buildMultiKuriyama, YReducedFromBasis,
   YReducedSchurF, YCFSchur, dCandidates, freqWallTmp, QCLN3, QCLN6, QCLN10,
   QMK4, QMK7,
   dBest, dSchur, freqProbe, evalCase,
   xiMin, xiMax, NCFs, cfResults, taylorExact, taylorReducedPlusCF,
   cfBaxisResults},
  a = geom["a"]; b = geom["b"]; c = geom["c"];
  name = geom["name"]; wallLo = geom["wall_lo"]; wallHi = geom["wall_hi"];
  Sarea = 2 (a b + b c + c a);
  KSIBC3D = Sarea Sqrt[sigma/mu];
  xiMin = cfParams["xi_min"]; xiMax = cfParams["xi_max"];
  NCFs  = cfParams["N_list"];

  Print["==============================================="];
  Print[" Geometry: ", name];
  Print["==============================================="];
  Print["  a = ", N[a 1000, 4], " mm, b = ", N[b 1000, 4], " mm, c = ", N[c 1000, 4], " mm"];
  Print["  S = ", N[Sarea 1*^6, 6], " mm^2,  K_SIBC = ", N[KSIBC3D, 6]];
  Print["  CF grid: xi in [", N[xiMin], ", ", N[xiMax],
        "] rad/s = 2pi[", N[xiMin/(2 Pi)], ", ", N[xiMax/(2 Pi)], "] Hz"];

  (* --- Foster spectrum + reduced operators --- *)
  oddRange = Range[1, Mmax, 2];
  modeList = Flatten[Table[{m, n, p}, {m, oddRange}, {n, oddRange}, {p, oddRange}], 2];
  Nmodes   = Length[modeList];
  lamVec   = N[Table[(mnp[[1]] Pi/a)^2 + (mnp[[2]] Pi/b)^2 + (mnp[[3]] Pi/c)^2,
                     {mnp, modeList}]];
  tauVec   = mu sigma / lamVec;
  g2Vec    = N[Table[512 sigma a b c / ((mnp[[1]] mnp[[2]] mnp[[3]])^2 Pi^6),
                     {mnp, modeList}]];
  LambdaM    = N[DiagonalMatrix[lamVec]];
  sigmaM     = N[sigma IdentityMatrix[Nmodes]];
  Imat       = N[IdentityMatrix[Nmodes]];
  Kmodal[s_] := nu LambdaM + sigma s Imat;
  K0matrix   = Kmodal[0];
  bvec       = N[Sqrt[g2Vec / tauVec]];
  YExactFoster[omega_] := Module[{s = I omega}, Total[g2Vec / (1 + s tauVec)]];

  K0Inner[u_, v_] := u . K0matrix . v;
  K0MGS[vIn_, basis_] := Module[{v = vIn},
    Do[v = v - K0Inner[basis[[i]], v] basis[[i]], {i, 1, Length[basis]}]; v];
  K0Normalise[v_] := Module[{nrm = Sqrt[Re[K0Inner[v, v]]]},
    If[nrm < 1*^-300, v, v/nrm]];
  buildCLNbasis[s0_, M_] := Module[{Q = {}, vk, KsInv},
    KsInv = Inverse[Kmodal[s0]];
    vk    = K0Normalise[KsInv . (sigmaM . bvec)];
    AppendTo[Q, vk];
    Do[vk = KsInv . (sigmaM . Last[Q]);
       vk = K0Normalise[K0MGS[vk, Q]];
       AppendTo[Q, vk], {M - 1}];
    Q];
  buildMultiKuriyama[Mzero_, s1list_] := Module[{Q, KsInv, vRaw},
    Q = buildCLNbasis[0, Mzero];
    Do[Module[{si = s1list[[k]]},
         KsInv = Inverse[Kmodal[si]];
         vRaw  = KsInv . (sigmaM . Last[Q]);
         vRaw  = K0Normalise[K0MGS[vRaw, Q]];
         Q     = Append[Q, vRaw]], {k, 1, Length[s1list]}];
    Q];
  YReducedFromBasis[Qlist_, omega_] := Module[{Kr, Qb},
    Kr = Qlist . Kmodal[I omega] . Transpose[Qlist];
    Qb = Qlist . bvec;
    sigma (Qb . LinearSolve[Kr, Qb])];

  (* --- ROMs --- *)
  QCLN3 = buildCLNbasis[0, 3];
  QCLN6 = buildCLNbasis[0, 6];
  QMK4  = buildMultiKuriyama[3, {2 Pi wallLo 10}];
  QMK7  = buildMultiKuriyama[3, N[2 Pi wallLo 10^Range[0, 3, 1]]];

  (* --- Optimal d for the original non-rational Schur-F (re-use earlier result) --- *)
  dCandidates = N[2 Pi 10^Range[4, 9, 0.5]];
  freqWallTmp = Select[N[10^Range[Log10[wallLo], Log10[wallHi], 0.25]],
                       wallLo <= # <= wallHi &];
  YReducedSchurF[Qlist_, omega_, d_] :=
    YReducedFromBasis[Qlist, omega] + KSIBC3D Sqrt[I omega]/(I omega + d);
  dBest = First[SortBy[Table[
    Module[{wallErr},
      wallErr = Max[Table[
        Module[{om = 2 Pi f, yEx, yR},
          yEx = YExactFoster[om];
          yR  = YReducedSchurF[QCLN3, om, d];
          Abs[(yR - yEx)/yEx]], {f, freqWallTmp}]];
      {d, wallErr}], {d, dCandidates}], Last]];
  dSchur = dBest[[1]];
  Print["  non-rational Schur-F best d/(2pi) = ", N[dSchur/(2 Pi), 4], " Hz"];

  (* --- CF-Schur model --- *)
  YCFSchur[Qlist_, omega_, xiList_, wList_] := Module[{yCLN, s, yExtra},
    yCLN   = YReducedFromBasis[Qlist, omega];
    s      = I omega;
    yExtra = KSIBC3D Total[wList / (s + xiList)];
    yCLN + yExtra];

  freqProbe = N[{1*^6, 1*^8, 1*^10, 1*^12}];

  (* === Sub-test (1) + (2): C-axis convergence with N --- *)
  Print[""];
  Print["  --- Sub-test (1)+(2): C-axis convergence with CF rank N ---"];
  Print["  ", StringPadLeft["N", 4], " ", StringPadRight["wall %", 11],
        StringPadRight["r(1e6)", 11], StringPadRight["r(1e8)", 11],
        StringPadRight["r(1e10)", 11], StringPadRight["r(1e12)", 11]];
  cfResults = Table[
    Module[{xiList, wList, wallErr, rVec, yEx, yR},
      {xiList, wList} = cfNodes[NC, xiMin, xiMax];
      wallErr = Max[Table[
        Module[{om = 2 Pi f},
          yEx = YExactFoster[om];
          yR  = YCFSchur[QCLN3, om, xiList, wList];
          Abs[(yR - yEx)/yEx]], {f, freqWallTmp}]];
      rVec = Table[
        Module[{om = 2 Pi f},
          yR = YCFSchur[QCLN3, om, xiList, wList];
          Abs[yR] Sqrt[om] / KSIBC3D], {f, freqProbe}];
      Print["  ", StringPadLeft[ToString[NC], 4], " ",
            StringPadRight[ToString[NumberForm[100 wallErr, {6, 2}]] <> "%", 11],
            StringPadRight[ToString[NumberForm[rVec[[1]], {6, 4}]], 11],
            StringPadRight[ToString[NumberForm[rVec[[2]], {6, 4}]], 11],
            StringPadRight[ToString[NumberForm[rVec[[3]], {6, 4}]], 11],
            StringPadRight[ToString[NumberForm[rVec[[4]], {6, 4}]], 11]];
      <|"N" -> NC, "wall_peak" -> N[wallErr],
        "r_1e6" -> N[rVec[[1]]], "r_1e8" -> N[rVec[[2]]],
        "r_1e10" -> N[rVec[[3]]], "r_1e12" -> N[rVec[[4]]]|>],
    {NC, NCFs}];

  (* Reference row: non-rational Schur-F at best d *)
  Module[{yEx, yR, wallErr, rVec},
    wallErr = Max[Table[
      Module[{om = 2 Pi f},
        yEx = YExactFoster[om];
        yR  = YReducedSchurF[QCLN3, om, dSchur];
        Abs[(yR - yEx)/yEx]], {f, freqWallTmp}]];
    rVec = Table[
      Module[{om = 2 Pi f, yR2},
        yR2 = YReducedSchurF[QCLN3, om, dSchur];
        Abs[yR2] Sqrt[om] / KSIBC3D], {f, freqProbe}];
    Print["  ", StringPadLeft["NR", 4], " ",
          StringPadRight[ToString[NumberForm[100 wallErr, {6, 2}]] <> "%", 11],
          StringPadRight[ToString[NumberForm[rVec[[1]], {6, 4}]], 11],
          StringPadRight[ToString[NumberForm[rVec[[2]], {6, 4}]], 11],
          StringPadRight[ToString[NumberForm[rVec[[3]], {6, 4}]], 11],
          StringPadRight[ToString[NumberForm[rVec[[4]], {6, 4}]], 11]];
    Print["  (NR = original non-rational sqrt(s) Schur-F at d/(2pi)=",
          N[dSchur/(2 Pi), 4], " Hz)"]];

  (* === Sub-test (3): B-axis contamination --- *)
  Print[""];
  Print["  --- Sub-test (3): B-axis contamination by CF rungs ---"];
  taylorExact[n_] := (-1)^n Total[g2Vec * tauVec^n];
  (* CF-Schur Taylor at s=0:
     Sum_k w_k * (-1)^n / xi_k^(n+1) (geometric series d^n/ds^n[1/(s+xi)] at s=0) *)
  cfTaylor[n_, xiList_, wList_] := KSIBC3D (-1)^n Total[wList / xiList^(n + 1)];
  taylorReducedPlusCF[Qlist_, n_, xiList_, wList_] :=
    Module[{K0r, sigmar, br, K0rInv, aClnR, aCF},
      K0r    = Qlist . K0matrix . Transpose[Qlist];
      sigmar = Qlist . sigmaM . Transpose[Qlist];
      br     = Qlist . bvec;
      K0rInv = Inverse[K0r];
      aClnR = sigma (br . ((-1)^n MatrixPower[K0rInv . sigmar, n] . K0rInv) . br);
      aCF   = cfTaylor[n, xiList, wList];
      aClnR + aCF];

  Module[{xi5, w5, xi7, w7, xi9, w9},
    {xi5, w5} = cfNodes[5, xiMin, xiMax];
    {xi7, w7} = cfNodes[7, xiMin, xiMax];
    {xi9, w9} = cfNodes[9, xiMin, xiMax];
    Print["  Taylor coefficients of (CLN_N=3 + CF(N=5,7,9)) at s=0 vs Foster exact"];
    Print["  ", StringPadLeft["n", 4], " ",
          StringPadRight["exact a_n", 14],
          StringPadRight["CLN3 alone", 14],
          StringPadRight["CLN3+CF5", 14],
          StringPadRight["CLN3+CF7", 14],
          StringPadRight["CLN3+CF9", 14]];
    cfBaxisResults = Table[
      Module[{aEx, aN3, aCF5, aCF7, aCF9, fE},
        aEx  = taylorExact[n];
        aN3  = sigma (((QCLN3 . bvec)) . ((-1)^n MatrixPower[
                Inverse[QCLN3 . K0matrix . Transpose[QCLN3]] . (QCLN3 . sigmaM . Transpose[QCLN3]),
                n] . Inverse[QCLN3 . K0matrix . Transpose[QCLN3]]) . (QCLN3 . bvec));
        aCF5 = taylorReducedPlusCF[QCLN3, n, xi5, w5];
        aCF7 = taylorReducedPlusCF[QCLN3, n, xi7, w7];
        aCF9 = taylorReducedPlusCF[QCLN3, n, xi9, w9];
        fE[x_] := If[Abs[aEx] > 0, ScientificForm[N[Abs[(x - aEx)/aEx]], 2], "n/a"];
        Print["  ", StringPadLeft[ToString[n], 4], " ",
              StringPadRight[ToString[ScientificForm[N[aEx], 3]], 14],
              StringPadRight[ToString[fE[aN3]], 14],
              StringPadRight[ToString[fE[aCF5]], 14],
              StringPadRight[ToString[fE[aCF7]], 14],
              StringPadRight[ToString[fE[aCF9]], 14]];
        <|"n" -> n, "exact" -> N[aEx, 6],
          "rel_CLN3_alone" -> N[If[Abs[aEx] > 0, Abs[(aN3 - aEx)/aEx], 0]],
          "rel_CLN3_CF5"   -> N[If[Abs[aEx] > 0, Abs[(aCF5 - aEx)/aEx], 0]],
          "rel_CLN3_CF7"   -> N[If[Abs[aEx] > 0, Abs[(aCF7 - aEx)/aEx], 0]],
          "rel_CLN3_CF9"   -> N[If[Abs[aEx] > 0, Abs[(aCF9 - aEx)/aEx], 0]]|>],
      {n, 0, 8}]];

  (* === Sub-test (4): Hybrid CLN_3 + CF(N=4) vs Multi-K basis 7 --- *)
  Print[""];
  Print["  --- Sub-test (4): A-axis hybrid CLN_3+CF(N=4) vs Multi-K basis 7 ---"];
  Module[{xi4, w4, yEx, yR, wallErr, rProbe, axisHy, axisMK},
    {xi4, w4} = cfNodes[4, xiMin, xiMax];
    wallErr = Max[Table[
      Module[{om = 2 Pi f},
        yEx = YExactFoster[om];
        yR  = YCFSchur[QCLN3, om, xi4, w4];
        Abs[(yR - yEx)/yEx]], {f, freqWallTmp}]];
    rProbe = Module[{om = 2 Pi 1*^12, yR2},
      yR2 = YCFSchur[QCLN3, om, xi4, w4];
      Abs[yR2] Sqrt[om] / KSIBC3D];
    axisHy = <|"name" -> "CLN_3 + CF(N=4)", "basis" -> 7,
               "wall" -> N[wallErr], "r_1e12" -> N[rProbe]|>;
    wallErr = Max[Table[
      Module[{om = 2 Pi f},
        yEx = YExactFoster[om];
        yR  = YReducedFromBasis[QMK7, om];
        Abs[(yR - yEx)/yEx]], {f, freqWallTmp}]];
    rProbe = Module[{om = 2 Pi 1*^12, yR2},
      yR2 = YReducedFromBasis[QMK7, om];
      Abs[yR2] Sqrt[om] / KSIBC3D];
    axisMK = <|"name" -> "Multi-K M_0+4pt", "basis" -> 7,
               "wall" -> N[wallErr], "r_1e12" -> N[rProbe]|>;
    Print["  ", StringPadRight[axisHy["name"], 25],
          " basis=", axisHy["basis"], "  wall=",
          NumberForm[100 axisHy["wall"], {6, 2}], "%,  r(1e12)=",
          NumberForm[axisHy["r_1e12"], {6, 4}]];
    Print["  ", StringPadRight[axisMK["name"], 25],
          " basis=", axisMK["basis"], "  wall=",
          NumberForm[100 axisMK["wall"], {6, 2}], "%,  r(1e12)=",
          NumberForm[axisMK["r_1e12"], {6, 4}]]];

  Print[""];
  <|"geom" -> geom, "K_SIBC" -> N[KSIBC3D], "Nmodes" -> Nmodes,
    "d_schur_NR" -> N[dSchur],
    "cf_results" -> cfResults,
    "cf_baxis" -> cfBaxisResults|>];

(* === Per-geometry CF grids (xi range matched to wall + asymptote) ====== *)
(* A1: wall 1e3-1e5 Hz, asymptote up to 1e12 Hz -> xi from 2pi*1e3 to 2pi*1e13 *)
(* 5x2x1: wall 1e5-1e7 Hz, asymptote 1e12 Hz   -> xi from 2pi*1e5 to 2pi*1e13 *)
cfParamsA1    = <|"xi_min" -> 2 Pi 1*^3, "xi_max" -> 2 Pi 1*^13,
                  "N_list" -> {1, 3, 5, 7, 9, 11}|>;
cfParams5x2x1 = <|"xi_min" -> 2 Pi 1*^5, "xi_max" -> 2 Pi 1*^13,
                  "N_list" -> {1, 3, 5, 7, 9, 11}|>;

results = {analyzeCuboid[geometries[[1]], cfParamsA1],
            analyzeCuboid[geometries[[2]], cfParams5x2x1]};

(* === Side-by-side C-axis convergence summary =========================== *)
Print[""];
Print["============================================================"];
Print[" CF-Schur C-axis convergence (r(1e12), target = 1)"];
Print["============================================================"];
Print[StringPadLeft["N", 4], " ",
      StringPadRight["A1 plate r(1e12)", 22],
      StringPadRight["5x2x1 brick r(1e12)", 22]];
Do[Module[{a1 = First[results]["cf_results"][[k]],
            sm = Last[results]["cf_results"][[k]]},
    Print[StringPadLeft[ToString[a1["N"]], 4], " ",
          StringPadRight[ToString[NumberForm[a1["r_1e12"], {7, 5}]], 22],
          StringPadRight[ToString[NumberForm[sm["r_1e12"], {7, 5}]], 22]]],
   {k, Length[First[results]["cf_results"]]}];

(* === Save JSON ========================================================== *)
combinedOut = <|
  "geometries" -> Table[results[[k]]["geom"], {k, Length[results]}],
  "results"    -> Table[
    <|"name"     -> results[[k]]["geom"]["name"],
      "K_SIBC"   -> results[[k]]["K_SIBC"],
      "d_schur_NR" -> results[[k]]["d_schur_NR"],
      "cf_results" -> results[[k]]["cf_results"],
      "cf_baxis"   -> results[[k]]["cf_baxis"]|>,
    {k, Length[results]}]|>;
Export["cuboid3D_CFschur_both.json", combinedOut, "JSON"];
