Print["Saved: bem_disk_axisym_cauer.json (", Length[eigvalsSorted], " modes, ",
      NMOMENTS, " moments)"];

#!/usr/bin/env wolframscript
(*
  bem_disk_axisym_cauer_highprec.wls — high-precision variant of
  bem_disk_axisym_cauer.wls with NMOMENTS=40 and arbitrary precision
  arithmetic for the Eigensystem + Foster amplitudes.

  Track B-ii high-k diagnosis: original n_moments=20 + standard mpmath
  dps=50 produces a sign change in tau_pair at k=6 (cylinder Cu disk).
  This script doubles n_moments and uses N[..., 80] to push the high-k
  Cauer extraction further before round-off ends it.

  Output: bem_disk_axisym_cauer_highprec.json (same schema as
          bem_disk_axisym_cauer.json, just longer alphas array)
*)

mu0 = 4 Pi * 10^-7;
sigma = 5.8 * 10^7;
R = 10 * 10^-3;
t = 2 * 10^-3;
B0 = 1;

(* Same mesh as v3 *)
NR = 80;
Nz = 24;
dr = R / NR;
dz = t / Nz;
ne = NR * Nz;

NMODES = 80;          (* number of Foster modes (was 50) *)
NMOMENTS = 40;        (* number of alpha_n moments (was 20) *)
WP = 80;              (* working precision in digits *)

Print["=== BEM disk axisym for Cauer-I extraction (HIGH PRECISION) ==="];
Print["  R=", R*1000, "mm, t=", t*1000, "mm, NR=", NR, " Nz=", Nz, " ne=", ne];
Print["  modes=", NMODES, " moments=", NMOMENTS, " WP=", WP];

elements = Flatten[Table[{(i - 1/2) dr, (j - 1/2) dz - t/2},
                         {i, 1, NR}, {j, 1, Nz}], 1];
dV = Table[2 Pi elements[[i, 1]] dr dz, {i, 1, ne}];

Gaxi[r1_, z1_, r2_, z2_] := Module[{k2, K1, E1, eps = 1.0*^-15},
  k2 = 4 r1 r2 / ((r1 + r2)^2 + (z1 - z2)^2 + eps);
  K1 = EllipticK[k2];
  E1 = EllipticE[k2];
  (1/(2 Pi^2 Sqrt[r1 r2 + eps] Sqrt[k2])) * ((1 - k2/2) K1 - E1)
];

aEq = Sqrt[dr dz / Pi];
GaxiSelf[r_] := (1/(2 Pi^2 r)) * (Log[8 r / aEq] - 2);

Print["  Building K_sym (", ne, "x", ne, ") at WP=", WP, "..."];
t0 = AbsoluteTime[];

Ksym = Table[
  Module[{r1, z1, r2, z2, gval},
    {r1, z1} = elements[[i]];
    {r2, z2} = elements[[j]];
    If[i === j,
      gval = GaxiSelf[r1],
      gval = Gaxi[r1, z1, r2, z2]
    ];
    N[mu0 * gval * Sqrt[dV[[i]] * dV[[j]]], WP]
  ],
  {i, 1, ne}, {j, 1, ne}
];

Print["    K_sym built in ", AbsoluteTime[] - t0, " s"];

Print["  Solving symmetric eigenvalue problem (top ", NMODES, ", WP=", WP, ")..."];
t0 = AbsoluteTime[];
{eigvals, eigvecs} = Eigensystem[Ksym, NMODES];
Print["    Done in ", AbsoluteTime[] - t0, " s"];

posMask = Table[Re[eigvals[[k]]] > 0, {k, 1, NMODES}];
eigvalsPos = Pick[eigvals, posMask];
eigvecsPos = Pick[eigvecs, posMask];

Print["  Positive-eigenvalue modes kept: ", Length[eigvalsPos], "/", NMODES];

ord = Reverse[Ordering[Re[eigvalsPos]]];
eigvalsSorted = eigvalsPos[[ord]];
eigvecsSorted = eigvecsPos[[ord]];

tausUs = N[sigma * Re[eigvalsSorted] * 10^6, 30];

Print["  tau_1..tau_8 us = ", N[tausUs[[1;;8]], 8]];

aExtSym = Table[N[Sqrt[dV[[i]]] * B0 * elements[[i, 1]] / 2, WP], {i, 1, ne}];

Print["  Computing Foster amplitudes g_k..."];
gAmpl = Table[
  Module[{vk = eigvecsSorted[[k]]},
    Re[vk . aExtSym]
  ],
  {k, 1, Length[eigvalsSorted]}];

Print["  g_1..g_6 = ", N[gAmpl[[1;;Min[6, Length[gAmpl]]]], 6]];

tausSec = sigma * Re[eigvalsSorted];

Print["  Computing ", NMOMENTS, " alpha_n moments..."];
alphasMomLegacy = Table[
  Module[{n = nn},
    Sum[gAmpl[[k]]^2 * tausSec[[k]]^(n + 1) * (-1)^n,
        {k, 1, Length[eigvalsSorted]}]
  ],
  {nn, 0, NMOMENTS - 1}];

Print["  alpha_0..alpha_5 = ", N[alphasMomLegacy[[1;;6]], 6]];

result = <|
  "method" -> "BEM disk axisym + Foster amplitudes + alpha_n moments for Cauer-I (HIGHPREC)",
  "params" -> <|"R_mm" -> R*1000, "t_mm" -> t*1000, "sigma" -> sigma,
                "B0" -> B0, "NR" -> NR, "Nz" -> Nz, "ne" -> ne,
                "n_modes" -> Length[eigvalsSorted], "n_moments" -> NMOMENTS,
                "wp_digits" -> WP|>,
  "bem_tau_us" -> tausUs,
  "bem_eigvals_lambda" -> N[Re[eigvalsSorted], 30],
  "foster_amplitudes_g" -> N[gAmpl, 30],
  "alphas" -> N[alphasMomLegacy, 30],
  "element_r" -> Table[elements[[i, 1]], {i, 1, ne}],
  "element_z" -> Table[elements[[i, 2]], {i, 1, ne}],
  "dV" -> N[dV, 30]
|>;
Export["bem_disk_axisym_cauer_highprec.json", result, "JSON"];
Print[""];
Print["Saved: bem_disk_axisym_cauer_highprec.json (", Length[eigvalsSorted], " modes, ",
      NMOMENTS, " moments, WP=", WP, ")"];

#!/usr/bin/env wolframscript
(*
  Axisymmetric BEM Foster-CLN for Cu disk in vacuum (2026-05-05).

  Computes Foster poles τ_n of eddy current decay in an axisymmetric
  conducting disk via:
    Generalized eigenvalue: τ × M_mass × J = σ × M_BEM × J

  where M_BEM[i, j] = mutual inductance between current ring i and j,
  using axisymmetric Green's function with complete elliptic integrals K, E.

  Output: τ_n = Foster pole spectrum (μs), to be compared with NGSolve v22b
  axisymmetric Cu disk (R=10mm, t=2mm) per-stage Hiruma L_B2 form values.
*)

mu0 = 4 Pi * 10^-7;
sigma = 5.8 * 10^7;        (* Cu *)
R = 10 * 10^-3;            (* disk radius [m] *)
t = 2 * 10^-3;             (* disk thickness [m] *)

(* Discretization *)
NR = 30;        (* radial divisions *)
Nz = 6;         (* axial divisions *)
dr = R / NR;
dz = t / Nz;
ne = NR * Nz;

Print["=== Axisymmetric BEM Foster for Cu disk ==="];
Print["  R=", R*1000, "mm, t=", t*1000, "mm, sig=", sigma];
Print["  NR=", NR, ", Nz=", Nz, ", ne=", ne];

(* Element centroids (r_i, z_i) for i = 1..ne *)
elements = Flatten[Table[{(i - 0.5) * dr, (j - 0.5) * dz - t/2},
                         {i, 1, NR}, {j, 1, Nz}], 1];

(* Mutual inductance kernel for current loops at (r1, z1) and (r2, z2):
   M = mu0 * sqrt(r1 r2) * [(2/k - k) K(k^2) - (2/k) E(k^2)]
   where k^2 = 4 r1 r2 / ((r1+r2)^2 + (z1-z2)^2)
   We compute G_BEM = M / mu0 (drop constants for eigenvalue problem since
   they appear on both sides via σ × mu0). Actually we keep mu0 for
   correct physical units of τ. *)

mutualG[r1_, z1_, r2_, z2_] := Module[{k2, K1, E1, eps = 1.0*^-12},
  k2 = 4 r1 r2 / ((r1 + r2)^2 + (z1 - z2)^2 + eps);
  K1 = EllipticK[k2];
  E1 = EllipticE[k2];
  Sqrt[r1 r2] * ((2/Sqrt[k2] - Sqrt[k2]) K1 - (2/Sqrt[k2]) E1)
];

(* Self-term approximation: for ring of radius r with cross-section dr × dz,
   self-inductance (per unit current density) is well-approximated by
   M_self ≈ mu0 r [ln(8 r / a_eq) - 7/4]
   where a_eq is equivalent cross-section radius: a_eq = sqrt(dr × dz / pi) *)

aEq = Sqrt[dr * dz / Pi];
selfM[r_] := mu0 r (Log[8 r / aEq] - 7/4);

Print["  Building BEM matrix (", ne, "×", ne, ")..."];
t0 = AbsoluteTime[];

(* M_BEM[i, j] = mu0 × G_axi(elem_i, elem_j) for i ≠ j
                 = self_M(r_i)             for i == j *)
Mbem = Table[
  Module[{r1, z1, r2, z2, val},
    {r1, z1} = elements[[i]];
    {r2, z2} = elements[[j]];
    If[i === j,
      val = selfM[r1] / (2 Pi),  (* normalize: integrand vs ring inductance *)
      val = mu0 * mutualG[r1, z1, r2, z2]
    ];
    val
  ],
  {i, 1, ne}, {j, 1, ne}
];

Print["    BEM matrix built in ", AbsoluteTime[] - t0, " s"];

(* Mass matrix: diagonal, M_mass[i, i] = 2 pi r_i dr dz (cylindrical volume) *)
Mmass = DiagonalMatrix[Table[2 Pi elements[[i, 1]] dr dz, {i, 1, ne}]];

(* Generalized eigenvalue problem:
   τ × M_mass × J = σ × M_BEM × J
   Equivalent to: σ × M_BEM × J = τ^{-1} × M_mass × J ??? Let me re-derive.

   For Foster pole decay J(t) = J_0 × exp(-t/τ):
   ∂J/∂t = -J/τ
   Faraday + Ohm: J = σ × E = -σ × ∂A/∂t (in conductor)
   A(P) = ∫ G_axi(P, P') × J(P') × dV' (vacuum vector potential from current J)
   So: J = -σ × ∂/∂t [∫ G × J × dV']
   For decay: -J/τ = -σ × ∫ G × J × dV' (with sign flip for ∂/∂t of exp(-t/τ))
   J/τ = σ × ∫ G × J × dV'

   Discretized:
     (1/τ) × M_mass × J = σ × M_BEM × J  (where M_mass = diag(2 π r dr dz))
     τ × σ × M_BEM × J = M_mass × J        (rearranged)

   Or equivalently: σ × M_BEM × J = (1/τ) × M_mass × J
   Eigenvalues e_n = 1/τ_n → τ_n = 1/e_n.
*)

Print["  Solving generalized eigenvalue problem..."];
t0 = AbsoluteTime[];
{eigvals, eigvecs} = Eigensystem[
  {N[sigma * Mbem], N[Mmass]}, 6
];
Print["    Eigensolve done in ", AbsoluteTime[] - t0, " s"];

(* Convert: e_n = 1/τ_n → τ_n = 1/e_n in seconds *)
taus = 1 / Re[eigvals];
tausUs = N[taus, 8] * 10^6;  (* μs *)
tausUsSorted = Reverse[Sort[Select[tausUs, # > 0 &]]];

Print[""];
Print["=== Foster pole spectrum (Cu disk R=", R*1000, "mm, t=", t*1000, "mm) ==="];
Print["  Top ", Length[tausUsSorted], " τ values (μs):"];
Do[
  Print["  τ_", n, " = ", tausUsSorted[[n]], " μs"],
  {n, 1, Length[tausUsSorted]}
];

(* Comparison with NGSolve v22b per-stage τ_B2 *)
v22bTauB2 = {208.32, 77.90, 46.41, 33.19, 25.22, 18.23};
Print[""];
Print["=== Comparison with NGSolve v22b axisymmetric Cu disk ==="];
Print["  Note: v22b uses Hiruma per-stage L_B2 form (canonical)"];
Print["  ", StringPadRight["n", 4], StringPadRight["BEM τ μs", 14],
        StringPadRight["v22b τ_B2 μs", 16], "ratio"];
Do[
  If[n <= Length[tausUsSorted] && n <= Length[v22bTauB2],
    Module[{ratio = tausUsSorted[[n]] / v22bTauB2[[n]]},
      Print["  ",
        StringPadRight[ToString[n], 4],
        StringPadRight[ToString[NumberForm[tausUsSorted[[n]], {6, 4}]], 14],
        StringPadRight[ToString[v22bTauB2[[n]]], 16],
        NumberForm[ratio, {5, 4}]
      ]
    ]
  ],
  {n, 1, 6}
];

(* Save JSON *)
result = <|
  "method" -> "Axisymmetric BEM Foster-CLN for Cu disk",
  "params" -> <|
    "R_mm" -> R * 1000,
    "t_mm" -> t * 1000,
    "sigma" -> sigma,
    "NR" -> NR,
    "Nz" -> Nz,
    "ne" -> ne
  |>,
  "tau_us" -> tausUsSorted,
  "v22b_tau_B2_us_for_compare" -> v22bTauB2
|>;
Export["bem_disk_axisym_foster.json", result, "JSON"];
Print[""];
Print["Saved: bem_disk_axisym_foster.json"];

#!/usr/bin/env wolframscript
(*
  Axisymmetric BEM Foster v4: aim for 1% convergence.
  - NR=200, Nz=60, ne=12000
  - ParallelTable for K matrix construction
  - Improved self-term (Maxwell mutual inductance for adjacent ring)
*)

mu0 = 4 Pi * 10^-7;
sigma = 5.8 * 10^7;
R = 10 * 10^-3;
t = 2 * 10^-3;

NR = 200;
Nz = 60;
dr = R / NR;
dz = t / Nz;
ne = NR * Nz;

Print["=== BEM Foster v4 (converging refinement) ==="];
Print["  R=", R*1000, "mm, t=", t*1000, "mm"];
Print["  NR=", NR, " Nz=", Nz, " ne=", ne, " (K is ", ne, "×", ne, ")"];

elements = Flatten[Table[{(i - 0.5) * dr, (j - 0.5) * dz - t/2},
                         {i, 1, NR}, {j, 1, Nz}], 1];
dV = Table[2 Pi elements[[i, 1]] dr dz, {i, 1, ne}];

Gaxi[r1_, z1_, r2_, z2_] := Module[{k2, K1, E1, eps = 1.0*^-15},
  k2 = 4 r1 r2 / ((r1 + r2)^2 + (z1 - z2)^2 + eps);
  K1 = EllipticK[k2];
  E1 = EllipticE[k2];
  (1/(2 Pi^2 Sqrt[r1 r2 + eps] Sqrt[k2])) * ((1 - k2/2) K1 - E1)
];

aEq = Sqrt[dr dz / Pi];
GaxiSelf[r_] := (1/(2 Pi^2 r)) * (Log[8 r / aEq] - 2);

Print["  Building K_sym in parallel..."];
t0 = AbsoluteTime[];

(* Use ParallelTable for speedup *)
SetSharedFunction[Gaxi, GaxiSelf];
DistributeDefinitions[mu0, dV, elements, Gaxi, GaxiSelf];

Ksym = ParallelTable[
  Module[{r1, z1, r2, z2, gval},
    {r1, z1} = elements[[i]];
    {r2, z2} = elements[[j]];
    If[i === j,
      gval = GaxiSelf[r1],
      gval = Gaxi[r1, z1, r2, z2]
    ];
    mu0 * gval * Sqrt[dV[[i]] * dV[[j]]]
  ],
  {i, 1, ne}, {j, 1, ne}
];

Print["    K_sym built in ", AbsoluteTime[] - t0, " s"];

Print["  Solving symmetric eigenvalue problem (top 8)..."];
t0 = AbsoluteTime[];
{eigvals, eigvecs} = Eigensystem[N[Ksym], 8];
Print["    Done in ", AbsoluteTime[] - t0, " s"];

positiveEigs = Select[Re[eigvals], # > 0 &];
tausUs = N[sigma * positiveEigs * 10^6, 8];
tausUsSorted = Reverse[Sort[tausUs]];

Print[""];
Print["=== BEM v4 Foster pole spectrum ==="];
Do[
  If[n <= Length[tausUsSorted],
    Print["  tau_", n, " = ", NumberForm[tausUsSorted[[n]], {6, 4}], " us"]
  ],
  {n, 1, 8}
];

(* Comparison vs v22b NGSolve and v3 *)
v22bTauB2 = {208.32, 77.90, 46.41, 33.19, 25.22, 18.23};
v3Tau = {224.31, 88.42, 49.54, 32.09, 23.34, 22.59};

Print[""];
Print["=== Convergence comparison ==="];
Print[StringJoin[
  StringPadRight["n", 4],
  StringPadRight["BEM v2 (ne=180)", 17],
  StringPadRight["BEM v3 (ne=1920)", 18],
  StringPadRight["BEM v4 (ne=12000)", 19],
  StringPadRight["v22b NGSolve", 14],
  "v4/v22b"
]];
v2Tau = {228.0, 91.6, 52.6, 35.0, 26.6, 25.4};
Do[
  Module[{v2, v3, v4, v22, ratio},
    v2 = If[n <= 6, v2Tau[[n]], 0];
    v3 = If[n <= 6, v3Tau[[n]], 0];
    v4 = If[n <= Length[tausUsSorted], tausUsSorted[[n]], 0];
    v22 = If[n <= Length[v22bTauB2], v22bTauB2[[n]], 0];
    ratio = If[v22 > 0, v4 / v22, 0];
    Print[StringJoin[
      StringPadRight[ToString[n], 4],
      StringPadRight[ToString[NumberForm[v2, {6, 3}]], 17],
      StringPadRight[ToString[NumberForm[v3, {6, 3}]], 18],
      StringPadRight[ToString[NumberForm[v4, {6, 3}]], 19],
      StringPadRight[ToString[NumberForm[v22, {6, 3}]], 14],
      ToString[NumberForm[ratio, {5, 4}]]
    ]]
  ],
  {n, 1, 6}
];

result = <|
  "method" -> "BEM v4 axisymmetric Cu disk (vacuum, refined)",
  "params" -> <|"R_mm" -> R*1000, "t_mm" -> t*1000, "sigma" -> sigma,
                "NR" -> NR, "Nz" -> Nz, "ne" -> ne|>,
  "tau_us_v4" -> tausUsSorted,
  "tau_us_v3" -> v3Tau,
  "tau_us_v2" -> v2Tau,
  "v22b_tau_B2" -> v22bTauB2
|>;
Export["bem_disk_axisym_v4_converge.json", result, "JSON"];
Print[""];
Print["Saved: bem_disk_axisym_v4_converge.json"];

(* BEM-Foster Phase 2: alpha_2 validation on Cartesian hex grid.

   Strategy:
   - Discretize cuboid Omega = [-a/2,a/2] x [-b/2,b/2] x [-c/2,c/2]
     into Nx x Ny x Nz uniform hex cells with piecewise-constant basis.
   - Cell-cell Newton matrix K_{ij} = int_{Omega_i} int_{Omega_j} 1/|r-r'| dVdV'
     reduced to 3D via change of variables u = r - r':
       K_ij(d) = int_{|u_a|<h_a} prod_a(h_a - |u_a|) / |u + d| du,  d = r_i - r_j
   - alpha_2^BEM = (mu0 sigma)^2 / (16 pi V) * sum_{ij} (x_i x_j + y_i y_j) K_{ij}
     (midpoint quadrature; expected at least O(h) convergence, possibly O(h^2)
     by symmetric-error cancellation).
   - Compare to closed form alpha_2 = 7.4783e-10
     (cuboid_3D_vacuum_Born_alpha2_closed.wls, 30+ digit Aharoni 6D).

   Date: 2026-05-01
*)

$HistoryLength = 0;
prec = 25;

Print["================================================================"];
Print["BEM-Foster Phase 2: alpha_2 validation (Cartesian hex grid)"];
Print["================================================================"];
Print[""];

(* === Constants === *)
sigmaN = SetPrecision[58 10^6, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
PiN = SetPrecision[Pi, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
VN = aN bN cN;

Print["Material : Cu, sigma = ", N[sigmaN, 6], " S/m"];
Print["Geometry : ", N[aN 1000, 4], " x ", N[bN 1000, 4],
      " x ", N[cN 1000, 4], " mm  (V = ", N[VN, 6], " m^3)"];
Print[""];

alpha2Closed = SetPrecision[7.47832405353*^-10, 16];
Print["alpha_2 (closed form, Born/Aharoni 6D): ", alpha2Closed];
Print[""];

(* === Cell-cell Newton kernel === *)
(* Off-diagonal (d != 0): smooth integrand. *)
cellNewtonOff[dx_, dy_, dz_, hx_, hy_, hz_] :=
  NIntegrate[
    (hx - Abs[u])(hy - Abs[v])(hz - Abs[w])/
      Sqrt[(u + dx)^2 + (v + dy)^2 + (w + dz)^2],
    {u, -hx, hx}, {v, -hy, hy}, {w, -hz, hz},
    WorkingPrecision -> 20, AccuracyGoal -> 14, PrecisionGoal -> 12,
    MaxRecursion -> 14, Method -> "GlobalAdaptive"];

(* Self-cell (d = 0): exploit octant symmetry, 1/r corner singularity. *)
cellNewtonSelf[hx_, hy_, hz_] :=
  8 NIntegrate[
    (hx - u)(hy - v)(hz - w)/Sqrt[u^2 + v^2 + w^2],
    {u, 0, hx}, {v, 0, hy}, {w, 0, hz},
    WorkingPrecision -> 20, AccuracyGoal -> 14, PrecisionGoal -> 12,
    MaxRecursion -> 16, Method -> "GlobalAdaptive"];

cellNewton[dx_, dy_, dz_, hx_, hy_, hz_] :=
  If[dx == 0 && dy == 0 && dz == 0,
    cellNewtonSelf[hx, hy, hz],
    cellNewtonOff[dx, dy, dz, hx, hy, hz]];

(* === Sanity check: unit cube self-energy === *)
Print["=== Sanity check ==="];
t0 = AbsoluteTime[];
KselfUnit = cellNewtonSelf[1, 1, 1];
Print["  K_self(unit cube) = ", N[KselfUnit, 14],
      "  (", N[AbsoluteTime[] - t0, 3], " s)"];
Print["  Expected: ~1.88231264338  (literature, e.g. Hummer 1996)"];
Print[""];

(* === Build BEM matrix and compute alpha_2 === *)
buildAndCompute[Nx_, Ny_, Nz_] := Module[
  {hx, hy, hz, ncells, centers, K, di, t0, xs, ys, Dxx, Dyy,
   alpha2BEM, err, cache, key, val, dt},
  hx = aN/Nx; hy = bN/Ny; hz = cN/Nz;
  ncells = Nx Ny Nz;

  centers = Flatten[
    Table[
      {(i - 1/2)hx - aN/2, (j - 1/2)hy - bN/2, (k - 1/2)hz - cN/2},
      {i, Nx}, {j, Ny}, {k, Nz}],
    2];

  Print["  Grid (", Nx, ", ", Ny, ", ", Nz, "): ",
        ncells, " cells, ", ncells (ncells + 1)/2, " pairs"];
  t0 = AbsoluteTime[];

  (* Translation-invariance cache: K_ij depends on (|delta_i|, |delta_j|, |delta_k|)
     since the kernel integrand is even in each component of d. *)
  cache = <||>;
  K = ConstantArray[0, {ncells, ncells}];
  Do[
    di = centers[[i]] - centers[[j]];
    key = Abs[Round[di/{hx, hy, hz}]];
    val = Lookup[cache, Key[key], $Failed];
    If[val === $Failed,
      val = cellNewton[di[[1]], di[[2]], di[[3]], hx, hy, hz];
      cache[key] = val];
    K[[i, j]] = val;
    K[[j, i]] = val,
    {i, ncells}, {j, i, ncells}];
  dt = AbsoluteTime[] - t0;
  Print["    K assembly: ", N[dt, 4], " s, ",
        Length[cache], " unique kernel values"];

  xs = centers[[All, 1]];
  ys = centers[[All, 2]];
  Dxx = xs.K.xs;
