(* Task A: Fourier-based K element — verification.

   For vacuum 3D problem, Foster eigenmode integrals are:
     K_{(p_1q_1r_1),(p_2q_2r_2)} = int int x^{p_1}y^{q_1}z^{r_1} x'^{p_2}y'^{q_2}z'^{r_2} / |r-r'| dV dV'

   After variable change u = r - r', polynomial integration over R = (r+r')/2,
   reduces to 3D integral over u with weight g_x(xi) g_y(eta) g_z(zeta) divided by |u|.

   Fourier path:
     1/|u| = (1/(2 pi^2)) int_R^3 e^{i k.u} / k^2 d^3 k
   So K = 8 int_{[0,h_x]x[0,h_y]x[0,h_z]} g_x g_y g_z / |u| du
        = (8/(2 pi^2)) int_R^3 G_x(k_x) G_y(k_y) G_z(k_z) / k^2 d^3 k
   where G_alpha(k_alpha) = int_0^{h_alpha} g_alpha(xi) cos(k_alpha xi) d xi
   (taking real part since g_alpha and 1/|u| are real).

   Test 1: K[(0,0,0),(0,0,0)] = 8 * int_0^a int_0^b int_0^c 1/r du dv dw
   This equals 8 * Aharoni0 (octant self-integral). We have closed form at WP=50.

   Date: 2026-05-02
*)

$HistoryLength = 0;
prec = 50;

Print["================================================================"];
Print["Task A: Fourier-based K element verification"];
Print["WorkingPrecision = ", prec];
Print["================================================================"];
Print[""];

aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
PiN = SetPrecision[Pi, prec];

(* === Direct: existing Aharoni0 closed form (v3 verified) === *)
t0 = AbsoluteTime[];
Aharoni0Direct = NIntegrate[1/Sqrt[xi^2 + eta^2 + zeta^2],
  {xi, 0, aN}, {eta, 0, bN}, {zeta, 0, cN},
  WorkingPrecision -> prec, AccuracyGoal -> prec - 5,
  PrecisionGoal -> prec - 8, MaxRecursion -> 16];
Print["Direct Aharoni0 (3D NIntegrate at WP=", prec, "):"];
Print["  ", N[Aharoni0Direct, 30], "  (", N[AbsoluteTime[] - t0, 4], " s)"];
Print[""];

(* === Fourier path === *)
(* For p=q=0, the weight g_alpha = 1 on [0, h_alpha].
   Fourier: G(k) = int_0^h cos(k xi) dxi = sin(kh)/k. *)
ClearAll[Gconst];
Gconst[h_, k_] := Sin[k h]/k;

(* K[(0,0,0),(0,0,0)] / 8 = (1/(2 pi^2)) int_R^3 G_x G_y G_z / k^2 d^3 k
   In spherical coords: d^3 k = k^2 sin(theta) dk dtheta dphi
   k_x = k sin(theta) cos(phi), k_y = k sin(theta) sin(phi), k_z = k cos(theta).

   K_self_octant = (1/(2 pi^2)) int_R^3 G_x(k_x) G_y(k_y) G_z(k_z) / k^2 d^3 k
                 = (1/(2 pi^2)) int_0^inf dk int_0^pi sin(theta) dtheta int_0^{2pi} dphi G_x G_y G_z
                   (k^2 cancels with k^2 sin(theta))

   Wait: d^3 k = k^2 sin(theta) dk dtheta dphi, divided by k^2 = sin(theta) dk dtheta dphi.
*)
Print["Fourier path verification:"];
Print["  G_x(k) = Sin[k a] / k for unit-weight g_x"];
Print["  G_y(k) = Sin[k b] / k"];
Print["  G_z(k) = Sin[k c] / k"];
Print[""];

(* Try integrating over (theta, phi, k) numerically first *)
Print["Step 1: 3D k-integral via NIntegrate (verify physics)"];
t0 = AbsoluteTime[];
AharoniFourier = (1/(2 PiN^2)) NIntegrate[
  Gconst[aN, k Sin[theta] Cos[phi]] *
  Gconst[bN, k Sin[theta] Sin[phi]] *
  Gconst[cN, k Cos[theta]] *
  Sin[theta],
  {k, 0, Infinity}, {theta, 0, PiN}, {phi, 0, 2 PiN},
  WorkingPrecision -> 30, AccuracyGoal -> 20,
  PrecisionGoal -> 15, MaxRecursion -> 12,
  Method -> "GlobalAdaptive"];
Print["  K_self_octant (Fourier path NIntegrate at WP=30) = ",
  N[AharoniFourier, 16],
  "  (", N[AbsoluteTime[] - t0, 4], " s)"];
Print[""];
Print["  Compare to direct Aharoni0 = ", N[Aharoni0Direct, 16]];
Print["  Ratio = ", N[AharoniFourier/Aharoni0Direct, 16]];
Print[""];

(* === Try closed form via Mathematica Integrate === *)
Print["Step 2: Try Integrate[] for full closed form (5 min timeout)"];
t0 = AbsoluteTime[];
AharoniClosedTry = TimeConstrained[
  Integrate[
    (1/(2 PiN^2)) *
    (Sin[k Sin[theta] Cos[phi] aN]/(k Sin[theta] Cos[phi])) *
    (Sin[k Sin[theta] Sin[phi] bN]/(k Sin[theta] Sin[phi])) *
    (Sin[k Cos[theta] cN]/(k Cos[theta])) *
    Sin[theta],
    {k, 0, Infinity}, {theta, 0, PiN}, {phi, 0, 2 PiN}],
  300, $Failed];
Print["  Time: ", N[AbsoluteTime[] - t0, 4], " s"];
If[AharoniClosedTry === $Failed,
  Print["  Integrate timed out. Closed form not directly achievable."],
  Print["  Closed form: ", AharoniClosedTry];
  Print["  Numeric: ", N[AharoniClosedTry, 30]]];

(* Mathematica K matrix exporter for Python.

   Computes K_mon[(p1,q1,r1),(p2,q2,r2)] for spectral basis at WP=50,
   stores as JSON for Python to load.

   This is the AUTHORITATIVE K matrix calculation, since Mathematica's
   NIntegrate GlobalAdaptive handles the corner log-singularity correctly
   (mpmath.quad limited to ~15 digits).

   Output: bem_foster_K_export_P{P_max}.json with K elements at 30 digit precision.

   Date: 2026-05-02
*)

$HistoryLength = 0;
prec = 50;
PmaxArg = 4;  (* default; set via wolframscript -file ... -PmaxArg N *)
If[Length[$ScriptCommandLine] >= 2,
  PmaxArg = ToExpression[$ScriptCommandLine[[2]]]];

Print["================================================================"];
Print["Mathematica K matrix exporter (WP=", prec, ", P=", PmaxArg, ")"];
Print["================================================================"];

aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];

(* Inner u-integration *)
ClearAll[gAxisPos];
gAxisPos[p1_Integer, p2_Integer, h_, xi_] := gAxisPos[p1, p2, h, xi] =
  Expand[Integrate[(u + xi/2)^p1 (u - xi/2)^p2,
    {u, xi/2 - h/2, h/2 - xi/2},
    Assumptions -> {xi > 0, xi < h, h > 0}]];

(* 1D-closed inner xi integration *)
ClearAll[IxiClosed];
IxiClosed[p1_Integer, p2_Integer, h_, R_] := IxiClosed[p1, p2, h, R] = Module[
  {xi, gPoly, result},
  gPoly = gAxisPos[p1, p2, h, xi];
  result = Integrate[gPoly/Sqrt[xi^2 + R^2], {xi, 0, h},
    Assumptions -> {h > 0, R > 0}];
  Simplify[result, Assumptions -> {h > 0, R > 0}]];

(* K element via 2D NIntegrate *)
ClearAll[KMon];
KMon[{p1_, q1_, r1_}, {p2_, q2_, r2_}] := KMon[{p1, q1, r1}, {p2, q2, r2}] = Module[
  {eta, zeta, R, ixi, gyExpr, gzExpr, integrand, val},
  R = Sqrt[eta^2 + zeta^2];
  ixi = IxiClosed[p1, p2, aN, R];
  gyExpr = gAxisPos[q1, q2, bN, eta];
  gzExpr = gAxisPos[r1, r2, cN, zeta];
  integrand = ixi * gyExpr * gzExpr;
  val = 8 NIntegrate[integrand,
    {eta, 0, bN}, {zeta, 0, cN},
    WorkingPrecision -> prec, AccuracyGoal -> prec - 5,
    PrecisionGoal -> prec - 8, MaxRecursion -> 16,
    Method -> "GlobalAdaptive"];
  val];

(* Build basis (e,o,e) and (o,e,e) parities *)
buildBasis[Pmax_, parity_] := Module[{px, py, pz, basis},
  {px, py, pz} = parity;
  basis = {};
  Do[
    If[Mod[p, 2] == px && Mod[q, 2] == py && Mod[r, 2] == pz && p + q + r <= Pmax,
      AppendTo[basis, {p, q, r}]],
    {p, 0, Pmax}, {q, 0, Pmax - p}, {r, 0, Pmax - p - q}];
  basis];

basisX = buildBasis[PmaxArg, {0, 1, 0}];
basisY = buildBasis[PmaxArg, {1, 0, 0}];
nX = Length[basisX]; nY = Length[basisY];
Print["x-block (e,o,e): ", nX, " functions"];
Print["y-block (o,e,e): ", nY, " functions"];

(* Compute K matrices *)
Print[""];
Print["Building K_mon for x-block..."];
t0 = AbsoluteTime[];
KX = ConstantArray[0, {nX, nX}];
Do[
  Module[{val = KMon[basisX[[i]], basisX[[j]]]},
    KX[[i, j]] = val;
    KX[[j, i]] = val],
  {i, nX}, {j, i, nX}];
Print["  done: ", N[AbsoluteTime[] - t0, 4], " s"];

Print["Building K_mon for y-block..."];
t0 = AbsoluteTime[];
KY = ConstantArray[0, {nY, nY}];
Do[
  Module[{val = KMon[basisY[[i]], basisY[[j]]]},
    KY[[i, j]] = val;
    KY[[j, i]] = val],
  {i, nY}, {j, i, nY}];
Print["  done: ", N[AbsoluteTime[] - t0, 4], " s"];

(* Export to JSON with high-precision string format *)
KEntryToJSON[i_, j_, val_] :=
  <|"i" -> i - 1, "j" -> j - 1, "value" -> ToString[CForm[N[val, 30]]]|>;

KMatrixToJSON[Kmat_, n_] :=
  Flatten[Table[KEntryToJSON[i, j, Kmat[[i, j]]], {i, n}, {j, n}]];

filename = "bem_foster_K_export_P" <> ToString[PmaxArg] <> ".json";

Export[filename,
  <|"P_max" -> PmaxArg,
    "WP" -> prec,
    "a" -> ToString[N[aN, 30], InputForm],
    "b" -> ToString[N[bN, 30], InputForm],
    "c" -> ToString[N[cN, 30], InputForm],
    "x_block" -> <|
      "basis" -> basisX,
      "K_elements" -> KMatrixToJSON[KX, nX]
    |>,
    "y_block" -> <|
      "basis" -> basisY,
      "K_elements" -> KMatrixToJSON[KY, nY]
    |>
  |>];

Print[""];
Print["Saved K matrices to: ", filename];
Print["  x-block: ", nX, "x", nX, " = ", nX*nX, " entries"];
Print["  y-block: ", nY, "x", nY, " = ", nY*nY, " entries"];

(* Issue 5 fix: re-test Legendre vs monomial at higher P to verify benefit.

   At P=8 the monomial basis has condition number issues from scale variation
   (x^p magnitudes range over many decades for cuboid 5x2x1 mm).
   Legendre polynomials should mitigate this and improve numerical stability.

   We compare:
   - Monomial (v1 spectral approach)
   - Legendre (v3 approach)
   at P=8 WP=30 (faster than WP=50 to make P=8 feasible).

   Date: 2026-05-01
*)

$HistoryLength = 0;
prec = 30;

Print["================================================================"];
Print["Issue 5: Legendre vs monomial at P=8 WP=30"];
Print["================================================================"];
Print[""];

sigmaN = SetPrecision[58 10^6, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
PiN = SetPrecision[Pi, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
VN = aN bN cN;
mu0sigmaN = mu0N sigmaN;

alpha1Ref = -mu0sigmaN (aN^2 + bN^2)/48;
alpha2Ref = SetPrecision[7.4783240521932061573535486933*^-10, 28];
tau1Ref = alpha2Ref/(-alpha1Ref);

(* === Inner u-integration === *)
ClearAll[gAxisPos];
gAxisPos[p1_Integer, p2_Integer, h_, xi_] := gAxisPos[p1, p2, h, xi] =
  Expand[Integrate[(u + xi/2)^p1 (u - xi/2)^p2,
    {u, xi/2 - h/2, h/2 - xi/2},
    Assumptions -> {xi > 0, xi < h, h > 0}]];

ClearAll[KelementMon];
KelementMon[{p1_, q1_, r1_}, {p2_, q2_, r2_}] := KelementMon[{p1, q1, r1}, {p2, q2, r2}] =
  Module[{xi, eta, zeta, gxE, gyE, gzE},
    gxE = gAxisPos[p1, p2, aN, xi];
    gyE = gAxisPos[q1, q2, bN, eta];
    gzE = gAxisPos[r1, r2, cN, zeta];
    8 NIntegrate[gxE gyE gzE/Sqrt[xi^2 + eta^2 + zeta^2],
      {xi, 0, aN}, {eta, 0, bN}, {zeta, 0, cN},
      WorkingPrecision -> prec, AccuracyGoal -> prec - 5,
      PrecisionGoal -> prec - 8, MaxRecursion -> 14,
      Method -> "GlobalAdaptive"]];

massAxis[n_, h_] := If[OddQ[n], 0, h^(n + 1)/((n + 1) 2^n)];
ClearAll[Melement];
Melement[{p1_, q1_, r1_}, {p2_, q2_, r2_}] := Melement[{p1, q1, r1}, {p2, q2, r2}] =
  massAxis[p1 + p2, aN] massAxis[q1 + q2, bN] massAxis[r1 + r2, cN];

(* === Build basis === *)
Pmax = 8;
basisX = {};
Do[
  If[Mod[p, 2] == 0 && Mod[q, 2] == 1 && Mod[r, 2] == 0 && p + q + r <= Pmax,
    AppendTo[basisX, {p, q, r}]],
  {p, 0, Pmax}, {q, 0, Pmax - p}, {r, 0, Pmax - p - q}];
nX = Length[basisX];
Print["Basis (e,o,e) at P=", Pmax, ": ", nX, " functions"];
Print[""];

(* === Build K (monomial) === *)
Print["Building K_mon (one-time)..."];
t0 = AbsoluteTime[];
KMon = Table[KelementMon[basisX[[i]], basisX[[j]]], {i, nX}, {j, nX}];
Print["  K_mon assembly: ", N[AbsoluteTime[] - t0, 4], " s"];

MMon = Table[Melement[basisX[[i]], basisX[[j]]], {i, nX}, {j, nX}];

(* === Method 1: Monomial + Cholesky === *)
Print[""];
Print["=== Method 1: Monomial basis + Cholesky ==="];
t0 = AbsoluteTime[];
condMon = N[Sqrt[Max[Eigenvalues[N[MMon, prec]]]/Min[Eigenvalues[N[MMon, prec]]]], 6];
Print["  M_mon condition number: ", condMon];
LMon = CholeskyDecomposition[MMon];
LMonInv = Inverse[LMon];
KMonHat = Transpose[LMonInv].KMon.LMonInv;
{eigvalsMon, eigvecsMonRaw} = Eigensystem[N[KMonHat, prec]];
eigvecsMon = (LMonInv.#) & /@ eigvecsMonRaw;
Print["  eigvalue solve: ", N[AbsoluteTime[] - t0, 4], " s"];

(* === Method 2: Legendre (mass diagonal, no Cholesky) === *)
Print[""];
Print["=== Method 2: Legendre basis (mass diagonal) ==="];
t0 = AbsoluteTime[];

(* Legendre transformation: T[P,p] = coefficient of x^p in P_n(2x/h) *)
ClearAll[legendreT];
legendreT[Pmax_, h_] := legendreT[Pmax, h] = Module[{T, n, k, c},
  T = ConstantArray[0, {Pmax + 1, Pmax + 1}];
  Do[
    c = CoefficientList[LegendreP[n, x], x];
    Do[T[[n + 1, k + 1]] = c[[k + 1]] (2/h)^k, {k, 0, n}],
    {n, 0, Pmax}];
  T];

Tx = legendreT[Pmax, aN]; Ty = legendreT[Pmax, bN]; Tz = legendreT[Pmax, cN];

(* Build basis transformation: TblockI[I, J] = T_x[P_I, p_J] T_y[Q_I, q_J] T_z[R_I, r_J]
   indexing same basis tuple, treated as Legendre orders for I, monomial orders for J. *)
TblockL = Table[
  Module[{P, Q, R, p, q, r},
    {P, Q, R} = basisX[[i]];
    {p, q, r} = basisX[[j]];
    Tx[[P + 1, p + 1]] Ty[[Q + 1, q + 1]] Tz[[R + 1, r + 1]]],
  {i, nX}, {j, nX}];

(* K in Legendre = TblockL . KMon . Transpose[TblockL] *)
KLeg = TblockL.KMon.Transpose[TblockL];

(* Mass diagonal in Legendre *)
massDiag = Table[
  Module[{P, Q, R}, {P, Q, R} = basisX[[i]];
    aN/(2 P + 1) bN/(2 Q + 1) cN/(2 R + 1)],
  {i, nX}];

(* M-orthonormal: K_norm[I, J] = K_Leg[I, J] / sqrt(mass[I] mass[J]) *)
KLegNorm = Table[KLeg[[i, j]]/Sqrt[massDiag[[i]] massDiag[[j]]], {i, nX}, {j, nX}];

condLeg = N[Max[massDiag]/Min[massDiag], 6];
Print["  M_leg condition number (= max_M/min_M): ", condLeg];

{eigvalsLeg, eigvecsLegRaw} = Eigensystem[N[KLegNorm, prec]];
(* Transform back to monomial basis *)
eigvecsLeg = Table[
  Transpose[TblockL].(eigvecsLegRaw[[k]]/Sqrt[massDiag]),
  {k, nX}];
Print["  eigvalue solve: ", N[AbsoluteTime[] - t0, 4], " s"];

(* === Compare results === *)
Print[""];
Print["================================================================"];
Print["Comparison: Monomial vs Legendre at P=8"];
Print["================================================================"];

(* Project A_ext on each *)
aExtMon = ConstantArray[0, nX];
idx010 = Position[basisX, {0, 1, 0}, 1][[1, 1]];
aExtMon[[idx010]] = -1/2;

(* Foster amplitudes *)
gMon = (eigvecsMon.MMon.aExtMon);
gLeg = (eigvecsLeg.MMon.aExtMon);

lambdaMon = eigvalsMon/(4 PiN);
lambdaLeg = eigvalsLeg/(4 PiN);

(* Compute alpha_n via both *)
NMoments = 6;
alphasMon = Table[
  (-1)^n (mu0sigmaN)^n/VN Total[gMon^2 lambdaMon^(n - 1)],
  {n, 1, NMoments}];
alphasLeg = Table[
  (-1)^n (mu0sigmaN)^n/VN Total[gLeg^2 lambdaLeg^(n - 1)],
  {n, 1, NMoments}];

Print["alpha_n (x-block only):"];
Do[
  Print["  alpha_", n, " mon = ", N[alphasMon[[n]], 16],
        "  leg = ", N[alphasLeg[[n]], 16],
        "  diff = ", N[alphasMon[[n]] - alphasLeg[[n]], 6]],
  {n, NMoments}];
Print[""];

(* Eigvalue precision: how close are largest few eigenvalues? *)
ordMon = Reverse[Ordering[N[Re[eigvalsMon], 6]]];
ordLeg = Reverse[Ordering[N[Re[eigvalsLeg], 6]]];
Print["Largest 5 eigenvalues:"];
Do[
  Print["  k=", k, " mon = ", N[eigvalsMon[[ordMon[[k]]]], 16],
        "  leg = ", N[eigvalsLeg[[ordLeg[[k]]]], 16]],
  {k, 5}];

(* Task B: Pure Legendre spectral BEM for vacuum 3D problem.

   Use shifted Legendre polynomials L_p(2x/a) directly as basis (no monomial detour).
   Key benefits:
   - Mass matrix DIAGONAL: M_{(P,Q,R),(P',Q',R')} = (a/(2P+1))(b/(2Q+1))(c/(2R+1)) delta
   - No Cholesky needed, just element-wise division by sqrt(mass)
   - Better numerical conditioning at high P (vs monomial which has cond ~ 10^21 at P=8)

   Method:
   - Cell-cell K_legendre[(P,Q,R),(P',Q',R')] = int int L_P(2x/a) L_Q(2y/b) L_R(2z/c)
       L_{P'}(2x'/a) L_{Q'}(2y'/b) L_{R'}(2z'/c) / |r-r'| dV dV'
   - Compute via Legendre's coefficient list -> sum of monomial K elements
     K_leg[I,J] = sum_{i,j} T_I[i] T_J[j] K_mon[i,j] where T_I[i] = coef of x^p y^q z^r in L_P L_Q L_R

   Run at P=8, P=10 to demonstrate scaling behavior.

   Date: 2026-05-02
*)

$HistoryLength = 0;
prec = 50;

Print["================================================================"];
Print["Task B: Pure Legendre spectral BEM (vacuum 3D)"];
Print["WorkingPrecision = ", prec];
Print["================================================================"];
Print[""];

sigmaN = SetPrecision[58 10^6, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
PiN = SetPrecision[Pi, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
VN = aN bN cN;
mu0sigmaN = mu0N sigmaN;

alpha1Ref = -mu0sigmaN (aN^2 + bN^2)/48;
alpha2RefNew = SetPrecision[7.4783240535434074691212813799*^-10, 28];
tau1Ref = alpha2RefNew/(-alpha1Ref);

Print["Reference values (NEW closed form, 1D-closed + 2D-NIntegrate WP=60):"];
Print["  alpha_2 = ", alpha2RefNew];
Print["  tau_1   = ", N[tau1Ref 10^6, 16], " us"];
Print[""];

(* === Inner u-integration (monomial basis) === *)
ClearAll[gAxisPos];
gAxisPos[p1_Integer, p2_Integer, h_, xi_] := gAxisPos[p1, p2, h, xi] =
  Expand[Integrate[(u + xi/2)^p1 (u - xi/2)^p2,
    {u, xi/2 - h/2, h/2 - xi/2},
    Assumptions -> {xi > 0, xi < h, h > 0}]];

ClearAll[KMon];
KMon[{p1_, q1_, r1_}, {p2_, q2_, r2_}] := KMon[{p1, q1, r1}, {p2, q2, r2}] =
  Module[{xi, eta, zeta, gxE, gyE, gzE},
    gxE = gAxisPos[p1, p2, aN, xi];
    gyE = gAxisPos[q1, q2, bN, eta];
    gzE = gAxisPos[r1, r2, cN, zeta];
    8 NIntegrate[gxE gyE gzE/Sqrt[xi^2 + eta^2 + zeta^2],
      {xi, 0, aN}, {eta, 0, bN}, {zeta, 0, cN},
      WorkingPrecision -> prec, AccuracyGoal -> prec - 5,
      PrecisionGoal -> prec - 8, MaxRecursion -> 16,
      Method -> "GlobalAdaptive"]];

(* === Legendre coefficient extraction ===
   T[P, p] = coefficient of x^p in L_P(2x/h) for x in [-h/2, h/2]. *)
ClearAll[legendreT];
legendreT[Pmax_, h_] := legendreT[Pmax, h] = Module[{T, n, k, c},
  T = ConstantArray[0, {Pmax + 1, Pmax + 1}];
  Do[
    c = CoefficientList[LegendreP[n, x], x];
    Do[T[[n + 1, k + 1]] = c[[k + 1]] (2/h)^k, {k, 0, n}],
    {n, 0, Pmax}];
  T];

(* === Build basis (e,o,e) === *)
buildBasis[Pmax_, parity_] := Module[{px, py, pz, basis},
  {px, py, pz} = parity;
  basis = {};
  Do[
    If[Mod[p, 2] == px && Mod[q, 2] == py && Mod[r, 2] == pz && p + q + r <= Pmax,
      AppendTo[basis, {p, q, r}]],
    {p, 0, Pmax}, {q, 0, Pmax - p}, {r, 0, Pmax - p - q}];
  basis];

(* === Run for given Pmax === *)
runLegendre[Pmax_] := Module[
  {basis, n, t0, KMonMat, Tx, Ty, Tz, TblockL, KLeg, massDiag,
   KLegStandard, eigvals, eigvecs, gXk, lambdaX, alphas, NMoments,
   tau1BEM, condM},
  basis = buildBasis[Pmax, {0, 1, 0}];
  n = Length[basis];
  Print["=== P_max = ", Pmax, " ==="];
  Print["  Basis (e,o,e): ", n, " functions"];

  Print["  Building K_mon (", n (n + 1)/2, " elements)..."];
  t0 = AbsoluteTime[];
  KMonMat = Table[KMon[basis[[i]], basis[[j]]], {i, n}, {j, n}];
  Print["    K_mon: ", N[AbsoluteTime[] - t0, 4], " s"];

  Tx = legendreT[Pmax, aN];
  Ty = legendreT[Pmax, bN];
  Tz = legendreT[Pmax, cN];

  TblockL = Table[
    Module[{P, Q, R, p, q, r},
      {P, Q, R} = basis[[i]];
      {p, q, r} = basis[[j]];
      Tx[[P + 1, p + 1]] Ty[[Q + 1, q + 1]] Tz[[R + 1, r + 1]]],
    {i, n}, {j, n}];

  KLeg = TblockL.KMonMat.Transpose[TblockL];

  (* Diagonal mass: M[I, I] = a/(2P+1) * b/(2Q+1) * c/(2R+1) *)
  massDiag = Table[
    Module[{P, Q, R}, {P, Q, R} = basis[[i]];
      aN/(2 P + 1) bN/(2 Q + 1) cN/(2 R + 1)],
    {i, n}];

  condM = Max[massDiag]/Min[massDiag];
  Print["  Mass condition (Legendre, diagonal): ", N[condM, 6]];

  (* Standard eigenvalue problem: K_norm[I,J] = K_leg[I,J] / sqrt(massDiag[I] * massDiag[J]) *)
  KLegStandard = Table[KLeg[[i, j]]/Sqrt[massDiag[[i]] massDiag[[j]]], {i, n}, {j, n}];

  Print["  Solving standard eigenvalue (no Cholesky)..."];
  t0 = AbsoluteTime[];
  {eigvals, eigvecs} = Eigensystem[N[KLegStandard, prec]];
  Print["    eigvalue solve: ", N[AbsoluteTime[] - t0, 4], " s"];

  (* Foster amplitudes: project A_ext^x = -B_0 y/2 *)
  (* In Legendre: y = (b/2) L_1(2y/b), so A_ext^x has coefficient -b/4 at (0, 1, 0). *)
  (* In M-orthonormal Legendre: phi_I = L_I/sqrt(mass), so coef = -b/4 * sqrt(mass[(0,1,0)]). *)
  Module[{aExt, idx010, b010},
    aExt = ConstantArray[0, n];
    idx010 = Position[basis, {0, 1, 0}, 1][[1, 1]];
    aExt[[idx010]] = -bN/4 Sqrt[massDiag[[idx010]]];
    gXk = eigvecs.aExt];

  lambdaX = eigvals/(4 PiN);
  NMoments = 8;
  alphas = Table[
    (* x-block contribution only; would double for full but err shows trend *)
    (-1)^n (mu0sigmaN)^n/VN Total[gXk^2 lambdaX^(n - 1)],
    {n, 1, NMoments}];

  Print["  alpha_n (x-block, Legendre):"];
  Do[Print["    alpha_", n, " = ", N[alphas[[n]], 16]], {n, NMoments}];

  alphas];

