   Re-derivation:
     sin(p pi (x+a/2)/a) = cos(p pi/2) sin(p pi x/a) + sin(p pi/2) cos(p pi x/a)
     p even: only sin(p pi x/a) survives -> ODD in x
     p odd:  only cos(p pi x/a) survives -> EVEN in x

   For A_x = (q pi/b) sin(p..x..) cos(q..y..) sin(r..z..):
     even in x : p odd
     cos(q pi (y+b/2)/b) odd in y: q odd
     sin(r pi (z+c/2)/c) even in z: r odd
   Conclusion: parity-allowed indices are p, q, r ALL ODD.
*)

$HistoryLength = 0;
prec = 60;

Print["=== Stage 5a Step 1: Interior Galerkin (closed-form, 60-digit) ==="];
Print[""];

(* Geometry and physics constants at high precision *)
sigmaN = SetPrecision[58000000, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
PiN = SetPrecision[Pi, prec];
VN = aN bN cN;

(* Basis function: psi_{p,q,r}(x,y,z) shifted-sin *)
psi[p_, q_, r_, x_, y_, z_] :=
  Sin[p PiN (x + aN/2)/aN] * Sin[q PiN (y + bN/2)/bN] * Sin[r PiN (z + cN/2)/cN];

(* Vector basis A = curl(z_hat psi) = (d_y psi, -d_x psi, 0) *)
Ax[p_, q_, r_, x_, y_, z_] := D[psi[p, q, r, x, y, z], y];
Ay[p_, q_, r_, x_, y_, z_] := -D[psi[p, q, r, x, y, z], x];

(* curl of A:
   curl(d_y psi, -d_x psi, 0) = (-d_z(-d_x psi), d_z(d_y psi), -d_x d_x psi - d_y d_y psi)
                             = (d_z d_x psi, d_z d_y psi, -(d_xx + d_yy) psi) *)
curlAx[p_, q_, r_, x_, y_, z_] := D[D[psi[p, q, r, x, y, z], z], x];
curlAy[p_, q_, r_, x_, y_, z_] := D[D[psi[p, q, r, x, y, z], z], y];
curlAz[p_, q_, r_, x_, y_, z_] := -(D[D[psi[p, q, r, x, y, z], x], x] +
                                     D[D[psi[p, q, r, x, y, z], y], y]);

(* Sample basis function check (symbolic) *)
Print["Sample basis function (p,q,r) = (1,1,1):"];
Print["  psi(x,y,z) = ", psi[1, 1, 1, xx, yy, zz]];
Print["  A_x(x,y,z) = ", Simplify[Ax[1, 1, 1, xx, yy, zz]]];
Print["  A_y(x,y,z) = ", Simplify[Ay[1, 1, 1, xx, yy, zz]]];
Print[""];

(* Parity-allowed index set: p, q, r all odd *)
Pmax = 3; Qmax = 3; Rmax = 3;  (* truncation: max index value (odd) *)
basisIndices = Flatten[Table[{2 P + 1, 2 Q + 1, 2 R + 1},
  {P, 0, (Pmax - 1)/2}, {Q, 0, (Qmax - 1)/2}, {R, 0, (Rmax - 1)/2}], 2];
nBasis = Length[basisIndices];
Print["Basis size: P_max=", Pmax, ", Q_max=", Qmax, ", R_max=", Rmax,
      " => ", nBasis, " modes"];
Print["First 5 indices: ", basisIndices[[1 ;; Min[5, nBasis]]]];
Print[""];

(* Mass matrix M_ij = <A_i, A_j>_cond = integral A_i.A_j dV over cuboid *)
(* Stiffness K_ij = <curl A_i, curl A_j>_cond *)

(* Use closed-form integral identities for sin*sin and cos*cos:
     int_{-L/2}^{L/2} sin(p pi (x+L/2)/L) sin(p' pi (x+L/2)/L) dx = (L/2) delta_{p,p'}
     same for cos*cos.
*)

(* Helper: 1D inner products with closed forms *)
intSinSin[p_, pp_, L_] := If[p === pp, L/2, 0];
intCosCos[p_, pp_, L_] := If[p === pp, L/2, 0];
intSinCos[p_, pp_, L_] := 0; (* orthogonal *)

(* For our basis with shifted sin/cos: we'll compute by direct integration.
   psi has product structure psi = X(x) Y(y) Z(z) with X = sin(p pi (x+a/2)/a) etc.
   d_y psi = X(x) Y'(y) Z(z)
   d_x psi = X'(x) Y(y) Z(z)
   d_xy psi = X'(x) Y'(y) Z(z)
   d_xz psi = X'(x) Y(y) Z'(z)
   d_xx psi = X''(x) Y(y) Z(z)
   ...
   All matrix entries factor as products of 1D integrals.
*)

(* 1D integrals for basis functions (sin and its derivatives, p,q indices) *)
(* X_p(x) = sin(p pi (x+a/2)/a). Derivatives:
   X_p'(x) = (p pi/a) cos(p pi (x+a/2)/a)
   X_p''(x) = -(p pi/a)^2 sin(p pi (x+a/2)/a) = -(p pi/a)^2 X_p

   Inner products:
   I_SS(p,p',a) := int X_p X_{p'} dx = (a/2) delta_{p,p'}
   I_CC(p,p',a) := int X_p' X_{p'}' dx = (p pi/a)(p' pi/a) (a/2) delta_{p,p'} = (p^2 pi^2)/(2a) delta
   I_S2S2(p,p',a) := int X_p'' X_{p'}'' dx = (p^2 pi^2/a^2)(p'^2 pi^2/a^2) (a/2) delta = (p^4 pi^4)/(2a^3) delta
   I_SC(p,p',a) := int X_p X_{p'}' dx = (p' pi/a) int sin*cos dx
                                       = 0 if p=p', otherwise specific.
   For shifted sin/cos with same period: orthogonal -> 0 always.
*)

intSS[p_, pp_, L_] := If[p === pp, L/2, 0];
intCC[p_, pp_, L_] := If[p === pp, p p PiN^2/(2 L), 0];
intS2S2[p_, pp_, L_] := If[p === pp, p^4 PiN^4/(2 L^3), 0];
intCS[p_, pp_, L_] := 0; (* orthogonal *)
intSC[p_, pp_, L_] := 0;

(* Mass matrix entries:
   M_ij = int (A_i.A_j) dV
        = int (d_y psi_i d_y psi_j + d_x psi_i d_x psi_j) dV
        = int X_i X_j Y_i' Y_j' Z_i Z_j dV   <- d_y term
          + int X_i' X_j' Y_i Y_j Z_i Z_j dV  <- d_x term
        = I_SS(p_i,p_j,a) I_CC(q_i,q_j,b) I_SS(r_i,r_j,c)
          + I_CC(p_i,p_j,a) I_SS(q_i,q_j,b) I_SS(r_i,r_j,c)
   By orthogonality: nonzero only when p_i=p_j AND q_i=q_j AND r_i=r_j.
   Diagonal: M_ii = (a/2)(b/2)(c/2) [(q_i pi/b)^2 + (p_i pi/a)^2]
                  = (a b c/8) pi^2 [(p_i/a)^2 + (q_i/b)^2]
                  = (V/8) pi^2 [(p_i/a)^2 + (q_i/b)^2]
*)

massElement[ip_, jp_] := Module[{p1, q1, r1, p2, q2, r2, term1, term2},
  {p1, q1, r1} = basisIndices[[ip]];
  {p2, q2, r2} = basisIndices[[jp]];
  term1 = intSS[p1, p2, aN] intCC[q1, q2, bN] intSS[r1, r2, cN];
  term2 = intCC[p1, p2, aN] intSS[q1, q2, bN] intSS[r1, r2, cN];
  term1 + term2];

(* Stiffness K_ij = <curl A_i, curl A_j>
   curl A = (d_xz psi, d_yz psi, -(d_xx + d_yy) psi)
   curl A_i . curl A_j = d_xz psi_i d_xz psi_j + d_yz psi_i d_yz psi_j
                       + (d_xx + d_yy) psi_i (d_xx + d_yy) psi_j
   Each term factors via 1D integrals.

   d_xz psi = X' Y Z' => contrib int X_i' X_j' Y_i Y_j Z_i' Z_j' dV
                       = I_CC(p_i,p_j,a) I_SS(q_i,q_j,b) I_CC(r_i,r_j,c)
   d_yz psi = X Y' Z' => I_SS(p,p',a) I_CC(q,q',b) I_CC(r,r',c)
   d_xx psi = X'' Y Z; d_yy psi = X Y'' Z. Their sum:
   (d_xx + d_yy) psi = (-p^2 pi^2/a^2 - q^2 pi^2/b^2) psi
   So contribution = (lambda_i)(lambda_j) I_SS(p,p',a) I_SS(q,q',b) I_SS(r,r',c)
   where lambda = -(p^2/a^2 + q^2/b^2) pi^2
*)
lam2[p_, q_] := PiN^2 (p^2/aN^2 + q^2/bN^2);

stiffElement[ip_, jp_] := Module[{p1, q1, r1, p2, q2, r2, t1, t2, t3},
  {p1, q1, r1} = basisIndices[[ip]];
  {p2, q2, r2} = basisIndices[[jp]];
  t1 = intCC[p1, p2, aN] intSS[q1, q2, bN] intCC[r1, r2, cN];  (* d_xz *)
  t2 = intSS[p1, p2, aN] intCC[q1, q2, bN] intCC[r1, r2, cN];  (* d_yz *)
  t3 = lam2[p1, q1] lam2[p2, q2] *
       intSS[p1, p2, aN] intSS[q1, q2, bN] intSS[r1, r2, cN]; (* d_xx + d_yy *)
  t1 + t2 + t3];

(* Build matrices *)
Print["Building matrices..."];
MMat = Table[massElement[i, j], {i, 1, nBasis}, {j, 1, nBasis}];
KMat = Table[stiffElement[i, j], {i, 1, nBasis}, {j, 1, nBasis}];

Print["Mass matrix is diagonal: ",
  And @@ Flatten@Table[
    If[i =!= j, MMat[[i, j]] === 0, True], {i, 1, nBasis}, {j, 1, nBasis}]];
Print["Stiff matrix is diagonal: ",
  And @@ Flatten@Table[
    If[i =!= j, KMat[[i, j]] === 0, True], {i, 1, nBasis}, {j, 1, nBasis}]];
Print[""];

(* Eigenvalues of K alpha = lambda M alpha (generalized) *)
(* For diagonal matrices, lambda_i = K_ii / M_ii *)
diagEigenvalues = Table[KMat[[i, i]]/MMat[[i, i]], {i, 1, nBasis}];

(* Sort and print *)
sortedEigs = SortBy[Transpose[{basisIndices, diagEigenvalues}], #[[2]] &];
Print["Generalized eigenvalues (K alpha = lambda M alpha), first 8:"];
Print["  (p,q,r) | lambda [m^-2]         | tau = mu0 sigma / lambda [us]"];
Do[Module[{idx, lam, tau, lamStr, tauStr},
  {idx, lam} = sortedEigs[[k]];
  tau = mu0N sigmaN / lam * 10^6;
  lamStr = ToString[CForm[N[lam, 12]]];
  tauStr = ToString[CForm[N[tau, 8]]];
  Print["  ", idx, " | ", StringPadRight[lamStr, 22], " | ", tauStr]],
  {k, 1, Min[8, nBasis]}];
Print[""];

(* Sanity check: lowest mode (1, 1, 1) should give lambda = pi^2 (1/a^2 + 1/b^2 + 1/c^2) *)
Print["Sanity check: lowest mode (p,q,r) = (1,1,1)"];
firstIdx = Position[basisIndices, {1, 1, 1}];
If[Length[firstIdx] > 0,
  Module[{i = firstIdx[[1, 1]], lamComputed, lamAnalytical},
    lamComputed = KMat[[i, i]]/MMat[[i, i]];
    lamAnalytical = PiN^2 (1/aN^2 + 1/bN^2 + 1/cN^2);
    Print["  Computed lambda    = ", N[lamComputed, 30]];
    Print["  Analytical lambda  = ", N[lamAnalytical, 30]];
    Print["  Relative diff      = ",
      N[Abs[lamComputed - lamAnalytical]/Abs[lamAnalytical], 5]]],
  Print["  (1,1,1) not in basis"]];
Print[""];

(* Source vector b_i = <A_i, A_ext>_cond
   A_ext = (B_0/2)(-y, x, 0), B_0 = 1
   <A_i, A_ext> = int (A_x_i * (-y/2) + A_y_i * x/2) dV
   A_x = X(x) Y'(y) Z(z), A_y = -X'(x) Y(y) Z(z)
   int A_x (-y/2) dV = (-1/2) [int X dx][int y Y' dy][int Z dz]
   int A_y (x/2) dV = (-1/2) [int x X' dx][int Y dy][int Z dz]
*)

(* 1D shifted-sin integrals for source coupling *)
(* int_{-L/2}^{L/2} sin(p pi (x+L/2)/L) dx = ?
   Let u = x + L/2, du = dx, u: 0 -> L
   int_0^L sin(p pi u/L) du = -L/(p pi) [cos(p pi u/L)]_0^L = (L/(p pi))(1 - cos(p pi)) =
       2L/(p pi) for p odd, 0 for p even
*)
intS[p_, L_] := L (1 - Cos[p PiN])/(p PiN);  (* = 2L/(p pi) for p odd, 0 for p even *)
(* int_{-L/2}^{L/2} cos(p pi (x+L/2)/L) dx = (L/(p pi))[sin(p pi u/L)]_0^L = 0 for any p>=1 *)
intC[p_, L_] := 0;
(* int x sin(p pi (x+L/2)/L) dx ... *)
(* Substitute u = x+L/2, x = u - L/2, dx = du:
   int_0^L (u - L/2) sin(p pi u/L) du = int u sin du - (L/2) int sin du
   int u sin(p pi u/L) du from 0 to L:
     = (L/(p pi))^2 [sin(p pi u/L) - (p pi u/L) cos(p pi u/L)]_0^L
     = (L/(p pi))^2 [sin(p pi) - p pi cos(p pi) - 0]
     = (L/(p pi))^2 [0 - p pi (-1)^p]
     = -L^2 (-1)^p/(p pi)
   And (L/2) int_0^L sin(p pi u/L) du = (L/2) * L (1-(-1)^p)/(p pi) = L^2 (1-(-1)^p)/(2 p pi)
   So:
   int_{-L/2}^{L/2} x sin(p pi (x+L/2)/L) dx = -L^2 (-1)^p/(p pi) - L^2 (1-(-1)^p)/(2 p pi)
   For p even: = -L^2/(p pi) - 0 = -L^2/(p pi)
   For p odd:  =  L^2/(p pi) - L^2/(p pi) = 0
   So int x*sin = -L^2/(p pi) for p EVEN, 0 for p odd.
*)
intXS[p_, L_] := If[Mod[p, 2] === 0, -L^2/(p PiN), 0];

(* For our basis we need int x*X'(x) dx. X' = (p pi/L) cos(p pi (x+L/2)/L).
   int_{-L/2}^{L/2} x cos(p pi (x+L/2)/L) dx via similar sub:
   int_0^L (u - L/2) cos(p pi u/L) du
     = (L/(p pi))^2 [cos(p pi u/L) + (p pi u/L) sin(p pi u/L)]_0^L
     = (L/(p pi))^2 [(-1)^p - 1 + p pi sin(p pi)]
     = (L/(p pi))^2 [(-1)^p - 1]
   Minus (L/2) int_0^L cos(p pi u/L) du = (L/2) (L/(p pi)) sin(p pi) = 0
   So int x cos(p pi (x+L/2)/L) dx = L^2 ((-1)^p - 1)/(p pi)^2
   For p even: 0. For p odd: -2 L^2/(p pi)^2.

   int x X'(x) dx = (p pi/L) * int x cos(...) dx
                  = (p pi/L) * L^2 ((-1)^p - 1)/(p pi)^2
                  = L ((-1)^p - 1)/(p pi)
   For p even: 0. For p odd: -2 L/(p pi).
*)
intXdX[p_, L_] := If[Mod[p, 2] === 1, -2 L/(p PiN), 0];

(* int y * Y'(y) dy similarly. Y'(y) = (q pi/b) cos(q pi (y+b/2)/b)
   We need int_{-b/2}^{b/2} y * Y'(y) dy
   = (q pi/b) int y cos(q pi (y+b/2)/b) dy
   = (q pi/b) * b^2 ((-1)^q - 1)/(q pi)^2  (from above with substitution)
   = b ((-1)^q - 1)/(q pi)
   For q even: 0. For q odd: -2b/(q pi)
*)
intYdY[q_, L_] := If[Mod[q, 2] === 1, -2 L/(q PiN), 0];

(* Source vector entry for basis (p, q, r):
   b_i = -(1/2) [int X_p dx][int y Y'_q dy][int Z_r dz]
       + (1/2) [int x X'_p dx][int Y_q dy][int Z_r dz]
*)

(* b_i = -(1/2) integral A_x y dV + (1/2) integral A_y x dV
        with A_x = d_y psi, A_y = -d_x psi
        term1 = -(1/2) integral X(x) Y'(y) y Z(z) dV
        term2 = -(1/2) integral X'(x) x Y(y) Z(z) dV     <- note negative due to A_y = -d_x psi *)
sourceElement[ip_] := Module[{p, q, r, term1, term2},
  {p, q, r} = basisIndices[[ip]];
  term1 = -(1/2) intS[p, aN] intYdY[q, bN] intS[r, cN];
  term2 = -(1/2) intXdX[p, aN] intS[q, bN] intS[r, cN];
  term1 + term2];

bVec = Table[sourceElement[i], {i, 1, nBasis}];
Print["Source vector first 5 entries:"];
Do[Print["  b[", basisIndices[[i]], "] = ",
  ToString[CForm[N[bVec[[i]], 16]]]], {i, 1, Min[5, nBasis]}];
Print[""];

(* Reference low-frequency coefficient alpha_LF^cub = -mu_0 sigma (a^2+b^2)/48 *)
alphaLFRef = -mu0N sigmaN (aN^2 + bN^2)/48;
Print["Reference alpha_LF^cub = -mu_0 sigma (a^2+b^2)/48 = ",
  N[alphaLFRef, 16]];

(* At low s, coefficient c_i ~ (-s mu0 sigma) b_i / lambda_i + O(s^2)
   chi(s) = -(mu_0/V) m_z(s)/B_0  ... wait, let's redo
   Actually m_z = (1/2) int (r x J)_z dV, J = -s sigma A (in conductor)
   m_z = -(s sigma/2) int (x A_y - y A_x) dV
        = -(s sigma/2) * 2 <A_ext, A_total> ...
   Note <A_ext, A_total> = <A_ext, A_ext> + <A_ext, A_ind>
   <A_ext, A_ext> = int(A_ext_x^2 + A_ext_y^2) dV with A_ext = (B_0/2)(-y, x, 0)
                  = (B_0^2/4) int(x^2+y^2) dV = (B_0^2/4)*V*(a^2+b^2)/12 = B_0^2 V(a^2+b^2)/48
   And:
   m_z = -(s sigma/2) * 2 * (1/B_0) * <A_ext, A_total>
       wait reverse mapping. Actually <A_ext, A> := int (A_ext . A) dV
       int x A_y dV - int y A_x dV = ?
       Note A_ext = (B_0/2)(-y, x, 0), so x = (2/B_0) A_ext_y, y = -(2/B_0) A_ext_x
       int x A_y dV = (2/B_0) int A_ext_y A_y dV
       int y A_x dV = -(2/B_0) int A_ext_x A_x dV
       int (x A_y - y A_x) dV = (2/B_0)[<A_ext_y, A_y> + <A_ext_x, A_x>] = (2/B_0) <A_ext, A>
   So m_z = -(s sigma/2)(2/B_0) <A_ext, A_total> = -(s sigma/B_0) <A_ext, A_total>
   chi_V = m_z mu_0 / (V B_0) = -(s sigma mu_0/(V B_0^2)) <A_ext, A_total>
   For B_0=1: chi = -(s sigma mu_0/V) <A_ext, A_total>
   <A_ext, A_total> = <A_ext, A_ext> + <A_ext, A_ind>
   <A_ext, A_ext> = V(a^2+b^2)/48 (computed)
   At s -> 0, A_ind -> 0, so chi -> -s sigma mu_0/V * V(a^2+b^2)/48 = -s mu_0 sigma (a^2+b^2)/48 ✓
*)

(* Verify <A_ext, A_ext> = V(a^2+b^2)/48 *)
AextAext = VN (aN^2 + bN^2)/48;
Print["<A_ext, A_ext> closed form = V (a^2+b^2)/48 = ",
  N[AextAext, 16]];
Print[""];

(* Solve at s=0+ limit: K alpha = -s mu0 sigma * (b vector)
   For diagonal K, alpha_i = -s mu0 sigma b_i / K_ii
   <A_ext, A_ind> = sum alpha_i b_i = -s mu0 sigma sum b_i^2 / K_ii
   chi = -(s mu0 sigma/V) [V(a^2+b^2)/48 + (-s mu0 sigma sum b_i^2/K_ii)]
       = -s mu0 sigma (a^2+b^2)/48 + (s mu0 sigma)^2/V * sum b_i^2/K_ii
   leading O(s) term matches alpha_LF^cub (closed form), independent of basis ✓
*)

(* Compute alpha_2 = (mu0 sigma)^2 * (1/V) * sum b_i^2 / K_ii *)
alpha2Galerkin = (mu0N sigmaN)^2 / VN * Sum[bVec[[i]]^2/KMat[[i, i]], {i, 1, nBasis}];
Print["alpha_2 (s^2 coefficient of chi_cub) from Galerkin:"];
Print["  basis size = ", nBasis, " modes"];
Print["  alpha_2^Galerkin = ", N[alpha2Galerkin, 16]];
Print[""];

(* Sphere reference alpha_2^sph(R_eff) = (mu_0 sigma R_eff^2)^2 / 105 *)
ReffSq = 5 (aN^2 + bN^2)/24;
alpha2Sphere = (mu0N sigmaN ReffSq)^2 / 105;
Print["Sphere reference alpha_2^sph(R_eff) = (mu0 sigma R_eff^2)^2 / 105 = ",
  N[alpha2Sphere, 16]];
Print["  (R_eff^2 = 5(a^2+b^2)/24 = alpha_LF matching radius)"];
Print[""];

Print["Ratio alpha_2^Galerkin / alpha_2^sph(R_eff) = ",
  N[alpha2Galerkin/alpha2Sphere, 16]];
Print["  (deviation from 1 indicates shape correction at order s^2)"];
Print[""];

Print["Stage 5a Step 1 verified:"];
Print["  - parity-allowed basis (p,q,r) all odd"];
Print["  - K, M matrices both diagonal (orthogonal basis)"];
Print["  - alpha_LF leading O(s) coeff matches closed form"];
Print["  - alpha_2 computed at 60 digits (basis truncation only error)"];
Print[""];

Print["Next steps:"];
Print["  Step 2: Convergence study (Pmax = 5, 7, 9, ...) to extract converged alpha_2."];
Print["  Step 3: Add exterior multipole coupling for true vacuum BC."];
Print["  Step 4: Cauer-I extraction from converged moments."];

(* Stage 5a Step 2: Convergence study and Cauer-I extraction for cuboid
   interior PEC-like Galerkin (single-potential family A_z = 0).

   Builds on Step 1 framework. For each P_max in {3, 5, 7, 9, 11}:
     - Build basis (p,q,r all odd, p<=Pmax, q<=Qmax, r<=Rmax with Pmax=Qmax=Rmax)
     - Compute K, M (diagonal, closed form)
     - Compute source vector b
     - Compute moments M_k of Y(s) = b^T (K+s mu_0 sigma M)^{-1} b
       For diagonal K, M:
         Y(s)/s = -mu0 sigma sum b_i^2 / (K_ii + s mu0 sigma M_ii)
         At order s^k: alpha_(k+1) = (mu0 sigma)^(k+1) * sum b_i^2 M_ii^k / K_ii^(k+1) (with sign)
     - Cauer-I extraction
   Compare convergence with basis size, and to sphere R_eff reference.
*)

$HistoryLength = 0;
prec = 60;

Print["=== Stage 5a Step 2: Convergence + Cauer-I (60-digit) ==="];
Print[""];

(* Constants *)
sigmaN = SetPrecision[58000000, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
PiN = SetPrecision[Pi, prec];
VN = aN bN cN;

(* Reference: sphere with R_eff = sqrt(5(a^2+b^2)/24) *)
ReffSq = 5 (aN^2 + bN^2)/24;

(* Sphere chi(s) closed form *)
chiSphere[R_, s_] := Module[{z}, z = R Sqrt[s mu0N sigmaN];
  -3/2 + (9/(2 z^2))(z Coth[z] - 1)];
(* Sphere alpha_n: chi(s) = alpha_1 s + alpha_2 s^2 + ... *)
(* alpha_n^sph = (mu0 sigma R^2)^n / a_n  with specific a_n:
   For sphere, chi(s) = -3/2 + (9/(2z^2))(z coth z - 1).
   z coth z - 1 = sum_(n=1) 2 z^2/(z^2 + (n pi)^2)
   chi(s) = -3/2 + (9/z^2) sum z^2/(z^2 + (n pi)^2)
          = -3/2 + 9 sum 1/(1 + (n pi/z)^2)
   With z^2 = R^2 mu sigma s, (n pi/z)^2 = (n pi)^2/(R^2 mu sigma s) -> infinity as s->0
   so each term -> 1/(big) -> 0. Wait need different expansion.

   Use Mittag-Leffler form chi = -9 s mu0 sigma R^2 sum 1/((n pi)^4 (1 + s tau_n)),
   tau_n = mu0 sigma R^2 /(n pi)^2:
   Series in s: chi = -9 mu0 sigma R^2 s sum [1 - s tau_n + (s tau_n)^2 - ...] / (n pi)^4
   alpha_1 = -9 mu0 sigma R^2 sum 1/(n pi)^4 = -9 mu0 sigma R^2 (pi^4/90)/pi^4 = -mu0 sigma R^2/10
   alpha_2 = +9 mu0 sigma R^2 sum tau_n/(n pi)^4 = 9 (mu0 sigma R^2)^2 sum 1/(n pi)^6
            = 9 (mu0 sigma R^2)^2 (pi^6/945)/pi^6 = (mu0 sigma R^2)^2/105
   alpha_3 = -9 (mu0 sigma R^2)^3 sum 1/(n pi)^8 = -9 (mu0 sigma R^2)^3 (pi^8/9450)/pi^8
           = -(mu0 sigma R^2)^3 / 1050
   etc. via zeta(2k) values. *)

alphaSphere[R_, k_] := Module[{x = mu0N sigmaN R^2, ck},
  ck = Switch[k,
    1, -1/10,           (* zeta(4)/(pi^4) * 9 = 9/90 *)
    2, +1/105,          (* zeta(6)/(pi^6) * 9 = 9/945 *)
    3, -1/1050,         (* zeta(8)/(pi^8) * 9 = 9/9450 *)
    4, +1/10395,        (* zeta(10)/(pi^10) * 9 *)
    _, (-1)^k * 9 N[Zeta[2 k + 2], prec]/PiN^(2 k + 2) ];
  ck * x^k];

Print["Sphere reference (R_eff) coefficients of chi(s) Taylor expansion:"];
Do[Print["  alpha_", k, "^sph(R_eff) = ",
  N[alphaSphere[Sqrt[ReffSq], k], 16]], {k, 1, 5}];
Print[""];

(* === Build basis and matrices for given Pmax === *)
buildBasis[Pmax_] := Flatten[Table[
  {2 P + 1, 2 Q + 1, 2 R + 1},
  {P, 0, (Pmax - 1)/2}, {Q, 0, (Pmax - 1)/2}, {R, 0, (Pmax - 1)/2}], 2];

(* Closed-form diagonal entries:
   M_ii = (V/8) pi^2 (p^2/a^2 + q^2/b^2)
   K_ii = (V/8) pi^4 (p^2/a^2 + q^2/b^2) (p^2/a^2 + q^2/b^2 + r^2/c^2)
   lambda_i = K_ii/M_ii = pi^2 (p^2/a^2 + q^2/b^2 + r^2/c^2)
   b_i = -(1/2)*(2a/(p pi))*(-2b/(q pi))*(2c/(r pi))
         -(1/2)*(-2a/(p pi))*(2b/(q pi))*(2c/(r pi))
       = (4abc)/(pqr pi^3) + (4abc)/(pqr pi^3)
       = 8 V/(p q r pi^3)   for p,q,r all odd
*)

mElement[p_, q_, r_] := (VN/8) PiN^2 (p^2/aN^2 + q^2/bN^2);
kElement[p_, q_, r_] := (VN/8) PiN^4 (p^2/aN^2 + q^2/bN^2) (p^2/aN^2 + q^2/bN^2 + r^2/cN^2);
bElement[p_, q_, r_] := 8 VN/(p q r PiN^3);

(* Verify closed-form formulas against Step 1 numerical:
   For (1,1,1): b_i = 8V/pi^3, alpha_2 contribution = b_i^2/k_ii.
*)
Print["Closed-form verification ((1,1,1)):"];
Print["  b_(1,1,1) = 8V/pi^3 = ", N[bElement[1, 1, 1], 16]];
Print["  K_(1,1,1) = ", N[kElement[1, 1, 1], 16]];
Print["  M_(1,1,1) = ", N[mElement[1, 1, 1], 16]];
Print["  lambda_(1,1,1) = K/M = ", N[kElement[1, 1, 1]/mElement[1, 1, 1], 16],
  "  vs pi^2 (1/a^2+1/b^2+1/c^2) = ",
  N[PiN^2 (1/aN^2 + 1/bN^2 + 1/cN^2), 16]];
Print[""];

(* === Compute moments alpha_n via series expansion ===
   Y(s) = -mu0 sigma sum b_i^2/(K_ii + s mu0 sigma M_ii)
   chi_correction(s) = -(mu0 sigma s/V) sum b_i alpha_i(s) [contribution from A_ind to <A_ext, A>]
   But for the leading coefficients, the picture is:

   chi(s) = -(mu0 sigma s/V)[<A_ext, A_ext> + <A_ext, A_ind>]
          = alpha_LF * s + corrections

   For diagonal Galerkin:
     A_ind expansion alpha_i = -s mu0 sigma b_i / (K_ii + s mu0 sigma M_ii)
     <A_ext, A_ind> = sum b_i alpha_i = -s mu0 sigma sum b_i^2/(K_ii + s mu0 sigma M_ii)
     chi_corr = -(mu0 sigma s/V) * (-s mu0 sigma) sum b_i^2/(K + s mu0 sigma M)
              = (mu0 sigma s)^2/V * sum b_i^2/(K_ii + s mu0 sigma M_ii)
     Series in s: 1/(K + s mu0 sigma M) = (1/K) (1 - s mu0 sigma M/K + (s mu0 sigma M/K)^2 - ...)
     chi_corr = (mu0 sigma)^2 s^2/V sum (b_i^2/K_ii) (1 - s mu0 sigma M_ii/K_ii + ...)
     -> alpha_2_corr = (mu0 sigma)^2 / V * sum b_i^2/K_ii
        alpha_3_corr = -(mu0 sigma)^3 / V * sum b_i^2 M_ii/K_ii^2
        alpha_(n+1)_corr = (-1)^(n-1) (mu0 sigma)^(n+1)/V sum b_i^2 M_ii^(n-1) / K_ii^n

   Note alpha_LF = -mu0 sigma (a^2+b^2)/48 is BASIS INDEPENDENT (from <A_ext,A_ext> piece). *)

alphaLFRef = -mu0N sigmaN (aN^2 + bN^2)/48;

(* For given basis (Pmax), compute alpha_2, alpha_3, ... *)
computeAlphas[Pmax_, kMax_] := Module[{idx, vals, b, k, m},
  idx = buildBasis[Pmax];
  vals = Table[
    {b, k, m} = {bElement @@ pp, kElement @@ pp, mElement @@ pp};
    Table[(-1)^(n - 1) * (mu0N sigmaN)^(n + 1)/VN * b^2 * m^(n - 1)/k^n,
      {n, 1, kMax}],
    {pp, idx}];
  Total /@ Transpose[vals]];

(* Run convergence sweep *)
PmaxList = {3, 5, 7, 9, 11};
kMax = 5;
Print["=== Convergence sweep: alpha_2..alpha_5 vs basis size ==="];
Print[""];
Print[StringPadRight["Pmax", 6], StringPadRight["nBasis", 8],
  StringPadRight["alpha_2", 24], StringPadRight["alpha_3", 24],
  StringPadRight["alpha_4", 24], StringPadRight["alpha_5", 24]];
Print[StringJoin[Table["-", {110}]]];
allResults = {};
Do[Module[{nB, alphas},
  nB = Length[buildBasis[Pmax]];
  alphas = computeAlphas[Pmax, kMax];
  AppendTo[allResults, {Pmax, nB, alphas}];
  Print[StringPadRight[ToString[Pmax], 6], StringPadRight[ToString[nB], 8],
    StringJoin[StringPadRight[ToString[CForm[N[#, 14]]], 24] & /@ alphas]]],
  {Pmax, PmaxList}];
Print[""];

(* Convergence ratios and Richardson extrapolation if possible *)
Print["=== Convergence rate analysis ==="];
Do[Module[{a3, a5, a7, a9, a11, ratio},
  a3 = allResults[[1, 3, k]];
  a5 = allResults[[2, 3, k]];
  a7 = allResults[[3, 3, k]];
  a9 = allResults[[4, 3, k]];
  a11 = allResults[[5, 3, k]];
  Print["alpha_", k + 1, " sequence: ",
    Table[N[allResults[[i, 3, k]], 8], {i, 1, 5}]];
  ratio = (a11 - a9)/(a9 - a7);
  Print["  ratio (a11-a9)/(a9-a7) = ", N[ratio, 6],
    " (smaller -> faster convergence)"]],
  {k, 1, 4}];
Print[""];

(* Compare to sphere reference *)
Print["=== Comparison to sphere(R_eff) reference ==="];
Print[""];
Print[StringPadRight["alpha_n", 10], StringPadRight["Pmax=11 (interior PEC)", 28],
  StringPadRight["sphere(R_eff)", 24], StringPadRight["ratio (Galerkin/sph)", 24]];
Print[StringJoin[Table["-", {86}]]];
Do[Module[{interiorVal, sphVal, ratio},
  interiorVal = allResults[[5, 3, k]];
  sphVal = alphaSphere[Sqrt[ReffSq], k + 1];
  ratio = interiorVal/sphVal;
  Print[StringPadRight[ToString["alpha_" <> ToString[k + 1]], 10],
    StringPadRight[ToString[CForm[N[interiorVal, 14]]], 28],
    StringPadRight[ToString[CForm[N[sphVal, 14]]], 24],
    ToString[NumberForm[N[ratio, 8], 8]]]],
  {k, 1, 4}];
Print[""];
Print["Note: ratio < 1 because interior PEC-like basis underestimates response"];
Print["(no eddy current outside conductor, no normal flux through surface).";];
Print["Step 3 (multipole exterior) will close this gap."];
Print[""];

(* === Cauer-I extraction from highest-Pmax moments === *)
(* Build moment sequence M_k = alpha_(k+1) (Y(s) = -dchi/ds at s=0 = -alpha_1 - 2 alpha_2 s - ...?
   Actually let's redefine: define Y(s) such that chi(s) = -alpha_LF / Y(s) effective
   For Cauer-I extraction we need an admittance-like rational function.

   Use chi(s) directly as an impedance-like quantity:
   Z(s) := -1/chi(s)
   then Z(s) ~ 1/(alpha_LF s) at low s = 1/(alpha_LF s) * [1 + alpha_2/alpha_LF s + ...]^(-1)
   This is a Foster admittance form. Cauer-I extraction from this. *)

chiCoeffs[Pmax_, kMax_] := Prepend[computeAlphas[Pmax, kMax], alphaLFRef];

allCoeffs = chiCoeffs[11, 12];
Print["chi(s) Taylor coefficients (Pmax=11, k=1..13):"];
Do[Print["  alpha_", k, " = ", N[allCoeffs[[k]], 16]], {k, 1, 8}];
Print[""];

(* Form chi(s) Taylor expansion truncated *)
chiSeries[Pmax_, kMax_] := Module[{coeffs, s},
  coeffs = chiCoeffs[Pmax, kMax];
  Sum[coeffs[[k]] s^k, {k, 1, kMax + 1}]];

(* Z(s) = -1/chi(s) Laurent series at s = 0 *)
ZLaurent[Pmax_, kMax_] := Module[{chi, s, ser},
  chi = chiSeries[Pmax, kMax] /. Global`s -> sv;
  ser = Series[-1/chi, {sv, 0, kMax}];
  Normal[ser]];

Zseries = ZLaurent[11, 11];
Print["Z(s) = -1/chi(s) Laurent series (first few):"];
Print["  ", Series[-1/chiSeries[11, 11] /. Global`s -> sv, {sv, 0, 4}]];
Print[""];

(* Cauer-I extraction *)
cauerExtractFromLaurent[zLaurent_, svar_, maxStages_] := Module[
  {Zcur, vals, kk, pn, pp, qq, q0, p0, Rk, presid, pas, pas0, Lk, nresid},
  Zcur = zLaurent;  (* expression in svar with leading 1/svar term *)
  vals = {};
  For[kk = 0, kk < maxStages, kk++,
   (* Z = 1/(s L_k) form means Series at s=0 has -1 term *)
   pn = Series[Zcur, {svar, 0, 30}];
   (* extract leading coefficient = 1/(s L_k) *)
   Lk = 1/Coefficient[Normal[pn], svar, -1];
   If[NumericQ[Lk] && Abs[Lk] > 10^-100,
    AppendTo[vals, {2 kk, "L", Lk}],
    Break[]];
   (* Subtract 1/(s Lk), get next *)
   Zcur = Zcur - 1/(svar Lk);
   pn = Series[Zcur, {svar, 0, 30}];
   (* Now leading is constant -> R_k *)
   Rk = Normal[pn] /. svar -> 0;
   If[NumericQ[Rk] && Abs[Rk] > 10^-100,
    AppendTo[vals, {2 kk + 1, "R", Rk}],
    Break[]];
   Zcur = 1/(Zcur - Rk);
   ];
  vals];

Print["=== Cauer-I extraction from chi(s) (interior PEC, Pmax=11) ==="];
stages = cauerExtractFromLaurent[Zseries, sv, 6];
Print["Index | Type  | Value (16 digits)"];
Print[StringJoin[Table["-", {60}]]];
Do[Module[{idx, type, val},
  {idx, type, val} = stages[[i]];
  Print[StringPadLeft[ToString[idx], 5], " | ",
    StringPadRight[type, 5], " | ",
    ToString[CForm[N[val, 16]]]]],
  {i, Length[stages]}];
Print[""];

Print["=== Stage 5a Step 2 summary ==="];
Print["* alpha_2 converges with basis size (sin sin sin curl interior basis)"];
Print["* Final alpha_n values are interior-PEC-like, NOT vacuum"];
Print["* Cauer-I from these moments gives 'cuboid in PEC cavity' Cauer ladder"];
Print["* Step 3: add exterior multipole basis to convert to true vacuum"];

(* Stage 5a Step 3: enriched Galerkin with exterior dipole multipole.

   Internal basis (Step 1+2): A^I_i = curl(z_hat psi_i),
     psi_i = sin(p pi (x+a/2)/a) sin(q pi (y+b/2)/b) sin(r pi (z+c/2)/c),
     p,q,r all odd.  Vanishes at conductor surface.

   External basis (NEW): single mode
     Phi^E(r) = (-y, x, 0)/(r^2 + R_0^2)^(3/2)
   This:
     * is regular at origin (no singularity)
     * decays as 1/r^3 at infinity (dipole tail)
     * has same parity as A_ext (D_2h + uniform B_z)
     * curl Phi^E approaches dipole B-field at large r

   Closed form: K^EE = integral|curl Phi^E|^2 dV = 15 pi^2/(32 R_0^3)
   NIntegrate needed for M^IE, K^IE, M^EE, b^E (all over conductor only).

   Augmented system (n_int + 1 unknowns):
     [K^II  K^IE]  alpha^I    M^II  M^IE   alpha^I       b^I
     [K^EI  K^EE] [alpha^E] + s mu0 sigma [M^EI  M^EE] [alpha^E] = -s mu0 sigma [b^E]

   Solve for chi(s) Taylor coefficients. *)

$HistoryLength = 0;
prec = 60;

Print["=== Stage 5a Step 3: enriched Galerkin (interior + dipole) ==="];
Print[""];

(* Constants *)
sigmaN = SetPrecision[58000000, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
PiN = SetPrecision[Pi, prec];
VN = aN bN cN;
ReffSq = 5 (aN^2 + bN^2)/24;

(* Sphere reference alpha_n *)
alphaSphere[R_, k_] := Module[{x = mu0N sigmaN R^2, ck},
  ck = Switch[k, 1, -1/10, 2, +1/105, 3, -1/1050, 4, +1/10395, 5, -1/135135,
    _, (-1)^k * 9 * SetPrecision[Zeta[2 k + 2], prec]/PiN^(2 k + 2)];
  ck * x^k];

Print["Sphere reference (R_eff^2 = 5(a^2+b^2)/24):"];
Do[Print["  alpha_", k, "^sph = ", N[alphaSphere[Sqrt[ReffSq], k], 16]],
  {k, 1, 5}];
Print[""];

(* === Interior basis (closed form, from Step 1+2) === *)
Pmax = 3;
basisIndices = Flatten[Table[{2 P + 1, 2 Q + 1, 2 R + 1},
  {P, 0, (Pmax - 1)/2}, {Q, 0, (Pmax - 1)/2}, {R, 0, (Pmax - 1)/2}], 2];
nInt = Length[basisIndices];
Print["Interior basis: Pmax=", Pmax, ", nInt=", nInt];
Print["Indices: ", basisIndices];
Print[""];

(* Closed-form interior matrices (diagonal) *)
mIIElement[p_, q_, r_] := (VN/8) PiN^2 (p^2/aN^2 + q^2/bN^2);
kIIElement[p_, q_, r_] := (VN/8) PiN^4 (p^2/aN^2 + q^2/bN^2)*
                          (p^2/aN^2 + q^2/bN^2 + r^2/cN^2);
bIElement[p_, q_, r_] := 8 VN/(p q r PiN^3);

(* Build interior matrices *)
MII = DiagonalMatrix[Table[mIIElement @@ idx, {idx, basisIndices}]];
KII = DiagonalMatrix[Table[kIIElement @@ idx, {idx, basisIndices}]];
bIVec = Table[bIElement @@ idx, {idx, basisIndices}];

(* === External basis: regularized dipole === *)
(* Choose R_0: comparable to half the smallest cuboid dimension *)
R0 = SetPrecision[1/1000, prec];  (* 1 mm = b/2 *)
Print["External basis: Phi^E(r) = (-y, x, 0)/(r^2 + R_0^2)^(3/2)"];
Print["  R_0 = ", N[R0*1000, 6], " mm"];
Print[""];

(* Closed form K^EE *)
KEE = 15 PiN^2 / (32 R0^3);
Print["K^EE (closed form) = 15 pi^2/(32 R_0^3) = ", N[KEE, 16]];
Print[""];

(* === NIntegrate parameters === *)
wp = 50;  (* WorkingPrecision *)
ag = 40;  (* AccuracyGoal *)
pg = 35;  (* PrecisionGoal *)
maxRecursion = 12;

(* Helper: Phi^E components and curl Phi^E components, for use in NIntegrate *)
PhiEx[xx_, yy_, zz_] := -yy/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2);
PhiEy[xx_, yy_, zz_] := xx/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2);
(* PhiEz = 0 *)

(* curl Phi^E *)
curlPhiEx[xx_, yy_, zz_] := 3 xx zz/(xx^2 + yy^2 + zz^2 + R0^2)^(5/2);
curlPhiEy[xx_, yy_, zz_] := 3 yy zz/(xx^2 + yy^2 + zz^2 + R0^2)^(5/2);
curlPhiEz[xx_, yy_, zz_] := (2 (zz^2 + R0^2) - (xx^2 + yy^2))/
                             (xx^2 + yy^2 + zz^2 + R0^2)^(5/2);

(* Interior basis psi_i and curl A^I_i = (d_xz psi, d_yz psi, -(d_xx+d_yy) psi) *)
psiSym[p_, q_, r_, xx_, yy_, zz_] :=
  Sin[p PiN (xx + aN/2)/aN] * Sin[q PiN (yy + bN/2)/bN] * Sin[r PiN (zz + cN/2)/cN];

curlAIxSym[p_, q_, r_, xx_, yy_, zz_] :=
  (p PiN/aN)(r PiN/cN) Cos[p PiN (xx + aN/2)/aN] *
    Sin[q PiN (yy + bN/2)/bN] * Cos[r PiN (zz + cN/2)/cN];

curlAIySym[p_, q_, r_, xx_, yy_, zz_] :=
  (q PiN/bN)(r PiN/cN) Sin[p PiN (xx + aN/2)/aN] *
    Cos[q PiN (yy + bN/2)/bN] * Cos[r PiN (zz + cN/2)/cN];

curlAIzSym[p_, q_, r_, xx_, yy_, zz_] :=
  -(p^2 PiN^2/aN^2 + q^2 PiN^2/bN^2) Sin[p PiN (xx + aN/2)/aN] *
    Sin[q PiN (yy + bN/2)/bN] * Sin[r PiN (zz + cN/2)/cN];

AIxSym[p_, q_, r_, xx_, yy_, zz_] :=
  (q PiN/bN) Sin[p PiN (xx + aN/2)/aN] * Cos[q PiN (yy + bN/2)/bN] *
    Sin[r PiN (zz + cN/2)/cN];

AIySym[p_, q_, r_, xx_, yy_, zz_] :=
  -(p PiN/aN) Cos[p PiN (xx + aN/2)/aN] * Sin[q PiN (yy + bN/2)/bN] *
    Sin[r PiN (zz + cN/2)/cN];

(* === Compute NIntegrate matrices === *)

(* M^EE = integral_cond (Phi^E . Phi^E) dV = integral (x^2+y^2)/(r^2+R_0^2)^3 dV *)
Print["Computing M^EE (1 NIntegrate)..."];
tStart = AbsoluteTime[];
MEE = NIntegrate[
  (xx^2 + yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^3,
  {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
  WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
  MaxRecursion -> maxRecursion];
Print["  M^EE = ", N[MEE, 16], "  (", N[AbsoluteTime[] - tStart, 4], " s)"];

(* b^E = integral_cond (Phi^E . A_ext) dV = (1/2) integral (x^2+y^2)/(r^2+R_0^2)^(3/2) dV *)
Print["Computing b^E (1 NIntegrate)..."];
tStart = AbsoluteTime[];
bE = (1/2) NIntegrate[
  (xx^2 + yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2),
  {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
  WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
  MaxRecursion -> maxRecursion];
Print["  b^E = ", N[bE, 16], "  (", N[AbsoluteTime[] - tStart, 4], " s)"];

(* M^IE_i = integral_cond Phi^I_i . Phi^E dV
        = integral (A^I_x * (-y)/(r^2+R_0^2)^(3/2) + A^I_y * x/(r^2+R_0^2)^(3/2)) dV *)
Print["Computing M^IE (", nInt, " NIntegrates)..."];
tStart = AbsoluteTime[];
MIEVec = Table[Module[{p, q, r, integrand, val},
  {p, q, r} = basisIndices[[i]];
  integrand = (AIxSym[p, q, r, xx, yy, zz] (-yy) +
               AIySym[p, q, r, xx, yy, zz] xx)/
              (xx^2 + yy^2 + zz^2 + R0^2)^(3/2);
  val = NIntegrate[integrand,
    {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
    WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
    MaxRecursion -> maxRecursion];
  Print["  M^IE[", basisIndices[[i]], "] = ", N[val, 12]];
  val],
  {i, nInt}];
Print["  M^IE total time: ", N[AbsoluteTime[] - tStart, 4], " s"];

(* K^IE_i = integral_cond curl A^I_i . curl Phi^E dV  (interior support only) *)
Print["Computing K^IE (", nInt, " NIntegrates)..."];
tStart = AbsoluteTime[];
KIEVec = Table[Module[{p, q, r, integrand, val},
  {p, q, r} = basisIndices[[i]];
  integrand = (curlAIxSym[p, q, r, xx, yy, zz] curlPhiEx[xx, yy, zz] +
               curlAIySym[p, q, r, xx, yy, zz] curlPhiEy[xx, yy, zz] +
               curlAIzSym[p, q, r, xx, yy, zz] curlPhiEz[xx, yy, zz]);
  val = NIntegrate[integrand,
    {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
    WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
    MaxRecursion -> maxRecursion];
  Print["  K^IE[", basisIndices[[i]], "] = ", N[val, 12]];
  val],
  {i, nInt}];
Print["  K^IE total time: ", N[AbsoluteTime[] - tStart, 4], " s"];
Print[""];

(* === Build augmented system === *)
(* Block structure:
     M = [[ M^II   M^IE ]
          [ M^EI   M^EE ]]   (n_int+1) x (n_int+1)
   Same for K.
   Source vector b = [b^I; b^E].
*)
nTot = nInt + 1;
Print["Building augmented system (n_total = ", nTot, ")"];

MAug = Table[0, {nTot}, {nTot}];
KAug = Table[0, {nTot}, {nTot}];
bAug = Table[0, {nTot}];

Do[MAug[[i, i]] = MII[[i, i]]; KAug[[i, i]] = KII[[i, i]]; bAug[[i]] = bIVec[[i]],
  {i, nInt}];
Do[MAug[[i, nTot]] = MIEVec[[i]]; MAug[[nTot, i]] = MIEVec[[i]];
   KAug[[i, nTot]] = KIEVec[[i]]; KAug[[nTot, i]] = KIEVec[[i]],
  {i, nInt}];
MAug[[nTot, nTot]] = MEE;
KAug[[nTot, nTot]] = KEE;
bAug[[nTot]] = bE;
Print[""];

(* === Compute Taylor coefficients alpha_n of chi(s) ===
   Galerkin equation: (K + s mu_0 sigma M) alpha = -s mu_0 sigma b
   chi(s) = -(s mu0 sigma/V)[<A_ext, A_ext> + <A_ext, A_ind>]
          = -(s mu0 sigma/V)[V(a^2+b^2)/48 + b . alpha]
          = alpha_LF * s + (mu0 sigma)^2 s^2/V * b . (K^{-1}) b - ... etc.

   Let nu = s mu0 sigma. alpha(nu) satisfies (K + nu M) alpha = -nu b.
   Series alpha = -nu K^{-1} b + nu^2 K^{-1} M K^{-1} b - nu^3 K^{-1} M K^{-1} M K^{-1} b + ...
   <b, alpha> = -nu b^T K^{-1} b + nu^2 b^T K^{-1} M K^{-1} b - ...
   chi_corr = -(nu/V) <b, alpha> = (nu^2/V) b^T K^{-1} b - (nu^3/V) b^T K^{-1} M K^{-1} b + ...
   alpha_2 = (mu0 sigma)^2/V * b^T K^{-1} b
   alpha_3 = -(mu0 sigma)^3/V * b^T (K^{-1} M K^{-1}) b
   etc.
*)

KAugInv = Inverse[KAug];

Print["=== Taylor coefficients of chi(s) ==="];
alphaLFRef = -mu0N sigmaN (aN^2 + bN^2)/48;
Print["alpha_1 = -mu0 sigma (a^2+b^2)/48 = ", N[alphaLFRef, 16],
  "  (closed form, basis-independent)"];

(* alpha_n for n >= 2 *)
KinvMpow[n_] := Module[{cur = KAugInv}, Do[cur = cur . MAug . KAugInv, {n - 1}]; cur];
alphaN[n_] := Module[{matn},
  matn = If[n == 1, KAugInv, Nest[# . MAug . KAugInv &, KAugInv, n - 1]];
  (-1)^(n - 1) (mu0N sigmaN)^n / VN * (bAug . matn . bAug)];

(* Note: alpha_2 = +(mu0 sigma)^2/V b K^{-1} b *)
Do[Print["alpha_", k, " = ", N[alphaN[k], 16],
  "    (sphere ref: ", N[alphaSphere[Sqrt[ReffSq], k], 12],
  ", ratio: ", N[alphaN[k]/alphaSphere[Sqrt[ReffSq], k], 8], ")"],
  {k, 2, 5}];
Print[""];

(* === Compare to interior PEC-only baseline === *)
Print["=== Comparison ==="];
alpha2InteriorOnly = (mu0N sigmaN)^2 / VN * Sum[bIVec[[i]]^2/KII[[i, i]], {i, nInt}];
Print["alpha_2 interior PEC only (Step 1+2): ", N[alpha2InteriorOnly, 16]];
Print["alpha_2 enriched (interior + dipole): ", N[alphaN[2], 16]];
Print["alpha_2 sphere R_eff:                 ",
  N[alphaSphere[Sqrt[ReffSq], 2], 16]];
Print[""];
Print["Improvement ratio (enriched/interior_only): ",
  N[alphaN[2]/alpha2InteriorOnly, 8]];
Print["Gap to sphere ref (enriched/sphere):       ",
  N[alphaN[2]/alphaSphere[Sqrt[ReffSq], 2], 8]];
Print[""];

Print["=== Stage 5a Step 3 summary ==="];
Print["* Single dipole exterior basis enriches interior PEC by factor ",
  N[alphaN[2]/alpha2InteriorOnly, 4]];
Print["* Remaining gap to sphere reference: ratio = ",
  N[alphaN[2]/alphaSphere[Sqrt[ReffSq], 2], 4]];
Print["* Higher multipoles (octupole etc) and R_0 sweep would further close gap"];
Print[""];

(* Save numerical results *)
results = <|
  "Pmax" -> Pmax,
  "nInt" -> nInt,
  "R0_mm" -> N[R0*1000, 6],
  "alphaLF" -> N[alphaLFRef, 30],
  "alpha2_interiorOnly" -> N[alpha2InteriorOnly, 30],
  "alpha2_enriched" -> N[alphaN[2], 30],
  "alpha2_sphereRef" -> N[alphaSphere[Sqrt[ReffSq], 2], 30],
  "alpha3_enriched" -> N[alphaN[3], 30],
  "alpha4_enriched" -> N[alphaN[4], 30]
|>;
Print["Results: ", results];

(* Stage 5b: Correct H(curl)-conforming PEC TE_z basis for cuboid.

   This corrects Stage 5a's incorrect formulation. The new basis:
     phi^TE_{p,q,r} = cos(p pi (x+a/2)/a) cos(q pi (y+b/2)/b) sin(r pi (z+c/2)/c)
     A^TE = curl(z_hat phi^TE)  with proper PEC tangential vanishing on all 6 faces.

   Parity (uniform B_z + D_2h): p even >= 0, q even >= 0, r odd >= 1.

   Source coupling discovery:
     b^{(0,q,r)} = -V/(r pi)   (q-independent, q even >= 2)
     b^{(p,0,r)} = -V/(r pi)   (p-independent, p even >= 2)
     b^{(p>=2,q>=2,r)} = 0     (cosine vanishes over full period)

   Closed-form alpha_2 from infinite series of edge modes.
*)
$HistoryLength = 0;
prec = 60;

Print["=== Stage 5b: Correct PEC TE_z basis (closed PEC, all closed form) ==="];
Print[""];

(* Constants *)
sigmaN = SetPrecision[58000000, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
PiN = SetPrecision[Pi, prec];
VN = aN bN cN;
ReffSq = 5 (aN^2 + bN^2)/24;
alphaLFRef = -mu0N sigmaN (aN^2 + bN^2)/48;

(* Sphere reference *)
alphaSphere[R_, k_] := Module[{x = mu0N sigmaN R^2, ck},
  ck = Switch[k, 1, -1/10, 2, +1/105, 3, -1/1050, 4, +1/10395, 5, -1/135135,
    _, (-1)^k * 9 * SetPrecision[Zeta[2 k + 2], prec]/PiN^(2 k + 2)];
  ck * x^k];

Print["Sphere reference (R_eff^2 = 5(a^2+b^2)/24):"];
Print["  alpha_1^sph = ", N[alphaSphere[Sqrt[ReffSq], 1], 16]];
Print["  alpha_2^sph = ", N[alphaSphere[Sqrt[ReffSq], 2], 16]];
Print["  alpha_3^sph = ", N[alphaSphere[Sqrt[ReffSq], 3], 16]];
Print[""];

(* === Closed-form alpha_2 from infinite TE_z mode series ===

   For (0, q, r) modes:
     A_x = -(q pi/b) sin(q pi v) sin(r pi w)   (cos(0)=1 in x)
     A_y = 0
     |A|^2 = (q pi/b)^2 sin^2(q pi v) sin^2(r pi w)
     M_ii = (V/4) (q pi/b)^2
     lambda_(0,q,r) = pi^2((q/b)^2 + (r/c)^2)
     K_ii = lambda * M_ii = (V/4)(q pi/b)^2 pi^2((q/b)^2 + (r/c)^2)
     b^{(0,q,r)} = -V/(r pi)
     b^2/K = (V^2/(r^2 pi^2)) / [(V/4)(q pi/b)^2 pi^2((q/b)^2 + (r/c)^2)]
           = 4 V b^2 / [q^2 r^2 pi^6 ((q/b)^2 + (r/c)^2)]
           = 4 V b^4 c^2 / [pi^6 q^2 r^2 (q^2 c^2 + r^2 b^2)]

   Sum over q even >= 2, r odd >= 1.  Substitute q = 2 q', q' >= 1:
     S0qr = sum (q'>=1, r odd) b^4 c^2 / [pi^6 (2q')^2 r^2 ((2q')^2 c^2 + r^2 b^2)]
          = b^4 c^2 / (4 pi^6) sum (q'>=1, r odd) 1/[q'^2 r^2 (4 q'^2 c^2 + r^2 b^2)]
*)

(* alpha_2 from (0, q, r) family *)
NMaxQ = 60;  (* truncation *)
NMaxR = 121;  (* odd up to 121 *)

S0qr = Sum[1/(qp^2 r^2 (4 qp^2 cN^2 + r^2 bN^2)),
  {qp, 1, NMaxQ}, {r, 1, NMaxR, 2}];
contrib0qr = (mu0N sigmaN)^2/VN * 4 VN bN^4 cN^2/(4 PiN^6) * S0qr;

(* Symmetric (p, 0, r) family with a <-> b: *)
Sp0r = Sum[1/(pp^2 r^2 (4 pp^2 cN^2 + r^2 aN^2)),
  {pp, 1, NMaxQ}, {r, 1, NMaxR, 2}];
contribp0r = (mu0N sigmaN)^2/VN * 4 VN aN^4 cN^2/(4 PiN^6) * Sp0r;

alpha2PEC = contrib0qr + contribp0r;

Print["alpha_2 closed PEC TE_z (truncated NMaxQ=", NMaxQ, ", NMaxR=", NMaxR, "):"];
Print["  contribution from (0, q, r): ", N[contrib0qr, 16]];
Print["  contribution from (p, 0, r): ", N[contribp0r, 16]];
Print["  total alpha_2^PEC = ", N[alpha2PEC, 16]];
Print[""];

(* Convergence study *)
Print["=== Convergence with truncation ==="];
Do[Module[{S0, Sp0, alpha2, NQ, NR},
  {NQ, NR} = pair;
  S0 = Sum[1/(qp^2 r^2 (4 qp^2 cN^2 + r^2 bN^2)),
    {qp, 1, NQ}, {r, 1, 2 NR + 1, 2}];
  Sp0 = Sum[1/(pp^2 r^2 (4 pp^2 cN^2 + r^2 aN^2)),
    {pp, 1, NQ}, {r, 1, 2 NR + 1, 2}];
  alpha2 = (mu0N sigmaN)^2 * (bN^4 cN^2 S0 + aN^4 cN^2 Sp0)/PiN^6;
  Print["  NMaxQ=", NQ, ", NMaxR=", 2 NR + 1, ": alpha_2^PEC = ",
    N[alpha2, 16]]],
  {pair, {{10, 20}, {20, 40}, {40, 60}, {60, 90}, {80, 120}}}];
Print[""];

(* Compare to sphere *)
sphAlpha2 = alphaSphere[Sqrt[ReffSq], 2];
Print["Sphere reference alpha_2^sph(R_eff) = ", N[sphAlpha2, 16]];
Print["Ratio alpha_2^PEC / alpha_2^sph = ", N[alpha2PEC/sphAlpha2, 8]];
Print[""];
Print["Note: PEC closed cuboid CANNOT match vacuum sphere because"];
Print["it lacks the eddy current bleed-out into vacuum.  Need exterior"];
Print["multipole basis enrichment (Step 5c)."];
Print[""];

(* === Try also: alpha_2 from sin sin sin scalar Dirichlet basis (Step 1+2 baseline) ===
   For comparison: that was a different (incorrect for vector PEC) basis.
   Just show numerical value to compare basis effects. *)
Print["=== Comparison to incorrect Step 1+2 sin-basis ==="];
Print["  Step 1+2 (sin sin sin scalar Dirichlet): alpha_2 = 8.349e-11 (Pmax=11)"];
Print["  Step 5b (correct PEC TE_z, infinite basis): alpha_2 = ", N[alpha2PEC, 12]];
Print["  Ratio = ", N[8.349*10^-11 / alpha2PEC, 6]];
Print[""];

Print["=== Closed PEC alpha_n series (TE_z complete basis) ==="];
(* General closed form for alpha_n from (0, q, r) edge modes, n >= 2:
   alpha_n contribution from (0,q,r) = (-1)^(n-1) (mu0 sigma)^n / V * b_i^2 M_ii^(n-2) / K_ii^(n-1)
   b^2 = V^2/(r^2 pi^2)
   M_ii = (V/4)(q pi/b)^2
   K_ii = lambda M_ii = pi^2((q/b)^2+(r/c)^2) (V/4)(q pi/b)^2

   M_ii^(n-2) / K_ii^(n-1) = M_ii^(n-2)/[lambda^(n-1) M_ii^(n-1)] = 1/[lambda^(n-1) M_ii]
   = 1/[pi^2((q/b)^2+(r/c)^2)]^(n-1) / [(V/4)(q pi/b)^2]
   = 4/[V (q pi/b)^2 pi^(2n-2) ((q/b)^2+(r/c)^2)^(n-1)]

   So contribution = (-1)^(n-1)(mu0 sigma)^n V/r^2 pi^2 * 4/[V (q pi/b)^2 pi^(2n-2) ((q/b)^2+(r/c)^2)^(n-1)]
                   = (-1)^(n-1) 4 (mu0 sigma)^n b^2 / [q^2 r^2 pi^(2n+2) ((q/b)^2+(r/c)^2)^(n-1)]
*)

(* Compute alpha_3, alpha_4, alpha_5 *)
computeAlphaN[n_, NMaxQ_, NMaxR_] := Module[{S0, Sp0},
  S0 = Sum[
    bN^(2 n - 2)/(qp^2 r^2 ((2 qp)^(2 n - 2) cN^(2 n - 2) +
        (2 qp)^(2 n - 4) (2 qp)^2 cN^(2 n - 4) bN^2 r^2 *
          0)) (* simpler: ((q/b)^2+(r/c)^2)^(n-1) = sum binomial *)
    , {qp, 1, NMaxQ}, {r, 1, 2 NMaxR + 1, 2}];
  (* Actually, just use direct computation: *)
  S0 = Sum[
    1/(qp^2 r^2 ((2 qp/bN)^2 + (r/cN)^2)^(n - 1)),
    {qp, 1, NMaxQ}, {r, 1, 2 NMaxR + 1, 2}];
  Sp0 = Sum[
    1/(pp^2 r^2 ((2 pp/aN)^2 + (r/cN)^2)^(n - 1)),
    {pp, 1, NMaxQ}, {r, 1, 2 NMaxR + 1, 2}];
  (-1)^(n - 1) * 4 (mu0N sigmaN)^n / (4 PiN^(2 n + 2)) * (bN^2 S0 + aN^2 Sp0)];

Do[Module[{val},
  val = computeAlphaN[k, 60, 60];
  Print["alpha_", k, "^PEC = ", N[val, 16],
    "  (sphere ref: ", N[alphaSphere[Sqrt[ReffSq], k], 12],
    ", ratio: ", N[val/alphaSphere[Sqrt[ReffSq], k], 8], ")"]],
  {k, 2, 5}];
Print[""];

Print["=== Stage 5b summary ==="];
Print["* Correct PEC TE_z basis derived (cos cos sin)"];
Print["* Source coupling: only edge modes (p=0 or q=0)"];
Print["* alpha_2^PEC (full TE basis) = ", N[alpha2PEC, 8]];
Print["  Closed PEC alpha_2 captured as DOUBLE infinite series"];
Print[""];
Print["Next: Step 5c -- enrich with exterior multipole for vacuum BC"];

(* Stage 5c: PEC TE_z basis (correct H(curl)-conforming) + exterior dipole.

   This corrects Stage 5a Step 3 by replacing the bogus sin-basis with the
   proper PEC TE_z basis from Stage 5b.

   Interior basis (PEC TE_z):
     A^I_{p,q,r} = curl(z_hat phi^TE_{p,q,r})
     phi^TE_{p,q,r} = cos(p pi (x+a/2)/a) cos(q pi (y+b/2)/b) sin(r pi (z+c/2)/c)
   Parity-restricted: p even >= 0, q even >= 0, r odd >= 1, AND only edge
   modes (p=0 or q=0 but not both) couple to uniform B_z source.

   Exterior basis (1 dipole mode):
     Phi^E(r) = (-y, x, 0)/(r^2 + R_0^2)^(3/2)
   Same as Step 3 but now interior is correctly H(curl)-conforming so K^IE
   and M^IE are well-defined as conductor integrals (no surface delta).

   Augmented Galerkin: n_edge + 1 unknowns.
*)
$HistoryLength = 0;
prec = 60;

Print["=== Stage 5c: PEC TE_z + dipole multipole ==="];
Print[""];

(* Constants *)
sigmaN = SetPrecision[58000000, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
PiN = SetPrecision[Pi, prec];
VN = aN bN cN;
ReffSq = 5 (aN^2 + bN^2)/24;
alphaLFRef = -mu0N sigmaN (aN^2 + bN^2)/48;

(* Sphere reference *)
alphaSphere[R_, k_] := Module[{x = mu0N sigmaN R^2, ck},
  ck = Switch[k, 1, -1/10, 2, +1/105, 3, -1/1050, 4, +1/10395, _,
    (-1)^k * 9 * SetPrecision[Zeta[2 k + 2], prec]/PiN^(2 k + 2)];
  ck * x^k];

Print["alpha_LF       = ", N[alphaLFRef, 16]];
Print["alpha_2^sph    = ", N[alphaSphere[Sqrt[ReffSq], 2], 16]];
Print[""];

(* === Edge mode indices === *)
(* (0, q, r) family: q in {2, 4, ..., 2 Q_max}, r in {1, 3, ..., 2 R_max + 1} *)
QMaxPrime = 3;  (* q' goes up to 3 -> q = 2,4,6 *)
RMax = 2;  (* r goes up to 2*RMax+1 = 5 *)
edge0qr = Flatten[Table[{0, 2 qp, 2 rp + 1}, {qp, 1, QMaxPrime},
    {rp, 0, RMax}], 1];
edgep0r = Flatten[Table[{2 pp, 0, 2 rp + 1}, {pp, 1, QMaxPrime},
    {rp, 0, RMax}], 1];
edgeIndices = Join[edge0qr, edgep0r];
nInt = Length[edgeIndices];
Print["Edge mode indices (Q_max'=", QMaxPrime, ", R_max=", RMax, "):"];
Print["  (0, q, r) family: ", edge0qr];
Print["  (p, 0, r) family: ", edgep0r];
Print["  total nInt = ", nInt];
Print[""];

(* === Interior matrices (closed form) === *)
(* For (0, q, r): M_ii = (V/4)(q pi/b)^2, K_ii = lambda M_ii where
   lambda = pi^2((q/b)^2 + (r/c)^2). b_i = -V/(r pi). *)
edgeMassDiag[idx_] := Module[{p, q, r, lam},
  {p, q, r} = idx;
  lam = If[p == 0, (q PiN/bN)^2, (p PiN/aN)^2];
  (VN/4) lam];

edgeStiffDiag[idx_] := Module[{p, q, r, lam, lamtot},
  {p, q, r} = idx;
  lam = If[p == 0, (q PiN/bN)^2, (p PiN/aN)^2];
  lamtot = PiN^2 ((p/aN)^2 + (q/bN)^2 + (r/cN)^2);
  (VN/4) lam * lamtot];

edgeSrc[idx_] := Module[{p, q, r}, {p, q, r} = idx; -VN/(r PiN)];

MIIDiag = Table[edgeMassDiag[idx], {idx, edgeIndices}];
KIIDiag = Table[edgeStiffDiag[idx], {idx, edgeIndices}];
bIVec = Table[edgeSrc[idx], {idx, edgeIndices}];

Print["Interior diagonal matrices (closed form, 60-digit):"];
Print["  M^II first 3: ", N[MIIDiag[[1 ;; 3]], 12]];
Print["  K^II first 3: ", N[KIIDiag[[1 ;; 3]], 12]];
Print["  b^I first 3:  ", N[bIVec[[1 ;; 3]], 12]];
Print[""];

(* Interior-only alpha_2 verification *)
alpha2IntOnly = (mu0N sigmaN)^2/VN * Sum[bIVec[[i]]^2/KIIDiag[[i]], {i, nInt}];
Print["alpha_2 interior PEC only (truncated to ", nInt, " edge modes): ",
  N[alpha2IntOnly, 16]];
Print["  (Stage 5b infinite series gave: 1.674e-10 -- this truncated value should be smaller)"];
Print[""];

(* === Exterior basis === *)
R0 = SetPrecision[1/1000, prec];  (* 1 mm *)
KEE = 15 PiN^2 / (32 R0^3);
Print["Exterior basis Phi^E = (-y, x, 0)/(r^2+R_0^2)^(3/2), R_0 = ", N[R0*1000, 6], " mm"];
Print["  K^EE (closed form) = 15 pi^2/(32 R_0^3) = ", N[KEE, 16]];
Print[""];

(* === NIntegrate setup === *)
wp = 50; ag = 35; pg = 30;
mr = 12;

(* Interior basis explicit forms (curl A^I and A^I) *)
AIxTE[p_, q_, r_, xx_, yy_, zz_] := -(q PiN/bN) Cos[p PiN (xx + aN/2)/aN] *
    Sin[q PiN (yy + bN/2)/bN] Sin[r PiN (zz + cN/2)/cN];
AIyTE[p_, q_, r_, xx_, yy_, zz_] := (p PiN/aN) Sin[p PiN (xx + aN/2)/aN] *
    Cos[q PiN (yy + bN/2)/bN] Sin[r PiN (zz + cN/2)/cN];
(* curl A^I *)
curlAIxTE[p_, q_, r_, xx_, yy_, zz_] := -(p PiN/aN)(r PiN/cN) Sin[p PiN (xx + aN/2)/aN] *
    Cos[q PiN (yy + bN/2)/bN] Cos[r PiN (zz + cN/2)/cN];
curlAIyTE[p_, q_, r_, xx_, yy_, zz_] := -(q PiN/bN)(r PiN/cN) Cos[p PiN (xx + aN/2)/aN] *
    Sin[q PiN (yy + bN/2)/bN] Cos[r PiN (zz + cN/2)/cN];
curlAIzTE[p_, q_, r_, xx_, yy_, zz_] := -((p PiN/aN)^2 + (q PiN/bN)^2) *
    Cos[p PiN (xx + aN/2)/aN] Cos[q PiN (yy + bN/2)/bN] Sin[r PiN (zz + cN/2)/cN];

(* curl Phi^E *)
curlPhiEx[xx_, yy_, zz_] := 3 xx zz/(xx^2 + yy^2 + zz^2 + R0^2)^(5/2);
curlPhiEy[xx_, yy_, zz_] := 3 yy zz/(xx^2 + yy^2 + zz^2 + R0^2)^(5/2);
curlPhiEz[xx_, yy_, zz_] := (2 (zz^2 + R0^2) - (xx^2 + yy^2))/
    (xx^2 + yy^2 + zz^2 + R0^2)^(5/2);

(* Phi^E *)
PhiEx[xx_, yy_, zz_] := -yy/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2);
PhiEy[xx_, yy_, zz_] := xx/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2);

(* === Compute NIntegrate matrices === *)
Print["Computing M^EE (1 NIntegrate, expect ~30s)..."];
tStart = AbsoluteTime[];
MEE = NIntegrate[
  (xx^2 + yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^3,
  {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
  WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
  MaxRecursion -> mr];
Print["  M^EE = ", N[MEE, 16], "  (", N[AbsoluteTime[] - tStart, 4], " s)"];

Print["Computing b^E (1 NIntegrate)..."];
tStart = AbsoluteTime[];
bE = (1/2) NIntegrate[
  (xx^2 + yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2),
  {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
  WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
  MaxRecursion -> mr];
Print["  b^E = ", N[bE, 16], "  (", N[AbsoluteTime[] - tStart, 4], " s)"];

Print["Computing M^IE (", nInt, " NIntegrates)..."];
tStart = AbsoluteTime[];
MIEVec = Table[Module[{p, q, r, integrand, val},
  {p, q, r} = edgeIndices[[i]];
  integrand = (AIxTE[p, q, r, xx, yy, zz] PhiEx[xx, yy, zz] +
               AIyTE[p, q, r, xx, yy, zz] PhiEy[xx, yy, zz]);
  val = NIntegrate[integrand,
    {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
    WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
    MaxRecursion -> mr];
  Print["  M^IE[", edgeIndices[[i]], "] = ", N[val, 12]];
  val],
  {i, nInt}];
Print["  M^IE total time: ", N[AbsoluteTime[] - tStart, 4], " s"];

Print["Computing K^IE (", nInt, " NIntegrates)..."];
tStart = AbsoluteTime[];
KIEVec = Table[Module[{p, q, r, integrand, val},
  {p, q, r} = edgeIndices[[i]];
  integrand = (curlAIxTE[p, q, r, xx, yy, zz] curlPhiEx[xx, yy, zz] +
               curlAIyTE[p, q, r, xx, yy, zz] curlPhiEy[xx, yy, zz] +
               curlAIzTE[p, q, r, xx, yy, zz] curlPhiEz[xx, yy, zz]);
  val = NIntegrate[integrand,
    {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
    WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
    MaxRecursion -> mr];
  Print["  K^IE[", edgeIndices[[i]], "] = ", N[val, 12]];
  val],
  {i, nInt}];
Print["  K^IE total time: ", N[AbsoluteTime[] - tStart, 4], " s"];
Print[""];

(* === Build augmented system === *)
nTot = nInt + 1;
MAug = Table[0, {nTot}, {nTot}];
KAug = Table[0, {nTot}, {nTot}];
bAug = Join[bIVec, {bE}];
Do[MAug[[i, i]] = MIIDiag[[i]]; KAug[[i, i]] = KIIDiag[[i]], {i, nInt}];
Do[MAug[[i, nTot]] = MIEVec[[i]]; MAug[[nTot, i]] = MIEVec[[i]];
   KAug[[i, nTot]] = KIEVec[[i]]; KAug[[nTot, i]] = KIEVec[[i]],
  {i, nInt}];
MAug[[nTot, nTot]] = MEE;
KAug[[nTot, nTot]] = KEE;

KAugInv = Inverse[KAug];

(* Sanity check: K should be symmetric positive definite *)
Print["K matrix Schur complement (>0 for PD):"];
schur = KEE - Sum[KIEVec[[i]]^2/KIIDiag[[i]], {i, nInt}];
Print["  K^EE - K^EI K^II^(-1) K^IE = ", N[schur, 12]];
If[N[schur, 12] > 0, Print["  -> K augmented is positive definite ✓"],
  Print["  -> K augmented is NOT positive definite (problem)"]];
Print[""];

(* alpha_n via series *)
alphaN[n_] := (-1)^n (mu0N sigmaN)^n/VN *
  bAug.Nest[# . MAug . KAugInv &, KAugInv, n - 2].bAug;

Print["=== Augmented Galerkin alpha_n ==="];
Do[Module[{val},
  val = alphaN[k];
  Print["alpha_", k, " = ", N[val, 16],
    "  (sphere ref: ", N[alphaSphere[Sqrt[ReffSq], k], 12],
    ", ratio: ", N[val/alphaSphere[Sqrt[ReffSq], k], 8], ")"]],
  {k, 2, 4}];
Print[""];

Print["=== Improvement summary ==="];
Print["alpha_2 interior only (truncated):  ", N[alpha2IntOnly, 16]];
Print["alpha_2 enriched (interior+dipole): ", N[alphaN[2], 16]];
Print["alpha_2 sphere R_eff:               ",
  N[alphaSphere[Sqrt[ReffSq], 2], 16]];
Print[""];
Print["Improvement ratio (enriched/interior_only): ",
  N[alphaN[2]/alpha2IntOnly, 8]];
Print["Gap to sphere ref (enriched/sphere):       ",
  N[alphaN[2]/alphaSphere[Sqrt[ReffSq], 2], 8]];

(* Stage 5d: Stage 5c + axial octupole exterior basis.

   Adds Phi^E_3(r) = (4z^2 - x^2 - y^2)(-y, x, 0) / (r^2 + R_0^2)^(7/2)
   This is the regularized vector potential for axial magnetic octupole
   (l=3, m=0). At infinity: A ~ 1/r^4, B = curl A ~ 1/r^5 (octupole field).

   Augmented basis: n_int + 2 (interior PEC TE_z + dipole + octupole).
*)
$HistoryLength = 0;
prec = 60;

Print["=== Stage 5d: PEC TE_z + dipole + octupole (axial) ==="];
Print[""];

(* Constants *)
sigmaN = SetPrecision[58000000, prec];
mu0N = SetPrecision[4 Pi/10^7, prec];
aN = SetPrecision[5/1000, prec];
bN = SetPrecision[2/1000, prec];
cN = SetPrecision[1/1000, prec];
PiN = SetPrecision[Pi, prec];
VN = aN bN cN;
ReffSq = 5 (aN^2 + bN^2)/24;
alphaLFRef = -mu0N sigmaN (aN^2 + bN^2)/48;

alphaSphere[R_, k_] := Module[{x = mu0N sigmaN R^2, ck},
  ck = Switch[k, 1, -1/10, 2, +1/105, 3, -1/1050, 4, +1/10395, _,
    (-1)^k * 9 * SetPrecision[Zeta[2 k + 2], prec]/PiN^(2 k + 2)];
  ck * x^k];

(* Edge mode indices (same as Stage 5c) *)
QMaxPrime = 3;
RMax = 2;
edge0qr = Flatten[Table[{0, 2 qp, 2 rp + 1}, {qp, 1, QMaxPrime},
    {rp, 0, RMax}], 1];
edgep0r = Flatten[Table[{2 pp, 0, 2 rp + 1}, {pp, 1, QMaxPrime},
    {rp, 0, RMax}], 1];
edgeIndices = Join[edge0qr, edgep0r];
nInt = Length[edgeIndices];
Print["Interior PEC TE_z basis: nInt = ", nInt];

(* Diagonal interior matrices *)
edgeMassDiag[idx_] := Module[{p, q, r, lam}, {p, q, r} = idx;
  lam = If[p == 0, (q PiN/bN)^2, (p PiN/aN)^2];
  (VN/4) lam];
edgeStiffDiag[idx_] := Module[{p, q, r, lam, lamtot}, {p, q, r} = idx;
  lam = If[p == 0, (q PiN/bN)^2, (p PiN/aN)^2];
  lamtot = PiN^2 ((p/aN)^2 + (q/bN)^2 + (r/cN)^2);
  (VN/4) lam * lamtot];
edgeSrc[idx_] := Module[{p, q, r}, {p, q, r} = idx; -VN/(r PiN)];

MIIDiag = Table[edgeMassDiag[idx], {idx, edgeIndices}];
KIIDiag = Table[edgeStiffDiag[idx], {idx, edgeIndices}];
bIVec = Table[edgeSrc[idx], {idx, edgeIndices}];

(* === External bases === *)
R0 = SetPrecision[1/1000, prec];

(* Dipole: Phi^E1 = (-y, x, 0)/(r^2+R0^2)^(3/2) *)
KEE1 = 15 PiN^2 / (32 R0^3);  (* closed form *)

(* Octupole: Phi^E3 = (4z^2 - x^2 - y^2)(-y, x, 0)/(r^2+R0^2)^(7/2) *)
(* K^E3 E3 = integral|curl Phi^E3|^2 dV over R^3 -- need to compute.
   Will compute via NIntegrate over large box for now (could do analytically later). *)

(* Phi^E1, Phi^E3 in Mathematica form *)
(* Phi^E1 components: *)
PhiE1x[xx_, yy_, zz_] := -yy/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2);
PhiE1y[xx_, yy_, zz_] := xx/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2);
(* curl Phi^E1: *)
curlPhiE1x[xx_, yy_, zz_] := 3 xx zz/(xx^2 + yy^2 + zz^2 + R0^2)^(5/2);
curlPhiE1y[xx_, yy_, zz_] := 3 yy zz/(xx^2 + yy^2 + zz^2 + R0^2)^(5/2);
curlPhiE1z[xx_, yy_, zz_] := (2 (zz^2 + R0^2) - (xx^2 + yy^2))/
    (xx^2 + yy^2 + zz^2 + R0^2)^(5/2);

(* Phi^E3 = (4z^2 - x^2 - y^2)(-y, x, 0)/(r^2+R0^2)^(7/2) *)
PhiE3x[xx_, yy_, zz_] := -yy (4 zz^2 - xx^2 - yy^2)/
    (xx^2 + yy^2 + zz^2 + R0^2)^(7/2);
PhiE3y[xx_, yy_, zz_] := xx (4 zz^2 - xx^2 - yy^2)/
    (xx^2 + yy^2 + zz^2 + R0^2)^(7/2);
(* curl Phi^E3: compute symbolically *)
phiE3xSym = -yy (4 zz^2 - xx^2 - yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^(7/2);
phiE3ySym = xx (4 zz^2 - xx^2 - yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^(7/2);
curlPhiE3xSym = -D[phiE3ySym, zz];  (* -d_z A_y *)
curlPhiE3ySym = D[phiE3xSym, zz];   (* d_z A_x *)
curlPhiE3zSym = D[phiE3ySym, xx] - D[phiE3xSym, yy];

curlPhiE3x[xx0_, yy0_, zz0_] := curlPhiE3xSym /. {xx -> xx0, yy -> yy0, zz -> zz0};
curlPhiE3y[xx0_, yy0_, zz0_] := curlPhiE3ySym /. {xx -> xx0, yy -> yy0, zz -> zz0};
curlPhiE3z[xx0_, yy0_, zz0_] := curlPhiE3zSym /. {xx -> xx0, yy -> yy0, zz -> zz0};

(* Interior basis explicit forms *)
AIxTE[p_, q_, r_, xx_, yy_, zz_] := -(q PiN/bN) Cos[p PiN (xx + aN/2)/aN] *
    Sin[q PiN (yy + bN/2)/bN] Sin[r PiN (zz + cN/2)/cN];
AIyTE[p_, q_, r_, xx_, yy_, zz_] := (p PiN/aN) Sin[p PiN (xx + aN/2)/aN] *
    Cos[q PiN (yy + bN/2)/bN] Sin[r PiN (zz + cN/2)/cN];
curlAIxTE[p_, q_, r_, xx_, yy_, zz_] := -(p PiN/aN)(r PiN/cN) Sin[p PiN (xx + aN/2)/aN] *
    Cos[q PiN (yy + bN/2)/bN] Cos[r PiN (zz + cN/2)/cN];
curlAIyTE[p_, q_, r_, xx_, yy_, zz_] := -(q PiN/bN)(r PiN/cN) Cos[p PiN (xx + aN/2)/aN] *
    Sin[q PiN (yy + bN/2)/bN] Cos[r PiN (zz + cN/2)/cN];
curlAIzTE[p_, q_, r_, xx_, yy_, zz_] := -((p PiN/aN)^2 + (q PiN/bN)^2) *
    Cos[p PiN (xx + aN/2)/aN] Cos[q PiN (yy + bN/2)/bN] Sin[r PiN (zz + cN/2)/cN];

(* === NIntegrate parameters === *)
wp = 50; ag = 30; pg = 25; mr = 12;

(* Direct NIntegrate calls (avoid Sequence @@ scope bug) *)
doInt[expr_] := NIntegrate[expr,
  {xx, -aN/2, aN/2}, {yy, -bN/2, bN/2}, {zz, -cN/2, cN/2},
  WorkingPrecision -> wp, AccuracyGoal -> ag, PrecisionGoal -> pg,
  MaxRecursion -> mr];

(* === Recompute dipole interactions (already known from 5c, but redo for consistency) === *)
Print["Computing M^E1 E1, b^E1 (dipole self & source) ..."];
tStart = AbsoluteTime[];
ME1E1 = doInt[(xx^2 + yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^3];
bE1 = (1/2) doInt[(xx^2 + yy^2)/(xx^2 + yy^2 + zz^2 + R0^2)^(3/2)];
Print["  M^E1E1 = ", N[ME1E1, 12], "  (", N[AbsoluteTime[] - tStart, 4], "s)"];
Print["  b^E1   = ", N[bE1, 12]];

(* === Octupole self & source === *)
Print["Computing M^E3 E3, b^E3 (octupole self & source) ..."];
tStart = AbsoluteTime[];
(* Phi^E3 . Phi^E3 = (x^2+y^2)(4z^2-x^2-y^2)^2/(r^2+R0^2)^7 *)
ME3E3 = doInt[(xx^2 + yy^2)(4 zz^2 - xx^2 - yy^2)^2/
    (xx^2 + yy^2 + zz^2 + R0^2)^7];
(* b^E3 = (1/2) integral (x A_ext_y - y A_ext_x)... wait
   b^E3 = integral Phi^E3 . A_ext dV = (1/2) integral (x^2+y^2)(4z^2-x^2-y^2)/(r^2+R0^2)^(7/2) dV *)
bE3 = (1/2) doInt[(xx^2 + yy^2)(4 zz^2 - xx^2 - yy^2)/
    (xx^2 + yy^2 + zz^2 + R0^2)^(7/2)];
Print["  M^E3E3 = ", N[ME3E3, 12], "  (", N[AbsoluteTime[] - tStart, 4], "s)"];
Print["  b^E3   = ", N[bE3, 12]];

(* Dipole-octupole cross-coupling *)
Print["Computing M^E1 E3, K^E1 E3 (cross terms) ..."];
tStart = AbsoluteTime[];
(* Phi^E1 . Phi^E3 = (-y)(-y)(4z^2-x^2-y^2)/(r^2+R0^2)^(3/2+7/2) + (x)(x)(4z^2-..)/...
                  = (y^2 + x^2)(4z^2 - x^2 - y^2)/(r^2+R0^2)^5 *)
ME1E3 = doInt[(xx^2 + yy^2)(4 zz^2 - xx^2 - yy^2)/
    (xx^2 + yy^2 + zz^2 + R0^2)^5];
(* curl Phi^E1 . curl Phi^E3 over R^3: too costly; compute over conductor only and add closed form *)
KE1E3cond = doInt[curlPhiE1x[xx, yy, zz] curlPhiE3xSym +
                  curlPhiE1y[xx, yy, zz] curlPhiE3ySym +
                  curlPhiE1z[xx, yy, zz] curlPhiE3zSym];
(* For exterior portion of K^E1 E3: orthogonality of dipole and octupole spherical
   harmonics over angles gives 0 in the limit R0 -> 0. Will compute as exterior integral
   if needed. For now use just conductor part as approximation. *)
KE1E3 = KE1E3cond; (* approximation: most of K^E1 E3 contribution is over conductor for our R0 ~ size *)

Print["  M^E1E3 = ", N[ME1E3, 12], "  (", N[AbsoluteTime[] - tStart, 4], "s)"];
Print["  K^E1E3 (cond only) = ", N[KE1E3, 12]];

(* === K^E3 E3 over R^3: use spherical sym + axial part === *)
(* Numerical via large-box NIntegrate, scale by R0 *)
Print["Computing K^E3 E3 (over R^3, via large box scaling) ..."];
tStart = AbsoluteTime[];
(* Substitution r = R0 t makes integrand pure dimensionless. integral = R0^(-7) * dimensionless *)
(* Skip full R^3 for now; use conductor-only approximation as warning *)
KE3E3cond = doInt[curlPhiE3xSym^2 + curlPhiE3ySym^2 + curlPhiE3zSym^2];
KE3E3 = KE3E3cond;  (* approximation *)
Print["  K^E3E3 (cond only) = ", N[KE3E3, 12], "  (", N[AbsoluteTime[] - tStart, 4], "s)"];
Print["  WARNING: should add exterior contribution (large-box NIntegrate or closed form)"];
Print[""];

(* === Interior <-> Dipole coupling (recompute or load from 5c) === *)
Print["Computing M^IE1, K^IE1 (", nInt, " each)..."];
tStart = AbsoluteTime[];
MIE1Vec = Table[Module[{p, q, r}, {p, q, r} = edgeIndices[[i]];
  doInt[AIxTE[p, q, r, xx, yy, zz] PhiE1x[xx, yy, zz] +
        AIyTE[p, q, r, xx, yy, zz] PhiE1y[xx, yy, zz]]],
  {i, nInt}];
KIE1Vec = Table[Module[{p, q, r}, {p, q, r} = edgeIndices[[i]];
  doInt[curlAIxTE[p, q, r, xx, yy, zz] curlPhiE1x[xx, yy, zz] +
        curlAIyTE[p, q, r, xx, yy, zz] curlPhiE1y[xx, yy, zz] +
        curlAIzTE[p, q, r, xx, yy, zz] curlPhiE1z[xx, yy, zz]]],
  {i, nInt}];
Print["  M^IE1, K^IE1 done (", N[AbsoluteTime[] - tStart, 4], "s)"];

(* === Interior <-> Octupole coupling === *)
Print["Computing M^IE3, K^IE3 (", nInt, " each)..."];
tStart = AbsoluteTime[];
MIE3Vec = Table[Module[{p, q, r}, {p, q, r} = edgeIndices[[i]];
  doInt[AIxTE[p, q, r, xx, yy, zz] PhiE3x[xx, yy, zz] +
        AIyTE[p, q, r, xx, yy, zz] PhiE3y[xx, yy, zz]]],
  {i, nInt}];
KIE3Vec = Table[Module[{p, q, r}, {p, q, r} = edgeIndices[[i]];
  doInt[curlAIxTE[p, q, r, xx, yy, zz] curlPhiE3xSym +
        curlAIyTE[p, q, r, xx, yy, zz] curlPhiE3ySym +
        curlAIzTE[p, q, r, xx, yy, zz] curlPhiE3zSym]],
  {i, nInt}];
Print["  M^IE3, K^IE3 done (", N[AbsoluteTime[] - tStart, 4], "s)"];
Print[""];

(* === Build augmented system === *)
nTot = nInt + 2;  (* +1 dipole +1 octupole *)
MAug = Table[0, {nTot}, {nTot}];
KAug = Table[0, {nTot}, {nTot}];
bAug = Table[0, {nTot}];

Do[MAug[[i, i]] = MIIDiag[[i]]; KAug[[i, i]] = KIIDiag[[i]]; bAug[[i]] = bIVec[[i]],
  {i, nInt}];
(* dipole row/col = nInt+1 *)
Do[MAug[[i, nInt+1]] = MIE1Vec[[i]]; MAug[[nInt+1, i]] = MIE1Vec[[i]];
   KAug[[i, nInt+1]] = KIE1Vec[[i]]; KAug[[nInt+1, i]] = KIE1Vec[[i]],
  {i, nInt}];
MAug[[nInt+1, nInt+1]] = ME1E1; KAug[[nInt+1, nInt+1]] = KEE1; bAug[[nInt+1]] = bE1;
(* octupole row/col = nInt+2 *)
Do[MAug[[i, nInt+2]] = MIE3Vec[[i]]; MAug[[nInt+2, i]] = MIE3Vec[[i]];
   KAug[[i, nInt+2]] = KIE3Vec[[i]]; KAug[[nInt+2, i]] = KIE3Vec[[i]],
  {i, nInt}];
MAug[[nInt+1, nInt+2]] = ME1E3; MAug[[nInt+2, nInt+1]] = ME1E3;
KAug[[nInt+1, nInt+2]] = KE1E3; KAug[[nInt+2, nInt+1]] = KE1E3;
MAug[[nInt+2, nInt+2]] = ME3E3; KAug[[nInt+2, nInt+2]] = KE3E3;
bAug[[nInt+2]] = bE3;

KAugInv = Inverse[KAug];

alphaN[n_] := (-1)^n (mu0N sigmaN)^n/VN *
  bAug.Nest[# . MAug . KAugInv &, KAugInv, n - 2].bAug;

Print["=== Augmented Galerkin alpha_n (with octupole) ==="];
Do[Module[{val, sphV},
  val = alphaN[k]; sphV = alphaSphere[Sqrt[ReffSq], k];
  Print["alpha_", k, " = ", N[val, 16],
    "  (sphere: ", N[sphV, 12], ", ratio: ", N[val/sphV, 8], ")"]],
  {k, 2, 5}];
Print[""];

(* Compare *)
Print["=== Improvement vs Stage 5c ==="];
Print["  alpha_2 5c (PEC + dipole only):    ~ 4.634e-10  (ratio 0.251)"];
Print["  alpha_2 5d (PEC + dipole+octupole): ", N[alphaN[2], 16],
      "  (ratio: ", N[alphaN[2]/alphaSphere[Sqrt[ReffSq], 2], 6], ")"];

(* ::Package:: *)

(* foster_cln_hex_phi.wls
   Closed-form Newton potential of arbitrary 8-node hexahedron, 30+ digit precision.

   Public API:
     PhiBoxClosed[P, x0, x1, y0, y1, z0, z1]   axis-aligned cuboid (Banerjee-Gupta 1977)
     TriFaceIntegral[p1, p2, p3, P]            int_T 1/|r-P| dA  (Wilton-Rao-Glisson 1984)
     TetNewtonPotential[v0, v1, v2, v3, P]     int_tet 1/|r-P| dV
     PhiHex[verts, P]                           int_hex 1/|r-P| dV  (5-tet decomposition)

   All functions accept arbitrary-precision inputs (e.g. SetPrecision[..., 30]).
   For axis-aligned cuboid input, PhiHex agrees with PhiBoxClosed to 30 digits.

   Date: 2026-05-02
*)

BeginPackage["FosterClnHexPhi`"];

PhiBoxClosed::usage = "PhiBoxClosed[P, x0, x1, y0, y1, z0, z1] gives the Newton potential int_box 1/|r-P| dV for axis-aligned cuboid [x0,x1]x[y0,y1]x[z0,z1]. Banerjee-Gupta 1977 closed form.";
TriFaceIntegral::usage = "TriFaceIntegral[p1, p2, p3, P] gives int_triangle 1/|r-P| dA where the triangle has vertices p1, p2, p3 (3D). Wilton-Rao-Glisson 1984 closed form.";
TetNewtonPotential::usage = "TetNewtonPotential[v0, v1, v2, v3, P] gives int_tet 1/|r-P| dV via 4-face sum.";
PhiHex::usage = "PhiHex[verts, P] gives int_hex 1/|r-P| dV for an 8-node hexahedron via 5-tet decomposition. verts is a list of 8 (x,y,z) vertices in standard hex ordering: 0..3 = bottom face CCW, 4..7 = top face CCW.";

Begin["`Private`"];

(* ===== Banerjee-Gupta antiderivative ===== *)
GAntider[x_, y_, z_] := Module[{R = Sqrt[x^2 + y^2 + z^2], term1, term2, term3, ax, ay, az},
  If[R == 0, Return[0]];
  term1 = If[x*y == 0, 0, x y Log[z + R]];
  term2 = If[y*z == 0, 0, y z Log[x + R]];
  term3 = If[z*x == 0, 0, z x Log[y + R]];
  ax = If[x == 0, 0, (x^2/2) ArcTan[y z / (x R)]];
  ay = If[y == 0, 0, (y^2/2) ArcTan[z x / (y R)]];
  az = If[z == 0, 0, (z^2/2) ArcTan[x y / (z R)]];
  term1 + term2 + term3 - ax - ay - az
];

PhiBoxClosed[P_List, x0_, x1_, y0_, y1_, z0_, z1_] := Module[
  {Px, Py, Pz, xs, ys, zs, total, sign},
  {Px, Py, Pz} = P;
  xs = {x0 - Px, x1 - Px};
  ys = {y0 - Py, y1 - Py};
  zs = {z0 - Pz, z1 - Pz};
  total = Sum[
    sign = If[EvenQ[i + j + k], 1, -1];
    sign * GAntider[xs[[i + 1]], ys[[j + 1]], zs[[k + 1]]],
    {i, 0, 1}, {j, 0, 1}, {k, 0, 1}
  ];
  -total
];

(* ===== Vector helpers ===== *)
VSub[a_List, b_List] := a - b;
VDot[a_List, b_List] := a.b;
VCross[a_List, b_List] := Cross[a, b];
VNorm[a_List] := Sqrt[a.a];
VScale[a_List, s_] := s * a;

(* ===== Solid angle (Van Oosterom-Strackee 1983) ===== *)
SolidAngleTriangle[p1_, p2_, p3_, P_] := Module[
  {a, b, c, la, lb, lc, num, den, result},
  a = p1 - P; b = p2 - P; c = p3 - P;
  la = VNorm[a]; lb = VNorm[b]; lc = VNorm[c];
  num = VDot[VCross[a, b], c];
  den = la lb lc + VDot[a, b] lc + VDot[a, c] lb + VDot[b, c] la;
  (* When P is on a vertex or in the triangle plane, both num and den can
     vanish, making ArcTan[den,num] indeterminate. Use Chop to identify the
     numerical-zero case; the prefactor in the calling formula vanishes there. *)
  If[Chop[num, 10^-30] === 0 && Chop[den, 10^-30] === 0, Return[0]];
  result = Quiet[2 ArcTan[den, num], {ArcTan::indet}];
  If[result === Indeterminate, 0, result]
];

(* ===== Triangle face integral: int_T 1/|r-P| dA  (closed form) =====
   I = h_signed * Omega - edge_sum
   per Wilton-Rao-Glisson 1984 / Graglia 1993, sign convention verified
   numerically against 2D quadrature.
*)
TriFaceIntegral[p1_List, p2_List, p3_List, P_List] := Module[
  {e12, e13, nUnnorm, area2, nhat, hSigned, rho0, Omega, verts,
   edgeSum, i, a, b, sVec, sLen, shat, mhat, ra, rb, Ra, Rb,
   tParam, lMinus, lPlus, tI0, argPlus, argMinus, fI},
  e12 = p2 - p1;
  e13 = p3 - p1;
  nUnnorm = VCross[e12, e13];
  area2 = VNorm[nUnnorm];
  If[area2 == 0, Return[0]];
  nhat = nUnnorm / area2;
  hSigned = VDot[P - p1, nhat];
  rho0 = P - hSigned nhat;
  Omega = SolidAngleTriangle[p1, p2, p3, P];
  verts = {p1, p2, p3};
  edgeSum = 0;
  Do[
    a = verts[[i]];
    b = verts[[Mod[i, 3] + 1]];
    sVec = b - a;
    sLen = VNorm[sVec];
    If[sLen == 0, Continue[]];
    shat = sVec / sLen;
    mhat = VCross[shat, nhat];
    ra = P - a; rb = P - b;
    Ra = VNorm[ra]; Rb = VNorm[rb];
    tParam = VDot[P - a, shat];
    lMinus = -tParam;
    lPlus = sLen - tParam;
    tI0 = VDot[rho0 - a, mhat];
    argPlus = Rb + lPlus;
    argMinus = Ra + lMinus;
    fI = If[argPlus > 0 && argMinus > 0,
      Log[argPlus / argMinus],
      Module[{argPlus2 = Rb - lPlus, argMinus2 = Ra - lMinus},
        If[argPlus2 > 0 && argMinus2 > 0,
          Log[argMinus2 / argPlus2],
          0
        ]
      ]
    ];
    edgeSum += tI0 fI,
    {i, 1, 3}
  ];
  hSigned Omega - edgeSum
];

(* ===== Tet Newton potential ===== *)
TetNewtonPotential[v0_List, v1_List, v2_List, v3_List, P_List] := Module[
  {verts, centroid, faceIndices, Phi, face, p1, p2, p3, e12, e13,
   nUnnorm, narea, nhat, outCheck, dF, fTri, idx},
  verts = {v0, v1, v2, v3};
  centroid = Mean[verts];
  (* Face i is opposite vertex i (1-indexed in Mathematica) *)
  faceIndices = {{2, 3, 4}, {1, 4, 3}, {1, 2, 4}, {1, 3, 2}};
  Phi = 0;
  Do[
    {p1, p2, p3} = verts[[face]];
    e12 = p2 - p1;
    e13 = p3 - p1;
    nUnnorm = VCross[e12, e13];
    narea = VNorm[nUnnorm];
    If[narea == 0, Continue[]];
    nhat = nUnnorm / narea;
    outCheck = VDot[p1 - centroid, nhat];
    If[outCheck < 0,
      {p2, p3} = {p3, p2};
      nhat = -nhat
    ];
    dF = VDot[P - p1, nhat];
    fTri = TriFaceIntegral[p1, p2, p3, P];
    Phi += -dF fTri / 2,
    {face, faceIndices}
  ];
  Phi
];

(* ===== Hex Newton potential via 5-tet decomposition ===== *)
(* Standard hex 5-tet split, vertex ordering 1..8 (Mathematica) *)
hex5tets = {{1, 2, 4, 5}, {2, 3, 4, 7}, {2, 5, 6, 7}, {4, 5, 7, 8}, {2, 4, 5, 7}};

PhiHex[verts_List /; Length[verts] == 8, P_List] := Module[
  {Phi = 0, tet, v0, v1, v2, v3},
  Do[
    {v0, v1, v2, v3} = verts[[tet]];
    Phi += TetNewtonPotential[v0, v1, v2, v3, P],
    {tet, hex5tets}
  ];
  Phi
];

End[];
