(* sphere_analytical_cln.wls
   Mathematica analytical computation of Cauer ladder for sphere with
   uniform B applied.

   Setup: Cu sphere radius a, σ uniform, uniform B_0 = 1 T applied.

   Analytical results:
     1) R_0 = 15 / (2π σ B_0² a⁵)  [from ∫σ|A_imposed|² dV with A = (B_0/2) r sin(θ)]
     2) Stoll Foster spectrum: τ_n = μ_0 σ a² / (n² π²), n = 1, 2, ...
     3) Foster amplitudes: from χ(s) = -1 + Σ (6/(n²π²))/(1 + sτ_n)
     4) Hankel-Padé Cauer ladder from Stoll Foster moments
*)

(* === Physical parameters === *)
mu0 = 4 Pi 10^-7;
sigma = 58 10^6;        (* Cu *)
B0 = 1;
a = 10/1000;            (* 10 mm *)

Print["=" <> StringRepeat["=", 70]];
Print[" Sphere analytical CLN: a = ", a 1000, " mm, σ = ", sigma, " S/m"];
Print["=" <> StringRepeat["=", 70]];
Print[];

(* === R_0 from Joule loss formula === *)
(* ∫σ|A_imposed|² dV = ∫_{sphere} σ × (B_0 r sin(θ)/2)² dV
                     = σ × B_0²/4 × ∫_0^a r⁴ dr × ∫_0^π sin³θ dθ × ∫_0^2π dφ
                     = σ × B_0²/4 × a⁵/5 × 4/3 × 2π
                     = (2π σ B_0² a⁵) / 15
*)
intsigmaAsq = (2 Pi sigma B0^2 a^5)/15;
R0canonical = 1/intsigmaAsq;

Print["1. R_0 from Joule loss formula (1T 印加, ω² で割った損失逆数):"];
Print["   R_0 = 15 / (2π σ B_0² a⁵)"];
Print["   Analytical R_0 = ", N[R0canonical, 10], " (dimensionless units)"];
Print[];

(* === Stoll Foster spectrum === *)
tauStoll[n_] := mu0 sigma a^2 / (n^2 Pi^2);

Print["2. Stoll Foster pole spectrum:"];
Print["   τ_n = μ_0 σ a² / (n² π²)"];
Print[Table[
  Row[{"   τ_", n, " = ", N[tauStoll[n] 10^6, 6], " μs"}],
  {n, 1, 6}] // TableForm];
Print[];

(* === Foster amplitudes === *)
(* χ(s) = -1 + Σ a_n / (1 + s τ_n) where a_n = 6/(n² π²) *)
fostAmplitude[n_] := 6/(n^2 Pi^2);

Print["3. Stoll Foster amplitudes (χ(s) representation):"];
Print["   a_n = 6 / (n² π²)"];
Print[Table[
  Row[{"   a_", n, " = ", N[fostAmplitude[n], 8]}],
  {n, 1, 6}] // TableForm];
Print["   Σ a_n = ", N[Sum[fostAmplitude[n], {n, 1, Infinity}], 10],
       " (= 1, satisfies χ(0) = 0)"];
Print[];

(* === Compute α_n moments for Cauer extraction === *)
(* α_n = Σ_k a_k × τ_k^(n+1) × (-1)^n *)
(* Note: in our convention, χ(s) = -1 + Σ a_k/(1+sτ_k), and we want Cauer-I
         expansion of (1 - χ(s)) or similar to get the Cauer ladder.
         The α_n moments are derivatives at s=0. *)

(* For numerical Hankel-Padé, sum truncated Foster series: *)
nModes = 100;     (* modes to include in Foster sum *)
nMoments = 20;    (* moments to compute *)

alphas = Table[
  (-1)^k Sum[fostAmplitude[n] tauStoll[n]^(k + 1), {n, 1, nModes}],
  {k, 0, nMoments - 1}];

Print["4. α_n moments (from truncated Stoll Foster, n_modes=", nModes, "):"];
Print[Table[
  Row[{"   α_", k, " = ", ScientificForm[N[alphas[[k+1]], 10]]}],
  {k, 0, 5}] // TableForm];
Print[];

(* === Cauer-I extraction via continued fraction inversion === *)
(* From Taylor coefficients α_n of f(s) = α_0 + α_1 s + α_2 s² + ...:
   Continued fraction expansion at s=0 gives Cauer-I rungs (R_0, L_1, R_2, ...).
   Algorithm:
     p_0 = 1/α_0  (= "first rung")
     residue = 1/(f(s)) - p_0 (with leading term subtracted)
     ... iterate
*)

invertTaylor[c_List] := Module[{n, e, k, j},
  n = Length[c];
  e = Table[0, {n}];
  e[[1]] = 1/c[[1]];
  Do[
    e[[k + 1]] = -Sum[c[[j + 1]] e[[k - j + 1]], {j, 1, k}]/c[[1]],
    {k, 1, n - 1}];
  e
];

cauerExtract[cTaylor_List, maxStages_] := Module[
  {c, pList, e, stage},
  c = cTaylor;
  pList = {};
  Do[
    If[Length[c] < 2 || Abs[c[[1]]] < 10^-300, Return[pList]];
    e = invertTaylor[c];
    pList = Append[pList, e[[1]]];
    c = Drop[e, 1];
    , {stage, 1, maxStages}];
  pList
];

(* Apply to alphas *)
pCauer = cauerExtract[alphas, nMoments - 1];
Print["5. Cauer-I ladder extraction from Stoll α_n moments:"];
Print["   Number of p-coefficients: ", Length[pCauer]];
Print["   Number of (R, L) pairs:   ", Floor[Length[pCauer]/2]];
Print[];

(* Convert p-coefficients to R, L pairs *)
(* p[2k] = R_{2k}, p[2k+1] = 1/L_{2k+1} *)
nPairs = Floor[Length[pCauer]/2];
Print["6. Cauer-I ladder (R_{2k}, L_{2k+1}, τ_pair = L/R):"];
Print[
  Row[{StringPadLeft["k", 4], " | ", StringPadLeft["R_2k", 18], " | ",
       StringPadLeft["L_2k+1", 18], " | ", StringPadLeft["τ_pair [μs]", 18]}]];
Do[
  Module[{R2k, Lin, L, tauUs},
    R2k = pCauer[[2 k + 1]];
    Lin = pCauer[[2 k + 2]];
    L = If[Abs[Lin] > 10^-300, 1/Lin, Indeterminate];
    tauUs = If[NumericQ[L] && R2k != 0, L / R2k 10^6, Indeterminate];
    Print[
      Row[{StringPadLeft[ToString[k], 4], " | ",
           StringPadLeft[ScientificForm[N[R2k, 8]], 18], " | ",
           StringPadLeft[ScientificForm[N[L, 8]], 18], " | ",
           StringPadLeft[ScientificForm[N[tauUs, 8]], 18]}]];
  ], {k, 0, nPairs - 1}];

Print[];
Print["==== Comparison: τ_pair vs Stoll Foster τ_n ===="];
Print["Note: stage k τ_pair is Cauer rung k, NOT Foster pole k+1."];
Print["For low k, Cauer τ ≈ leading Foster τ + correction."];

(* === Comparison reference === *)
Print[];
Print["=" <> StringRepeat["=", 70]];
Print["Reference: Hiruma+Kelvin (FEM axisym ORDER=3, mesh.Curve(3)):"];
Print["   stage 0: 728.85 μs (vs Stoll τ_1 = 738.48, gap -1.3%)"];
Print["   stage 1: 171.51 μs (Cauer rung k=1 — different from Stoll τ_2)"];
Print["Reference: Kameari+Kelvin (FEM axisym):"];
Print["   stage 0: 694.14 μs (vs Stoll τ_1 = 738.48, gap -6.0%)"];
Print["   stage 1: 154.60 μs (Cauer rung k=1)"];

(* sphere_analytical_cln_highstage.wls
   High-precision (60-digit) Cauer-I extraction for sphere from Stoll
   Bessel analytical Foster spectrum. Goes to ~30 stages.

   Uniform B_0 = 1 T applied to Cu sphere (a=10mm, σ=58e6).

   Stoll closed form (= analytical BEM-Foster for the sphere):
     τ_n = μ_0 σ a² / (n² π²),     n = 1, 2, ...
     a_n = 6 / (n² π²)             (Foster amplitudes)

   Joule loss (1T applied):
     R_0 = 15 / (2π σ B_0² a⁵)

   Cauer-I extraction: Hankel-Padé continued-fraction inversion of the
   Stoll Taylor-series moments
     α_k = (-1)^k Σ_n a_n × τ_n^(k+1).
*)

prec = 240;      (* working precision in digits *)
nModes = 12000;  (* Stoll modes summed for each moment *)
nMoments = 200;  (* Taylor moments computed *)
maxStages = 60;  (* Cauer (R,L) pairs requested *)

(* === Physical parameters === *)
mu0 = 4 Pi 10^-7;
sigma = SetPrecision[58 10^6, prec];
B0 = SetPrecision[1, prec];
a = SetPrecision[10/1000, prec];

Print["================================================================"];
Print[" Sphere analytical CLN (high-stage)"];
Print["   a = ", N[a 1000, 6], " mm,  σ = ", N[sigma, 6], " S/m,  B_0 = ", N[B0, 6], " T"];
Print["   working precision = ", prec, " digits, modes = ", nModes,
      ", moments = ", nMoments, ", stages = ", maxStages];
Print["================================================================"];

R0 = 15/(2 Pi sigma B0^2 a^5);
Print[];
Print["1. R_0 from Joule loss (1T 印加, ω² で割った損失逆数):"];
Print["   R_0 = 15 / (2π σ B_0² a⁵) = ", N[R0, 12]];

(* === Stoll spectrum (Foster) === *)
tauStoll[n_] := SetPrecision[mu0 sigma a^2/(n^2 Pi^2), prec];
fostAmplitude[n_] := SetPrecision[6/(n^2 Pi^2), prec];

Print[];
Print["2. Stoll Foster pole spectrum (closed form, = analytical BEM-Foster):"];
Print[Table[
  Row[{"   τ_", n, " = ", N[tauStoll[n] 10^6, 12], " μs"}],
  {n, 1, 10}] // TableForm];

(* === Taylor moments of f(s) = Σ a_n τ_n / (1 + sτ_n) === *)
(* d^k/ds^k at s=0:  α_k = (-1)^k Σ a_n τ_n^(k+1) (no factorial here) *)

alphas = Table[
  (-1)^k Sum[fostAmplitude[n] tauStoll[n]^(k + 1), {n, 1, nModes}],
  {k, 0, nMoments - 1}];

Print[];
Print["3. First α_k (high precision):"];
Do[
  Print["   α_", k, " = ", ScientificForm[N[alphas[[k+1]], 12]]],
  {k, 0, 5}];

(* === Hankel-Padé / continued-fraction inversion === *)
invertTaylor[c_List] := Module[{n, e, k, j},
  n = Length[c];
  e = Table[0, {n}];
  e[[1]] = 1/c[[1]];
  Do[
    e[[k + 1]] = -Sum[c[[j + 1]] e[[k - j + 1]], {j, 1, k}]/c[[1]],
    {k, 1, n - 1}];
  e
];

cauerExtract[cTaylor_List, maxS_] := Module[
  {c, pList, e, stage},
  c = cTaylor;
  pList = {};
  Do[
    If[Length[c] < 2 || Abs[c[[1]]] < 10^-(prec - 5),
       Print["   [stop at stage ", stage - 1, ": numerical floor]"];
       Return[pList]];
    e = invertTaylor[c];
    pList = Append[pList, e[[1]]];
    c = Drop[e, 1];
    , {stage, 1, maxS}];
  pList
];

pCauer = cauerExtract[alphas, 2 maxStages];

nPairs = Floor[Length[pCauer]/2];
Print[];
Print["4. Cauer-I ladder (R_{2k}, L_{2k+1}, τ_pair = L/R):"];
Print[];
Print["    k |       R_2k        |       L_2k+1      |  τ_pair [μs]"];
Print["   ---+-------------------+-------------------+---------------"];
Do[
  Module[{R2k, Lin, L, tauUs},
    R2k = pCauer[[2 k + 1]];
    Lin = pCauer[[2 k + 2]];
    L = If[Abs[Lin] > 10^-(prec - 10), 1/Lin, Indeterminate];
    tauUs = If[NumericQ[L] && R2k =!= 0, L/R2k 10^6, Indeterminate];
    Print[
      Row[{StringPadLeft[ToString[k], 5], " | ",
           StringPadLeft[ToString[ScientificForm[N[R2k, 10], NumberFormat -> (Row[{#1, "e", #3}] &)]], 17], " | ",
           StringPadLeft[ToString[ScientificForm[N[L, 10], NumberFormat -> (Row[{#1, "e", #3}] &)]], 17], " | ",
           StringPadLeft[ToString[N[tauUs, 10]], 14]}]];
  ], {k, 0, nPairs - 1}];

(* === Identify the largest reliable stage (no Indeterminate / Infinity) === *)
isFinite[x_] := NumericQ[x] && Abs[x] < 10^200 && Abs[x] > 10^-200;
nReliable = nPairs;
Do[
  If[Length[pCauer] >= 2 k + 2,
    If[!isFinite[pCauer[[2 k + 1]]] || !isFinite[pCauer[[2 k + 2]]],
      nReliable = k; Break[]]],
  {k, 0, nPairs - 1}];

Print[];
Print["Reliable Cauer stages with prec=", prec, " : k = 0..", nReliable - 1];

(* === Save high-precision results to JSON (reliable stages only) === *)
results = <|
  "params" -> <|"a_m" -> N[a, 20], "sigma_Spm" -> N[sigma, 20],
                "B0_T" -> N[B0, 20], "mu0" -> N[mu0, 20]|>,
  "R0" -> N[R0, 20],
  "n_reliable" -> nReliable,
  "stoll_tau_us" -> Table[N[tauStoll[n] 10^6, 16], {n, 1, 60}],
  "stoll_a_n"   -> Table[N[fostAmplitude[n], 16], {n, 1, 60}],
  "alpha_taylor" -> Table[N[alphas[[k+1]], 16], {k, 0, nMoments - 1}],
  "cauer_R" -> Table[N[pCauer[[2 k + 1]], 16], {k, 0, nReliable - 1}],
  "cauer_L_inv" -> Table[N[pCauer[[2 k + 2]], 16], {k, 0, nReliable - 1}],
  "cauer_L" -> Table[N[1/pCauer[[2 k + 2]], 16], {k, 0, nReliable - 1}],
  "cauer_tau_us" -> Table[N[(1/pCauer[[2 k + 2]])/pCauer[[2 k + 1]] 10^6, 16],
                          {k, 0, nReliable - 1}]
|>;

SetDirectory[NotebookDirectory[] /. _NotebookDirectory -> DirectoryName[$InputFileName]];
outPath = FileNameJoin[{Directory[], "sphere_analytical_cln_highstage.json"}];
Print[];
Print["Writing to: ", outPath];
Export[outPath, results, "JSON"];
Print["File exists after Export: ", FileExistsQ[outPath]];
If[FileExistsQ[outPath], Print["Size: ", FileByteCount[outPath], " bytes"]];

Print[];
Print["================================================================"];
Print[" Saved: sphere_analytical_cln_highstage.json"];
Print["================================================================"];

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  polarizability_tensor_3D.wls

  Phase 4 A1: 3D polarizability tensor with demagnetization factors
  for a rectangular cuboid conductor.  This addresses the
  demagnetization-factor gap identified in the Phase 3 B.2 NGSolve
  cross-check (§V.H honest scope note).

  Mathematical formulation
  ------------------------
  For a cuboid Omega = [0,a] x [0,b] x [0,c] in applied uniform B in
  direction i, the induced magnetic moment is

    m_i(s) = alpha_i(s) * B_i_applied / mu_0
    alpha_i(s) = V * chi(s) / (1 + N_i * chi(s))

  where:
    V = a b c                            (cuboid volume)
    N_i = demagnetization factor along axis i (Aharoni 1998)
    N_x + N_y + N_z = 1
    chi(s) = Y_cuboid(s) / (sigma V) - 1   (intrinsic susceptibility)

  chi(s) limits:
    chi(0)        = sigma V / (sigma V) - 1 = 0        (no eddy at DC)
    chi(infinity) = 0 - 1 = -1                          (PEC)

  alpha_i(s) limits:
    alpha_i(0)        = 0
    alpha_i(infinity) = V * (-1) / (1 - N_i) = -V/(1 - N_i)

  Aharoni 1998 formula for demagnetization factor of a rectangular
  prism with sides 2a, 2b, 2c centred at origin, along z axis:
    See Aharoni, J. Appl. Phys. 83 (1998) 3432.
    N_z = (1/(pi)) * (... complicated expression in terms of a, b, c)

  For our 5x2x1 mm cuboid, we use the well-known approximate values.
  The exact Aharoni formula is implemented below.

  Run: wolframscript -file polarizability_tensor_3D.wls
*)

ClearAll[a, b, c, sigma, mu, dParam, basisN];

a       = 5*^-3;
b       = 2*^-3;
c       = 1*^-3;
sigma   = 5.80*^7;
mu      = 4 Pi 1*^-7;
dParam  = 2 Pi 1*^5;
basisN  = 3;

VCub    = a b c;
SCub    = 2 (a b + b c + c a);
KsibcCub = SCub Sqrt[sigma/mu];

Print["=== polarizability_tensor_3D.wls ==="];
Print["3D polarizability tensor with Aharoni demagnetization factors"];
Print["Cuboid: ", a 1000, " x ", b 1000, " x ", c 1000, " mm Cu, V = ", N[VCub, 6], " m^3"];
Print[""];

(* === Aharoni 1998 demagnetization factor formula ======================== *)
(* For a rectangular prism with sides 2A, 2B, 2C centred at origin,
   the demagnetization factor along z (the C axis) is given by
   Aharoni's closed form. Here we use sides (a, b, c) = (2A, 2B, 2C). *)

aharoniNz[ax_, bx_, cx_] := Module[
  {A = ax/2, B = bx/2, C = cx/2, R, Rab, Rac, Rbc},
  R   = Sqrt[A^2 + B^2 + C^2];
  Rab = Sqrt[A^2 + B^2];
  Rac = Sqrt[A^2 + C^2];
  Rbc = Sqrt[B^2 + C^2];
  (1/Pi) (
    (B^2 - C^2)/(2 B C) Log[(R - A)/(R + A)] +
    (A^2 - C^2)/(2 A C) Log[(R - B)/(R + B)] +
    B/(2 C) Log[(Rab + A)/(Rab - A)] +
    A/(2 C) Log[(Rab + B)/(Rab - B)] +
    C/(2 A) Log[(Rbc - B)/(Rbc + B)] +
    C/(2 B) Log[(Rac - A)/(Rac + A)] +
    2 ArcTan[A B / (C R)] +
    (A^3 + B^3 - 2 C^3)/(3 A B C) +
    (A^2 + B^2 - 2 C^2)/(3 A B C) R +
    C/(A B) (Rac + Rbc) -
    (Rab^3 + Rbc^3 + Rac^3)/(3 A B C)
  )];

(* By symmetry, N_x = aharoni(b, c, a), N_y = aharoni(a, c, b), N_z = aharoni(a, b, c) *)
Nx = aharoniNz[b, c, a];
Ny = aharoniNz[a, c, b];
Nz = aharoniNz[a, b, c];

Print["Aharoni demagnetization factors:"];
Print["  N_x (along 5 mm axis) = ", N[Nx, 6]];
Print["  N_y (along 2 mm axis) = ", N[Ny, 6]];
Print["  N_z (along 1 mm axis) = ", N[Nz, 6]];
Print["  Sum N_x+N_y+N_z       = ", N[Nx + Ny + Nz, 8], "  (target 1)"];
Print[""];

(* === Per-cuboid Foster building block (from §V.B) ====================== *)
Mmax = 13;
modeList = Flatten[Table[{m, n, p},
  {m, 1, Mmax, 2}, {n, 1, Mmax, 2}, {p, 1, Mmax, 2}], 2];

g2MNP[m_, n_, p_] := 512 a b c / ((m n p)^2 Pi^6);
lambdaMNP[m_, n_, p_] := (m Pi/a)^2 + (n Pi/b)^2 + (p Pi/c)^2;
tauMNP[m_, n_, p_]    := mu sigma / lambdaMNP[m, n, p];

g2Vec  = N[Table[g2MNP[mn[[1]], mn[[2]], mn[[3]]], {mn, modeList}], 30];
tauVec = N[Table[tauMNP[mn[[1]], mn[[2]], mn[[3]]], {mn, modeList}], 30];

YcubFoster[s_] := sigma Total[g2Vec / (1 + s tauVec)];
YcubSchur[s_]  := YcubFoster[s] + KsibcCub Sqrt[s] / (s + dParam);

(* === Intrinsic susceptibility chi(s) =================================== *)
chiFoster[s_] := YcubFoster[s] / (sigma VCub) - 1;
chiSchur[s_]  := YcubSchur[s] / (sigma VCub) - 1;

(* Verify limits *)
Print["chi(s) sanity (Foster basis):"];
Print["  chi(0+)        = ", N[Re[chiFoster[I 2 Pi 0.01]], 6], "  (target 0)"];
Print["  chi(infinity)  = ", N[Re[chiFoster[I 2 Pi 1*^14]], 6], "  (target -1)"];
Print[""];

(* === Polarizability tensor: alpha_i = V chi/(1 + N_i chi) per axis ===== *)
alphaTensorFoster[s_, Nfac_] := VCub chiFoster[s] / (1 + Nfac chiFoster[s]);
alphaTensorSchur[s_, Nfac_]  := VCub chiSchur[s]  / (1 + Nfac chiSchur[s]);

(* === PEC limits along each axis ======================================== *)
Print["alpha_i(s -> infinity) at PEC limit:"];
With[{sInf = I 2 Pi 1*^14},
  Print["  alpha_x(inf) = -V/(1-N_x) = ", N[-VCub/(1 - Nx), 8],
        "  Foster:  ", N[Re[alphaTensorFoster[sInf, Nx]], 8]];
  Print["  alpha_y(inf) = -V/(1-N_y) = ", N[-VCub/(1 - Ny), 8],
        "  Foster:  ", N[Re[alphaTensorFoster[sInf, Ny]], 8]];
  Print["  alpha_z(inf) = -V/(1-N_z) = ", N[-VCub/(1 - Nz), 8],
        "  Foster:  ", N[Re[alphaTensorFoster[sInf, Nz]], 8]];
];
Print[""];

(* === Wall-band response per axis ======================================== *)
Print["Polarizability tensor per-axis response across wall band:"];
Print[""];
Print[StringPadRight["f [Hz]", 12] <>
      StringPadRight["alpha_x", 20] <>
      StringPadRight["alpha_y", 20] <>
      "alpha_z"];
Print[StringRepeat["-", 75]];

Do[
  With[{omega = 2 Pi (10.0^logf), s = I 2 Pi (10.0^logf)},
    With[{ax = alphaTensorFoster[s, Nx],
          ay = alphaTensorFoster[s, Ny],
          az = alphaTensorFoster[s, Nz]},
      Print["f=1e", logf, "      ",
            StringPadRight[ToString[N[ax, 5]], 20],
            StringPadRight[ToString[N[ay, 5]], 20],
            N[az, 5]]
    ]],
  {logf, {2, 4, 5, 6, 7, 8, 10, 12}}];

(* === Cross-check: m_y at PEC vs NGSolve =============================== *)
Print[""];
Print["Cross-check vs NGSolve FEM (per-cuboid in B_y=1 T):"];
With[{B0 = 1.0, omega = 2 Pi 1*^7, s = I 2 Pi 1*^7},
  With[{alphay = alphaTensorFoster[s, Ny]},
    With[{mPredicted = alphay B0 / mu},
      Print["  f = 10^7 Hz, applied B_y = 1 T"];
      Print["  alpha_y(s) (Foster tensor)   = ", N[alphay, 6]];
      Print["  m_y_predicted = alpha_y * B / mu_0 = ", N[mPredicted, 6], " A m^2"];
      Print["  NGSolve B.2 (per-cuboid) gave    m_y ~ -7.17j A m^2"];
      Print["  Ratio predicted/NGSolve       = ", N[mPredicted/(-7.17 I), 4]]
    ]];
  Print["Note: NGSolve at f=10^7 is under-resolved (mesh maxh=0.5mm,"];
  Print["      skin depth=21um, c/delta=48); proper FEM cross-check"];
  Print["      requires skin-graded mesh.  See B.2 honest scope note."];
];

(* === Trace identity ====================================================== *)
Print[""];
Print["Trace identity (sum over principal axes):"];
With[{sProbe = I 2 Pi 1*^14},
  With[{trace = alphaTensorFoster[sProbe, Nx] +
                alphaTensorFoster[sProbe, Ny] +
                alphaTensorFoster[sProbe, Nz]},
    Print["  alpha_x + alpha_y + alpha_z (s=inf) = ", N[Re[trace], 6]];
    Print["  Conventional bound: -3 V = ", N[-3 VCub, 6]];
    Print["  Ratio (always <= -3V for diamag)    = ", N[Re[trace]/(-3 VCub), 6]]
  ]];

(* === CSV output ========================================================= *)
csvData = {{"f_Hz", "alpha_x_re", "alpha_x_im", "alpha_y_re", "alpha_y_im",
            "alpha_z_re", "alpha_z_im"}};
Do[
  With[{omega = 2 Pi (10.0^logf), s = I 2 Pi (10.0^logf)},
    With[{ax = alphaTensorFoster[s, Nx],
          ay = alphaTensorFoster[s, Ny],
          az = alphaTensorFoster[s, Nz]},
      AppendTo[csvData,
        {10.0^logf, N[Re[ax], 8], N[Im[ax], 8],
                    N[Re[ay], 8], N[Im[ay], 8],
                    N[Re[az], 8], N[Im[az], 8]}]
    ]],
  {logf, {2, 3, 4, 5, 6, 7, 8, 10, 12}}];

Export["polarizability_tensor_3D.csv", csvData, "CSV"];
Print[""];
Print["Wrote polarizability_tensor_3D.csv"];

Print[""];
Print["=== polarizability_tensor_3D.wls DONE ==="];

#!/usr/bin/env wolframscript
(* ::Package:: *)

(*
  rect2D_schur_F.wls

  3-axis ROM evaluation for the 2D infinite-length rectangular prism
  scalar diffusion problem.  Parallels cuboid3D_schur_F.wls (3D)
  and slab_cpe_schur.wls (1D).  This is the journal section V.0
  verification, cross-checking against Nagamine et al., "Verified
  Numerical Computations of the Cauer Network Representation of a
  Square Prism Conductor," J. Magn. Magn. Mater. (2026, JJIAM
  submission). The Nagamine reference provides interval-arithmetic
  bounds on Cauer rungs {L_n, R_n} for the square case (a = b).

  Reference problem (per-unit-length, infinite z extent):
     -Laplacian u + s mu sigma u = -s mu sigma   on  Omega = [0,a]x[0,b]
     u = 0  on  dOmega
     u_ext = 1

  Foster spectrum (odd m,n only; even modes uncouple from uniform src):
     lambda_{mn} = (m pi/a)^2 + (n pi/b)^2
     tau_{mn}    = mu sigma / lambda_{mn}
     g_{mn}^2    = 64 sigma a b / ((m n)^2 pi^4)     (per-unit-length)

  Foster admittance (per-unit-length, S/m):
     Y(s) = Sum_{odd m,n} g_{mn}^2 / (1 + s tau_{mn})
     Y(0) = sigma a b                         (DC, Nagamine eq.20)
     Y(s) -> K_SIBC / sqrt(s) at large s
     K_SIBC = 2(a+b) sqrt(sigma/mu)           (perimeter formula)

  ROMs compared on three axes (A wall / B Taylor / C asymptote):
     CLN_N3 / CLN_N10 at s_0 = 0  (canonical Cauer Pade)
     Schur-F (CLN_N3 + 1 sqrt(s) block, basis 4) -- the test

  Run: wolframscript -file rect2D_schur_F.wls
*)

ClearAll[a, b, sigma, mu, nu, Mmax];

(* Geometry: 2D square prism cross-section, a = b = 5 mm Cu.
   Matches Nagamine et al. 2026 JJIAM "square case" with a = 5 mm. *)
a       = 5*^-3;
b       = 5*^-3;
sigma   = 5.96*^7;       (* Cu (matches digest cylinder; Nagamine uses sigma = 5.8e7) *)
mu      = 4 Pi 1*^-7;
nu      = 1/mu;

(* SIBC constant via cross-section perimeter *)
Pperim   = 2 (a + b);
KSIBC2D  = Pperim Sqrt[sigma/mu];

Print["=== rect2D_schur_F.wls ==="];
Print["a = ", N[a 1000], " mm, b = ", N[b 1000], " mm"];
Print["P = 2(a+b) = ", N[Pperim 1000, 6], " mm"];
Print["sigma = ", sigma, " S/m, mu = ", N[mu, 6], " H/m"];
Print["K_SIBC^{2D-rect} = P sqrt(sigma/mu) = ", N[KSIBC2D, 8]];

(* === Foster spectrum truncation ======================================== *)
(* Odd modes m,n = 1,3,5,...,Mmax. Total modes = ((Mmax+1)/2)^2 *)
Mmax = 99;   (* 50 x 50 = 2500 modes; DC converges to ~5 digits and
                f=1e9 Hz asymptote captures the bulk of the SIBC tail.
                For full 12-digit accuracy use Mmax=999 (250000 modes;
                ~30 s runtime), tracked in Nagamine cross-check. *)
oddRange = Range[1, Mmax, 2];

(* Foster eigenvalues, time constants, couplings (per-unit-length).
   g^2 ABSORBS sigma to match slab/cuboid convention:
   Y(s) = Sum g^2/(1 + s*tau) *)
lamMN[m_, n_] := N[(m Pi/a)^2 + (n Pi/b)^2];
tauMN[m_, n_] := mu sigma / lamMN[m, n];
g2MN[m_, n_]  := N[64 sigma a b / ((m n)^2 Pi^4)];

(* Enumerate modes (flat index) *)
modeList = Flatten[Table[{m, n}, {m, oddRange}, {n, oddRange}], 1];
Nmodes   = Length[modeList];
lamVec   = N[Table[lamMN[mn[[1]], mn[[2]]], {mn, modeList}]];
tauVec   = mu sigma / lamVec;
g2Vec    = N[Table[g2MN[mn[[1]], mn[[2]]], {mn, modeList}]];

Print["Nmodes = ", Nmodes, " (m,n odd up to ", Mmax, ")"];

(* Verify DC: Y(0) = Sum g^2 should equal sigma a b *)
yDC = Total[g2Vec];
Print["Y(0) Foster sum   = ", N[yDC, 8]];
Print["Y(0) analytic     = sigma a b = ", N[sigma a b, 8]];
Print["DC convergence    = ", N[yDC/(sigma a b), 8], " (target 1)"];

(* === Modal operators in Foster basis ==================================== *)
LambdaM  = N[DiagonalMatrix[lamVec]];
sigmaM   = N[sigma IdentityMatrix[Nmodes]];
Imat     = N[IdentityMatrix[Nmodes]];

Kmodal[s_] := nu LambdaM + sigma s Imat;
K0matrix   = Kmodal[0];

(* Source vector: uniform u_ext = 1 -> RHS proportional to projection
   onto each mode.  Match slab/cuboid convention: b_k ~ sqrt(g_k^2/tau_k) *)
bvec = N[Sqrt[g2Vec / tauVec]];

(* Exact Foster admittance (truncated double sum, the "ground truth") *)
YExactFoster[omega_] := Module[{s = I omega},
  Total[g2Vec / (1 + s tauVec)]];

(* === K_0 inner product utilities ======================================= *)
K0Inner[u_, v_]     := u . K0matrix . v;
K0MGS[vIn_, basis_] := Module[{v = vIn, ai, cc},
  Do[ai = basis[[i]];
     cc = K0Inner[ai, v];
     v  = v - cc ai, {i, 1, Length[basis]}];
  v];
K0Normalise[v_] := Module[{nrm = Sqrt[Re[K0Inner[v, v]]]},
  If[nrm < 1*^-300, v, v/nrm]];

(* === CLN Krylov basis at s = s0 (canonical Cauer Pade at s=0) ========= *)
buildCLNbasis[s0_, M_] := Module[{Q = {}, vk, KsInv},
  KsInv = Inverse[Kmodal[s0]];
  vk    = KsInv . (sigmaM . bvec);
  vk    = K0Normalise[vk];
  AppendTo[Q, vk];
  Do[vk = KsInv . (sigmaM . Last[Q]);
     vk = K0MGS[vk, Q];
     vk = K0Normalise[vk];
     AppendTo[Q, vk], {M - 1}];
  Q];

(* === Reduced admittance (no Schur) ==================================== *)
YReducedFromBasis[Qlist_, omega_] := Module[{Q, Kr, Qb},
  Q  = Qlist;
  Kr = Q . Kmodal[I omega] . Transpose[Q];
  Qb = Q . bvec;
  sigma (Qb . LinearSolve[Kr, Qb])];

(* === Schur-F 1x1 termination ========================================== *)
(* Y_R(s) = Y_CLN(s) + K_SIBC sqrt(s) / (s + d) *)
YReducedSchurF[Qlist_, omega_, d_] := Module[{yCLN, s, yExtra},
  yCLN   = YReducedFromBasis[Qlist, omega];
  s      = I omega;
  yExtra = KSIBC2D Sqrt[s] / (s + d);
  yCLN + yExtra];

(* === Sanity: DC and asymptote of exact Foster ========================= *)
Print[""];
Print["=== Sanity check on exact Foster Y(s) ==="];
yHF = YExactFoster[2 Pi 1*^9];
KempHF = Abs[yHF] Sqrt[2 Pi 1*^9];
Print["|Y(2pi 1e9)| sqrt(omega) num = ", N[KempHF, 8]];
Print["K_SIBC^{2D-rect} formula     = ", N[KSIBC2D, 8]];
Print["asymptote ratio (num/formula) = ", N[KempHF / KSIBC2D, 6]];
Print["  (NOTE: 121 modes is not enough at 1e9 Hz; this checks the trend)"];

(* === Extract first few Cauer rungs (L_n, R_n) for Nagamine cross-check  *)
(* Lanczos tridiagonalization of (K0^{-1} sigma) on b = bvec yields the
   tridiagonal (alpha_i, beta_i), and the Cauer rungs come from the
   Stieltjes recursion:
       L_{2k-1} = 1 / (alpha_k - L_{2k-3}^{-1} (1/R_{2k-2}))   [odd]
       R_{2k}   = beta_k^2 L_{2k-1} L_{2k+1}                     [even]
   For verification against Nagamine, we use the simpler "moment-based"
   extraction: Taylor coefficients c_k of Y(s) at s=0 -> Hankel-Pade
   QD algorithm -> Cauer rungs.
*)
Print[""];
Print["=== Cauer rung extraction (for Nagamine cross-check) ==="];

(* Compute Taylor moments c_k = (-1)^k * Sum_m g_m^2 * tau_m^k *)
moments[K_] := Table[
  N[Sum[g2Vec[[i]] (-tauVec[[i]])^k, {i, 1, Nmodes}], 30],
  {k, 0, K-1}];

cMoments = moments[20];
Print["First 5 Taylor coeffs c_k of Y(s) at s=0:"];
Do[Print["  c_", k, " = ", N[cMoments[[k+1]], 8]], {k, 0, 4}];

(* Cauer rungs via QD algorithm on the Hankel matrix of moments.
   For verified comparison with Nagamine: he extracts L_1, R_2, L_3, R_4,
   ... using interval arithmetic on the same Foster moments.  Here we
   use machine-precision Lanczos as the cross-check baseline.
   FULL QD implementation in qd_extract.m4 (TODO: port to Mathematica).
   For now, output the moments themselves -- Nagamine's Table 2 lists
   moment bounds we can directly compare. *)
Export["rect2D_schur_F_moments.csv",
  Prepend[Table[{k, cMoments[[k+1]]}, {k, 0, Length[cMoments]-1}],
         {"k", "c_k"}], "CSV"];
Print["Wrote rect2D_schur_F_moments.csv (", Length[cMoments],
      " moments for Nagamine cross-check)"];

(* === Build ROMs ======================================================== *)
Print[""];
Print["=== Building ROMs ==="];
QCLN3   = buildCLNbasis[0, 3];
QCLN10  = buildCLNbasis[0, 10];
Print["  CLN_N3   basis size = ", Length[QCLN3]];
Print["  CLN_N10  basis size = ", Length[QCLN10]];

(* === Frequency sweep + CSV export ===================================== *)
fHzList = N[10^Subdivide[0, 9, 90]];   (* 91 points, 1 Hz to 1e9 Hz *)

dSchur = N[2 Pi 1*^5];   (* digest crossover; tune if wall-band fit is poor *)
Print[""];
Print["=== Frequency sweep (1 Hz - 1e9 Hz, 91 points) ==="];
Print["Schur-F crossover d/(2pi) = ", N[dSchur/(2 Pi), 6], " Hz"];

results = Table[
  Module[{omega = 2 Pi f, yEx, yCLN3, yCLN10, ySchur, kref},
    omega  = 2 Pi f;
    yEx    = YExactFoster[omega];
    yCLN3  = YReducedFromBasis[QCLN3,  omega];
    yCLN10 = YReducedFromBasis[QCLN10, omega];
    ySchur = YReducedSchurF[QCLN3, omega, dSchur];
    kref   = KSIBC2D / Sqrt[omega];
    {f, Abs[yEx], Abs[yCLN3], Abs[yCLN10], Abs[ySchur], kref}],
  {f, fHzList}];

Export["rect2D_schur_F.csv",
  Prepend[results,
   {"f_Hz", "Y_exact", "Y_CLN_N3", "Y_CLN_N10", "Y_Schur_F_b4", "K_div_sqrts"}],
  "CSV"];
Print["Wrote rect2D_schur_F.csv (", Length[results], " rows)"];

(* === 3-axis summary ==================================================== *)
Print[""];
Print["=== 3-axis summary (square case a=b=5mm Cu) ==="];

(* A-axis: wall band peak rel err *)
wallMask = Select[Range[Length[fHzList]],
  1*^5 <= fHzList[[#]] <= 1*^7 &];
walls = {};
Do[Module[{label, idx, name = labelpair[[2]], col = labelpair[[1]]},
  idx = col;
  Module[{errs = Table[
       Abs[results[[k, idx]] - results[[k, 2]]] / Abs[results[[k, 2]]],
       {k, wallMask}]},
    AppendTo[walls,
      {name, N[100 Max[errs], 4]}]]],
  {labelpair, {{3, "CLN_N3"}, {4, "CLN_N10"}, {5, "Schur-F b4"}}}];
Print[StringPadRight["ROM", 16] <> "wall peak err"];
Do[Print[StringPadRight[w[[1]], 16] <> ToString[w[[2]]] <> " %"], {w, walls}];

(* C-axis: asymptote ratio at 1e9 Hz *)
idxC = First[Position[fHzList, _?(# >= 1*^9 &), 1, 1]][[1]];
Print[""];
Print["C-axis asymptote ratio r(1e9):"];
Print["  CLN_N3       = ", N[results[[idxC, 3]] / results[[idxC, 6]], 4]];
Print["  CLN_N10      = ", N[results[[idxC, 4]] / results[[idxC, 6]], 4]];
Print["  Schur-F b4   = ", N[results[[idxC, 5]] / results[[idxC, 6]], 4],
      "    (target 1)"];

Print[""];
Print["=== rect2D_schur_F.wls DONE ==="];

